import com.farmrunautopilot.access.UnlockSpotter;
import com.farmrunautopilot.settings.SettingsStore;
import com.farmrunautopilot.supply.BottomlessBucketTracker;
import com.farmrunautopilot.supply.Holdings;
import com.farmrunautopilot.supply.HoldingsTracker;
import com.farmrunautopilot.supply.ItemChargeTracker;
import com.farmrunautopilot.testing.TestRunner;
import com.farmrunautopilot.testing.TestView;
import com.farmrunautopilot.supply.SupplyLine;
import com.farmrunautopilot.supply.SupplyPlan;
import com.farmrunautopilot.route.RunOverrides;
import com.farmrunautopilot.route.RunPlan;
import com.farmrunautopilot.route.RunService;
import com.farmrunautopilot.run.GuidanceOverlay;
import com.farmrunautopilot.run.HighlightOverlay;
import com.farmrunautopilot.run.HintArrowController;
import com.farmrunautopilot.run.ItemHighlightOverlay;
import com.farmrunautopilot.run.RunSession;
import com.farmrunautopilot.run.RunView;
import com.farmrunautopilot.run.SceneTracker;
import com.farmrunautopilot.run.ShortestPathBridge;
import com.farmrunautopilot.run.SpellHighlightOverlay;
import com.farmrunautopilot.tracking.PatchTracker;
import com.farmrunautopilot.ui.FarmRunAutopilotPanel;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetModalMode;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Farm Run Autopilot",
	description = "Plans and guides combined tree, fruit tree and herb farming runs",
	tags = {"farming", "farm", "run", "herb", "tree", "fruit", "route", "planner"}
)
public class FarmRunAutopilotPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private PatchTracker patchTracker;

	@Inject
	private SettingsStore settings;

	@Inject
	private AccessChecker accessChecker;

	@Inject
	private PohDetector pohDetector;

	@Inject
	private HoldingsTracker holdingsTracker;

	@Inject
	private BottomlessBucketTracker bottomlessBucket;

	@Inject
	private ItemChargeTracker itemCharges;

	@Inject
	private UnlockSpotter unlockSpotter;

	@Inject
	private TestRunner testRunner;

	@Inject
	private ShortestPathBridge shortestPath;

	@Inject
	private RunService runService;

	@Inject
	private RunOverrides runOverrides;

	@Inject
	private ClientThread clientThread;

	@Inject
	private FarmBankTab farmBankTab;

	@Inject
	private RunSession runSession;

	@Inject
	private GuidanceOverlay guidanceOverlay;

	@Inject
	private HighlightOverlay highlightOverlay;

	@Inject
	private ItemHighlightOverlay itemHighlightOverlay;

	@Inject
	private SpellHighlightOverlay spellHighlightOverlay;

	@Inject
	private SceneTracker sceneTracker;

	@Inject
	private HintArrowController hintArrow;

	@Inject
	private OverlayManager overlayManager;

	/** The session view last shown in the sidebar. */
	private RunView shownRunView;
	/** The holdings the Detected list last showed (a new object each time they change). */
	private Holdings shownHoldings;
	/** The guided test as the Run tab last showed it. */
	private TestView shownTestView = TestView.NONE;

	/** What the bank tab last showed: each line, amount needed and colour (not exact counts held). */
	private String bankTabContents = "";

	private final Runnable onSettingsReloaded = () ->
	{
		rebuildSetupLater();
		// e.g. after "Reset to defaults" in the sidebar, which also clears the saved charges and bucket count
		clientThread.invoke(() ->
		{
			bottomlessBucket.reload();
			itemCharges.reload();
			holdingsTracker.markDirty();
		});
	};
	private final Runnable onSettingsSaved = () -> runService.markDirty();

	private FarmRunAutopilotPanel panel;
	private NavigationButton navButton;

	private WorldPoint lastTickLocation;
	private boolean lastTickPostLogin;
	private int lastModalCloseTick;

	@Override
	protected void startUp() throws Exception
	{
		settings.load();
		// Read the bundled walking grid now, not on the client thread when a route is first planned
		WalkGrid.loaded();
		bottomlessBucket.reload();
		itemCharges.reload();
		accessChecker.requestRefresh();
		panel = injector.getInstance(FarmRunAutopilotPanel.class);
		settings.addListener(onSettingsReloaded);
		settings.addSaveListener(onSettingsSaved);
		clientThread.invoke(holdingsTracker::loadCaches);
		farmBankTab.startUp(runSession::bankSupplies, runSession::depositNow);
		overlayManager.add(guidanceOverlay);
		overlayManager.add(highlightOverlay);
		overlayManager.add(itemHighlightOverlay);
		overlayManager.add(spellHighlightOverlay);

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Farm Run Autopilot")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		log.debug("Farm Run Autopilot started");
	}

	@Override
	protected void shutDown() throws Exception
	{
		settings.removeListener(onSettingsReloaded);
		settings.removeSaveListener(onSettingsSaved);
		farmBankTab.shutDown();
		overlayManager.remove(guidanceOverlay);
		overlayManager.remove(highlightOverlay);
		overlayManager.remove(itemHighlightOverlay);
		overlayManager.remove(spellHighlightOverlay);
		itemHighlightOverlay.clearCache();
		clientThread.invoke(() ->
		{
			// A running guided test ends unreported and puts the player's settings back, as on logout
			testRunner.onLoggedOut();
			runSession.stop(false);
			// Also puts the player's own Shortest Path settings back
			shortestPath.clear();
			hintArrow.clear();
			sceneTracker.clear();
			pohDetector.reset();
		});
		shownRunView = null;
		clientToolbar.removeNavigation(navButton);
		panel.shutDown();
		navButton = null;
		panel = null;
		lastTickLocation = null;
		lastTickPostLogin = false;
		patchTracker.reset();
		accessChecker.reset();
		runService.reset();
		runOverrides.clear();
		log.debug("Farm Run Autopilot stopped");
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		// Patch states first, so the run guide and the plan see this tick's, not last tick's
		trackPatches();
		final Player me = client.getLocalPlayer();
		if (itemCharges.onGameTick(me != null ? me.getWorldLocation() : null))
		{
			holdingsTracker.markDirty();
		}
		pohDetector.onGameTick();
		if (accessChecker.onGameTick())
		{
			rebuildSetupLater();
			runService.markDirty();
		}
		if (runService.onGameTick())
		{
			final RunPlan plan = runService.getPlan();
			showPlanLater(plan, true);
		}
		// Detected (charges, leprechaun, bucket) follows what's held, even when the plan stays the same (a recharge)
		final Holdings held = holdingsTracker.getHoldings();
		if (held != shownHoldings)
		{
			shownHoldings = held;
			final FarmRunAutopilotPanel p = panel;
			if (p != null)
			{
				SwingUtilities.invokeLater(p::refreshDetected);
			}
		}

		runSession.onGameTick();
		// Redraw the bank tab when a line or its colour changes. The bank redraws itself on every withdrawal, but a
		// tick before the plan catches up, so without this it would show the previous step. During a run the tab
		// shows the part of the run being banked for, counted against what's held now.
		farmBankTab.onGameTick();
		final String contents = bankTabContents(runSession.bankSupplies()) + runSession.depositNow();
		if (!contents.equals(bankTabContents))
		{
			bankTabContents = contents;
			farmBankTab.refresh();
		}
		testRunner.onGameTick();
		hintArrow.update();
		final RunView runView = runSession.getView();
		final TestView testView = testRunner.getView();
		if (!testView.equals(shownTestView))
		{
			shownTestView = testView;
			showPlanLater(runService.getPlan(), client.getGameState() == GameState.LOGGED_IN);
		}
		if (!runView.equals(shownRunView))
		{
			if (shownRunView == null || shownRunView.getState() != runView.getState())
			{
				farmBankTab.setEnabled(runView.getState() != RunView.State.OFF);
			}
			shownRunView = runView;
			showPlanLater(runService.getPlan(), client.getGameState() == GameState.LOGGED_IN);
		}
	}

	/** Read the patches in range this tick (SPEC 9). */
	private void trackPatches()
	{
		// Patch varbits are only sent after leaving the post-login welcome screen
		final Widget motw = client.getWidget(InterfaceID.WelcomeScreen.MOTW);
		if (motw != null && !motw.isHidden())
		{
			lastTickPostLogin = true;
			return;
		}
		if (lastTickPostLogin)
		{
			lastTickPostLogin = false;
			return;
		}

		final WorldPoint location = lastTickLocation;
		final Player player = client.getLocalPlayer();
		lastTickLocation = player == null ? null : player.getWorldLocation();

		// Skip ticks where the player crossed a region boundary
		if (location == null || lastTickLocation == null || location.getRegionID() != lastTickLocation.getRegionID())
		{
			return;
		}

		if (patchTracker.update(location, client.getTickCount() - lastModalCloseTick))
		{
			runService.markDirty();
			final FarmRunAutopilotPanel p = panel;
			if (p != null)
			{
				SwingUtilities.invokeLater(p::refreshPatches);
			}
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getModalMode() != WidgetModalMode.NON_MODAL)
		{
			lastModalCloseTick = client.getTickCount();
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		// A guided test belongs to the account it started on
		testRunner.onLoggedOut();
		patchTracker.reset();
		accessChecker.reset();
		holdingsTracker.loadCaches();
		runService.reset();
		// Reloading notifies onSettingsReloaded, which rebuilds the settings tabs
		settings.load();
		bottomlessBucket.reload();
		itemCharges.reload();
		holdingsTracker.markDirty();
		final FarmRunAutopilotPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(p::refreshPatches);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			accessChecker.requestRefresh();
			holdingsTracker.markDirty();
			runService.reset();
		}
		else if (event.getGameState() == GameState.LOADING)
		{
			// Objects are spawned again once the new scene loads; NPCs nearby aren't, so keep those
			sceneTracker.clearObjects();
			pohDetector.onSceneLoading(client.getTopLevelWorldView().isInstance());
		}
		else if (event.getGameState() == GameState.HOPPING)
		{
			sceneTracker.clear();
			pohDetector.reset();
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			// A run being built or waiting to leave is dropped; one already timing carries on after relogging
			runSession.cancelIfNotRunning();
			// Give the player their own Shortest Path settings back while logged out; a run carrying on sends its walk
			// again after relogging
			shortestPath.clear();
			testRunner.onLoggedOut();
			sceneTracker.clear();
			pohDetector.reset();
			showPlanLater(RunPlan.EMPTY, false);
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		accessChecker.onStatChanged(event.getSkill(), event.getLevel());
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		holdingsTracker.onItemContainerChanged(event.getContainerId(), event.getItemContainer());
		if (event.getContainerId() == InventoryID.INV && bottomlessBucket.onInventoryChanged(event.getItemContainer()))
		{
			holdingsTracker.markDirty();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		holdingsTracker.onVarbitChanged(event.getVarbitId());
		accessChecker.onVarbitChanged(event.getVarbitId());
		if (bottomlessBucket.onVarbitChanged(event.getVarbitId())
			| itemCharges.onVarbitChanged(event.getVarbitId(), event.getValue()))
		{
			holdingsTracker.markDirty();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() == ChatMessageType.GAMEMESSAGE || event.getType() == ChatMessageType.SPAM)
		{
			final String message = Text.removeTags(event.getMessage());
			runSession.onChatMessage(message);
			if (bottomlessBucket.onChatMessage(message) | itemCharges.onChatMessage(message))
			{
				holdingsTracker.markDirty();
			}
			// After the trackers, so a guided test sees their new counts
			testRunner.onChatMessage(message);
		}
		else if (event.getType() == ChatMessageType.DIALOG
			&& itemCharges.onChatMessage(Text.removeTags(event.getMessage())))
		{
			// NPC lines, e.g. Soar Leader Pitri recharging the whistle
			holdingsTracker.markDirty();
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.POH_LOADING)
		{
			pohDetector.onHouseLoading();
		}
		farmBankTab.onWidgetLoaded(event);
	}

	@Subscribe
	public void onScriptCallbackEvent(ScriptCallbackEvent event)
	{
		farmBankTab.onScriptCallbackEvent(event);
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		farmBankTab.onScriptPreFired(event);
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		farmBankTab.onScriptPostFired(event);
	}

	// After other plugins, so withdraw clicks are re-pointed last
	@Subscribe(priority = -1)
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		runSession.onMenuOptionClicked(event);
		bottomlessBucket.onMenuOptionClicked(event);
		if (itemCharges.onMenuOptionClicked(event))
		{
			holdingsTracker.markDirty();
		}
		pohDetector.onMenuOptionClicked(event);
		farmBankTab.onMenuOptionClicked(event);
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		pohDetector.onObjectSpawned(event.getGameObject().getId());
		sceneTracker.onObjectSpawned(event.getGameObject());
		unlockSpotter.onObjectSpawned(event.getGameObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		sceneTracker.onObjectDespawned(event.getGameObject());
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		sceneTracker.onNpcSpawned(event.getNpc());
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		sceneTracker.onNpcDespawned(event.getNpc());
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!FarmRunAutopilotConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if ("itemColour".equals(event.getKey()))
		{
			itemHighlightOverlay.clearCache();
		}
		else if (FarmRunAutopilotConfig.OPEN_SIDEBAR_KEY.equals(event.getKey()))
		{
			// The config panel has no buttons and doesn't redraw a box we untick, so any click on it opens the sidebar
			SwingUtilities.invokeLater(() ->
			{
				if (navButton != null)
				{
					clientToolbar.openPanel(navButton);
				}
			});
		}
	}

	private static String bankTabContents(SupplyPlan plan)
	{
		final StringBuilder sb = new StringBuilder();
		for (SupplyLine line : plan.getLines())
		{
			sb.append(line.getName()).append('=').append(line.getNeed()).append(':').append(line.getStatus()).append(';');
		}
		return sb.toString();
	}

	private void showPlanLater(RunPlan plan, boolean loggedIn)
	{
		final FarmRunAutopilotPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(() -> p.updateRun(plan, loggedIn));
		}
	}

	private void rebuildSetupLater()
	{
		final FarmRunAutopilotPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(p::rebuildSetup);
		}
	}

	@Provides
	FarmRunAutopilotConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(FarmRunAutopilotConfig.class);
	}
}

package com.farmrunautopilot.access;

import com.farmrunautopilot.data.AchievementDiary;
import com.farmrunautopilot.data.Location;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.Requirement;
import com.farmrunautopilot.data.Unlock;
import com.farmrunautopilot.data.poh.PohAltar;
import com.farmrunautopilot.data.travel.Spell;
import com.farmrunautopilot.data.travel.Spellbook;
import com.farmrunautopilot.data.travel.TravelItem;
import com.farmrunautopilot.data.travel.TravelMethod;
import com.farmrunautopilot.settings.AccountSettings;
import com.farmrunautopilot.settings.RunConfig;
import com.farmrunautopilot.settings.SettingsStore;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * Reads quests, diaries and skill levels on the client thread and publishes an {@link AccessSnapshot}
 * (SPEC 9). Results are cached and refreshed after login, on request, and every
 * {@link #REFRESH_TICKS} game ticks, never every tick.
 */
@Slf4j
@Singleton
public class AccessChecker
{
	/** Quests and diaries change rarely; re-read them about every 30 seconds. */
	private static final int REFRESH_TICKS = 50;

	private static final Set<Quest> QUESTS = EnumSet.of(Quest.FAIRYTALE_II__CURE_A_QUEEN, Quest.TREE_GNOME_VILLAGE,
		// Renu, the quetzal that flies between landing pads
		Quest.TWILIGHTS_PROMISE);
	/** Every skill, since the max cape needs 99 in all of them. */
	private static final Set<Skill> SKILLS = AccessSnapshot.REAL_SKILLS;

	static
	{
		final List<Requirement> all = new ArrayList<>();
		for (Patch patch : Patch.values())
		{
			all.addAll(patch.getRequirements());
		}
		for (Spell spell : Spell.values())
		{
			all.addAll(spell.getRequirements());
		}
		for (TravelMethod method : TravelMethod.values())
		{
			all.addAll(method.getRequirements());
		}
		for (TravelItem item : TravelItem.values())
		{
			all.addAll(item.getRequirements());
		}
		for (Requirement requirement : all)
		{
			if (requirement.getQuest() != null)
			{
				QUESTS.add(requirement.getQuest());
			}
		}
	}

	private final Client client;
	private final SettingsStore settings;

	private volatile AccessSnapshot snapshot = AccessSnapshot.UNKNOWN;
	private volatile boolean refreshRequested = true;
	private int ticksSinceRefresh;

	@Inject
	AccessChecker(Client client, SettingsStore settings)
	{
		this.client = client;
		this.settings = settings;
	}

	public AccessSnapshot getSnapshot()
	{
		return snapshot;
	}

	/** Forget the previous account, e.g. after switching accounts. */
	public void reset()
	{
		snapshot = AccessSnapshot.UNKNOWN;
		refreshRequested = true;
	}

	/** Re-read on the next game tick if a level that matters changed. Ignores ordinary XP drops. */
	public void onStatChanged(Skill skill, int realLevel)
	{
		final AccessSnapshot current = snapshot;
		if (SKILLS.contains(skill) && current.isKnown() && current.level(skill) != realLevel)
		{
			refreshRequested = true;
		}
	}

	/** Re-read on the next game tick (after login or a Setup change). Any thread. */
	public void requestRefresh()
	{
		refreshRequested = true;
	}

	/**
	 * Call on the client thread every game tick.
	 *
	 * @return whether the snapshot changed
	 */
	public boolean onGameTick()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return false;
		}
		if (!refreshRequested && ++ticksSinceRefresh < REFRESH_TICKS)
		{
			return false;
		}
		refreshRequested = false;
		ticksSinceRefresh = 0;

		final AccessSnapshot next = read();
		if (next.equals(snapshot))
		{
			return false;
		}
		log.debug("Account access changed");
		snapshot = next;
		return true;
	}

	private AccessSnapshot read()
	{
		final Map<Quest, QuestState> quests = new EnumMap<>(Quest.class);
		for (Quest quest : QUESTS)
		{
			quests.put(quest, quest.getState(client));
		}

		final Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		for (Skill skill : SKILLS)
		{
			levels.put(skill, client.getRealSkillLevel(skill));
		}

		final Set<String> diaries = new HashSet<>();
		for (AchievementDiary diary : AchievementDiary.values())
		{
			for (AchievementDiary.Tier tier : AchievementDiary.Tier.values())
			{
				if (diary.isComplete(tier, client.getVarbitValue(diary.getCompleteVarbit(tier))))
				{
					diaries.add(AccessSnapshot.diaryKey(diary, tier));
				}
			}
		}

		final AccountSettings account = settings.getAccount();
		final Set<Unlock> unlocks = EnumSet.noneOf(Unlock.class);
		for (Unlock unlock : account.getManualUnlocks())
		{
			// An old tick on an unlock now read from the game doesn't count: the game value is right
			if (!isDetected(unlock))
			{
				unlocks.add(unlock);
			}
		}
		// A dramen or lunar staff is also needed unless the Elite Lumbridge diary is done; the supply
		// calculator checks for the staff.
		if (quests.get(Quest.FAIRYTALE_II__CURE_A_QUEEN) != QuestState.NOT_STARTED)
		{
			unlocks.add(Unlock.FAIRY_RINGS);
		}
		if (quests.get(Quest.TREE_GNOME_VILLAGE) == QuestState.FINISHED)
		{
			unlocks.add(Unlock.SPIRIT_TREES);
		}
		for (Unlock unlock : Unlock.values())
		{
			if (unlock.hasVarbit() && client.getVarbitValue(unlock.getVarbit()) > 0)
			{
				unlocks.add(unlock);
			}
		}

		final PohAltar altar = account.getPoh().getAltar();
		return new AccessSnapshot(true, Collections.unmodifiableMap(quests), Collections.unmodifiableMap(levels),
			Collections.unmodifiableSet(diaries), Collections.unmodifiableSet(unlocks), account.getPoh().getPortal(),
			spellbook(client.getVarbitValue(VarbitID.SPELLBOOK)),
			altar != null ? altar.getSpellbooks() : Collections.emptySet(),
			// QP_MAX is the quest points available in the game (checked in-game)
			client.getVarpValue(VarPlayerID.QP), client.getVarbitValue(VarbitID.QP_MAX));
	}

	/** The SPELLBOOK varbit: 0 standard, 1 ancient, 2 lunar, 3 arceuus; null for anything else. */
	static Spellbook spellbook(int value)
	{
		switch (value)
		{
			case 0:
				return Spellbook.STANDARD;
			case 1:
				return Spellbook.ANCIENT;
			case 2:
				return Spellbook.LUNAR;
			case 3:
				return Spellbook.ARCEUUS;
			default:
				return null;
		}
	}

	/** Re-read soon if the varbit is the spellbook. Client thread. */
	public void onVarbitChanged(int varbitId)
	{
		if (varbitId == VarbitID.SPELLBOOK)
		{
			refreshRequested = true;
		}
	}

	/** Unlocks that are worked out automatically, so Setup shows them as detected rather than a toggle. */
	public static boolean isDetected(Unlock unlock)
	{
		return unlock == Unlock.FAIRY_RINGS || unlock == Unlock.SPIRIT_TREES || unlock.isReadFromGame();
	}

	/**
	 * Unlocks the plugin can't read from the game, not ticked, that would change this run: a patch or a way to
	 * a patch that's switched on needs them. Empty once the player has checked their unlocks.
	 */
	public static List<Unlock> toReview(RunConfig config, AccountSettings account)
	{
		final List<Unlock> review = new ArrayList<>();
		if (account.isUnlocksReviewed())
		{
			return review;
		}
		final Set<Location> locations = EnumSet.noneOf(Location.class);
		final Set<Unlock> needed = EnumSet.noneOf(Unlock.class);
		for (Patch patch : Patch.values())
		{
			if (config.getEnabledTypes().contains(patch.getType()) && !config.getDisabledPatches().contains(patch))
			{
				locations.add(patch.getLocation());
				addUnlocks(patch.getRequirements(), needed);
				if (patch.getDiseaseFreeRequirement() != null)
				{
					addUnlocks(Collections.singletonList(patch.getDiseaseFreeRequirement()), needed);
				}
			}
		}
		for (TravelMethod method : TravelMethod.values())
		{
			if (locations.contains(method.getDestination()))
			{
				addUnlocks(method.getRequirements(), needed);
			}
		}
		for (Unlock unlock : needed)
		{
			if (!isDetected(unlock) && !unlock.hasVarbit() && !account.getManualUnlocks().contains(unlock))
			{
				review.add(unlock);
			}
		}
		return review;
	}

	private static void addUnlocks(List<Requirement> requirements, Set<Unlock> into)
	{
		for (Requirement requirement : requirements)
		{
			if (requirement.getKind() == Requirement.Kind.UNLOCK)
			{
				into.add(requirement.getUnlock());
			}
		}
	}
}

package com.farmrunautopilot.access;

import com.farmrunautopilot.data.AchievementDiary;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.Requirement;
import com.farmrunautopilot.data.Unlock;
import com.farmrunautopilot.data.poh.HousePortal;
import com.farmrunautopilot.data.travel.Spell;
import com.farmrunautopilot.data.travel.Spellbook;
import com.farmrunautopilot.data.travel.TravelMethod;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Value;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

/**
 * An immutable picture of what the account has unlocked (SPEC 9), safe to read from any thread.
 */
@Value
public class AccessSnapshot
{
	/** Before the first login: nothing is known, so nothing shows as locked. */
	public static final AccessSnapshot UNKNOWN = new AccessSnapshot(false, Collections.emptyMap(),
		Collections.emptyMap(), Collections.emptySet(), Collections.emptySet(), null);

	/**
	 * Every skill. In this RuneLite version {@code Skill.OVERALL} is a deprecated field left as null, not an
	 * enum value, so {@code Skill.values()} already has only real skills.
	 */
	public static final Set<Skill> REAL_SKILLS = Collections.unmodifiableSet(EnumSet.allOf(Skill.class));

	/** False until real account data has been read. */
	boolean known;
	Map<Quest, QuestState> quests;
	Map<Skill, Integer> realLevels;
	/** Completed diaries as "DIARY:TIER", e.g. "FALADOR:ELITE". */
	Set<String> completedDiaries;
	/** Detected unlocks plus the ones the player ticked by hand. */
	Set<Unlock> unlocks;
	/** House portal location from My POH, or null. */
	HousePortal housePortal;
	/** The spellbook the player is on, or null if unknown. */
	Spellbook spellbook;
	/** Spellbooks a POH altar can switch to (empty without one). */
	Set<Spellbook> altarSpellbooks;
	/** The player's quest points. */
	int questPoints;
	/** Quest points available in the game right now; 0 if unknown. */
	int maxQuestPoints;

	public AccessSnapshot(boolean known, Map<Quest, QuestState> quests, Map<Skill, Integer> realLevels,
		Set<String> completedDiaries, Set<Unlock> unlocks, HousePortal housePortal, Spellbook spellbook,
		Set<Spellbook> altarSpellbooks, int questPoints, int maxQuestPoints)
	{
		this.known = known;
		this.quests = quests;
		this.realLevels = realLevels;
		this.completedDiaries = completedDiaries;
		this.unlocks = unlocks;
		this.housePortal = housePortal;
		this.spellbook = spellbook;
		this.altarSpellbooks = altarSpellbooks;
		this.questPoints = questPoints;
		this.maxQuestPoints = maxQuestPoints;
	}

	/** Without quest point information: the quest point cape counts as unusable. */
	public AccessSnapshot(boolean known, Map<Quest, QuestState> quests, Map<Skill, Integer> realLevels,
		Set<String> completedDiaries, Set<Unlock> unlocks, HousePortal housePortal, Spellbook spellbook,
		Set<Spellbook> altarSpellbooks)
	{
		this(known, quests, realLevels, completedDiaries, unlocks, housePortal, spellbook, altarSpellbooks, 0, 0);
	}

	/** Without spellbook information: any book counts as usable. */
	public AccessSnapshot(boolean known, Map<Quest, QuestState> quests, Map<Skill, Integer> realLevels,
		Set<String> completedDiaries, Set<Unlock> unlocks, HousePortal housePortal)
	{
		this(known, quests, realLevels, completedDiaries, unlocks, housePortal, null, Collections.emptySet());
	}

	public static String diaryKey(AchievementDiary diary, AchievementDiary.Tier tier)
	{
		return diary.name() + ":" + tier.name();
	}

	public boolean isMet(Requirement requirement)
	{
		if (!known)
		{
			return true;
		}
		switch (requirement.getKind())
		{
			case QUEST_COMPLETE:
				return quests.get(requirement.getQuest()) == QuestState.FINISHED;
			case QUEST_STARTED:
			{
				final QuestState state = quests.get(requirement.getQuest());
				return state != null && state != QuestState.NOT_STARTED;
			}
			case SKILL:
				return level(requirement.getSkill()) >= requirement.getLevel();
			case DIARY:
				return completedDiaries.contains(diaryKey(requirement.getDiary(), requirement.getDiaryTier()));
			case UNLOCK:
				return unlocks.contains(requirement.getUnlock());
			case HOUSE_PORTAL:
				return requirement.getHousePortal() == housePortal;
			case ALL_SKILLS:
				for (Skill skill : REAL_SKILLS)
				{
					if (level(skill) < requirement.getLevel())
					{
						return false;
					}
				}
				return true;
			case ALL_DIARIES:
				for (AchievementDiary diary : AchievementDiary.values())
				{
					if (!completedDiaries.contains(diaryKey(diary, requirement.getDiaryTier())))
					{
						return false;
					}
				}
				return true;
			case ALL_QUESTS:
				return hasAllQuests(questPoints, maxQuestPoints);
			default:
				return false;
		}
	}

	/** Every quest point in the game; an unknown maximum (0) counts as not. */
	static boolean hasAllQuests(int questPoints, int maxQuestPoints)
	{
		return maxQuestPoints > 0 && questPoints >= maxQuestPoints;
	}

	public int level(Skill skill)
	{
		final Integer level = realLevels.get(skill);
		return level != null ? level : 1;
	}

	/**
	 * @return the requirements that aren't met, empty if everything is
	 */
	public List<Requirement> missing(List<Requirement> requirements)
	{
		final List<Requirement> missing = new ArrayList<>();
		for (Requirement requirement : requirements)
		{
			if (!isMet(requirement))
			{
				missing.add(requirement);
			}
		}
		return missing;
	}

	public List<Requirement> missingFor(Patch patch)
	{
		return missing(patch.getRequirements());
	}

	/**
	 * Requirements for a travel method: its own, the item's, the spell's quest, and the spell's Magic level
	 * when there is no tablet (tablets work at any Magic level). Owning the item, tablet or runes is checked
	 * by the supply calculator, not here.
	 */
	public List<Requirement> missingFor(TravelMethod method)
	{
		final List<Requirement> all = new ArrayList<>(method.getRequirements());
		if (method.getItem() != null)
		{
			all.addAll(method.getItem().getRequirements());
		}
		final Spell spell = method.getSpell();
		if (spell != null)
		{
			all.addAll(spell.getRequirements());
			if (!spell.hasTablet())
			{
				all.add(Requirement.skill(Skill.MAGIC, spell.getMagicLevel()));
			}
		}
		return missing(all);
	}

	/**
	 * Whether the player can cast this spell rather than needing its tablet: Magic level, quest, and being on
	 * its spellbook (or able to switch with a house altar). Sean asked not to hop spellbooks otherwise.
	 */
	public boolean canCast(Spell spell)
	{
		return !known || (level(Skill.MAGIC) >= spell.getMagicLevel() && missing(spell.getRequirements()).isEmpty()
			&& (isOnSpellbook(spell) || altarSpellbooks.contains(spell.getSpellbook()) || canSwapFor(spell)));
	}

	/**
	 * The spell is on another book that the house altar can't switch to, but the player is on Lunar and can cast
	 * Spellbook Swap for it (one cast). Never true off Lunar.
	 */
	public boolean needsLunarSwap(Spell spell)
	{
		return known && !isOnSpellbook(spell) && !altarSpellbooks.contains(spell.getSpellbook()) && canSwapFor(spell);
	}

	/** Spellbook Swap only exists on Lunar: 96 Magic and Dream Mentor. */
	private boolean canSwapFor(Spell spell)
	{
		return spellbook == Spellbook.LUNAR && spell.getSpellbook() != Spellbook.LUNAR
			&& level(Skill.MAGIC) >= Spell.SPELLBOOK_SWAP.getMagicLevel()
			&& missing(Spell.SPELLBOOK_SWAP.getRequirements()).isEmpty();
	}

	/** On the spell's spellbook right now (or the spellbook isn't known). */
	public boolean isOnSpellbook(Spell spell)
	{
		return spellbook == null || spellbook == spell.getSpellbook();
	}

	/** Tooltip text listing what's missing, e.g. "Needs 65 Farming, Needs Priest in Peril". */
	public static String describe(List<Requirement> missing)
	{
		final List<String> parts = new ArrayList<>();
		for (Requirement requirement : missing)
		{
			parts.add(requirement.describe());
		}
		return String.join(", ", parts);
	}
}

package com.farmrunautopilot.access;

import com.farmrunautopilot.data.poh.JewelleryBoxTier;
import com.farmrunautopilot.data.poh.PohAltar;
import com.farmrunautopilot.data.poh.PoolTier;
import com.farmrunautopilot.settings.PohSetup;
import com.farmrunautopilot.settings.SettingsStore;
import java.time.Instant;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

/**
 * Fills in My house from house furniture as it loads (SPEC 2 "auto-detect on visit"). Driven by object
 * spawn events, never by scanning the scene.
 *
 * <p>Detection only ever adds or upgrades, because objects in another player's house look the same
 * and a partly loaded house would otherwise wipe settings. Removed furniture is picked up with Rescan
 * house in My house, which clears what was detected so the next house visit fills it in again. The house
 * portal location and nexus destinations can't be read this way and stay manual.
 *
 * <p>Only objects in the player's own house are looked at: from the "Loading house" screen (shown a tick
 * before the house's objects spawn) until a scene outside an instance loads. The game doesn't say whose house
 * it is, so it's worked out from how the player got in: a friend's house or the advertisement board means
 * someone else's, and the house is skipped until the player goes home again. Solo ironmen can't visit other
 * houses, so theirs is always scanned. Furniture found is collected and saved once, on the next game tick.
 */
@Slf4j
@Singleton
public class PohDetector
{
	/** The friend's-name prompt within this many ticks of using a house portal means visiting a friend. */
	private static final int NAME_PROMPT_TICKS = 50;

	private final Client client;
	private final SettingsStore settings;
	private final AccessChecker accessChecker;

	/** In the player's own house (client thread). */
	private boolean inHouse;
	/** The last way into a house was someone else's (client thread). */
	private boolean visiting;
	/** When a house portal was last used, for spotting the friend's-name prompt. */
	private int portalUsedTick = -NAME_PROMPT_TICKS;
	// Found since the last tick (client thread)
	private boolean found;
	private JewelleryBoxTier foundBox;
	private PoolTier foundPool;
	private PohAltar foundAltar;
	private boolean foundFairyRing;
	private boolean foundSpiritTree;

	@Inject
	PohDetector(Client client, SettingsStore settings, AccessChecker accessChecker)
	{
		this.client = client;
		this.settings = settings;
		this.accessChecker = accessChecker;
	}

	/** In the player's own house, with scanning on. Client thread. */
	public boolean isScanningHouse()
	{
		return inHouse;
	}

	/** The last house entered was someone else's. Client thread. */
	public boolean isVisiting()
	{
		return visiting;
	}

	/** The "Loading house" screen opened: the house's objects spawn next. Scan only the player's own. */
	public void onHouseLoading()
	{
		// Beta, ticked in Account > My house
		inHouse = settings.getAccount().isAutoDetectHouse() && (!visiting || soloIronman());
		log.debug("Entering a house: {}", inHouse ? "own, scanning" : "someone else's, not scanning");
	}

	/** Note how the player is getting into a house. */
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		final String option = Text.removeTags(event.getMenuOption());
		final String target = Text.removeTags(event.getMenuTarget());
		final Widget widget = event.getWidget();
		final Boolean someoneElses = someoneElsesHouse(option, target,
			widget != null && widget.getText() != null ? Text.removeTags(widget.getText()) : null);
		if (someoneElses != null)
		{
			visiting = someoneElses;
		}
		if (target.contains("Portal"))
		{
			portalUsedTick = client.getTickCount();
		}
	}

	/**
	 * Whether a click leads into someone else's house (true), the player's own (false), or neither (null).
	 *
	 * @param dialogText the text of a clicked dialogue option or other widget, or null
	 */
	static Boolean someoneElsesHouse(String option, String target, String dialogText)
	{
		final String text = dialogText != null ? dialogText.toLowerCase() : "";
		if (option.equalsIgnoreCase("Friend's house") || target.contains("House Advertisement")
			|| text.contains("friend's house"))
		{
			return true;
		}
		if (option.equalsIgnoreCase("Home") || option.equalsIgnoreCase("Build mode") || option.contains("POH")
			|| target.toLowerCase().contains("teleport to house") || text.contains("your house")
			|| text.contains("build mode"))
		{
			return false;
		}
		return null;
	}

	/**
	 * Chosen "a friend's house" from the portal by keyboard: no click to see, but the game then asks for the
	 * friend's name. UNVERIFIED: the prompt is assumed to contain "Enter name".
	 */
	private void checkNamePrompt()
	{
		if (client.getTickCount() - portalUsedTick > NAME_PROMPT_TICKS)
		{
			return;
		}
		final Widget prompt = client.getWidget(InterfaceID.Chatbox.MES_TEXT);
		if (prompt != null && !prompt.isHidden() && prompt.getText() != null
			&& prompt.getText().contains("Enter name"))
		{
			visiting = true;
		}
	}

	/** Normal, hardcore and ultimate ironmen can't enter other players' houses. Group ironmen can. */
	private boolean soloIronman()
	{
		final int type = client.getVarbitValue(VarbitID.IRONMAN);
		return type >= 1 && type <= 3;
	}

	/** A new scene is loading; anything but an instance means the player has left the house. */
	public void onSceneLoading(boolean instance)
	{
		if (!instance)
		{
			inHouse = false;
		}
	}

	/** Call for every spawned game object. Does nothing outside a house. */
	public void onObjectSpawned(int objectId)
	{
		if (!inHouse)
		{
			return;
		}
		final JewelleryBoxTier box = jewelleryBoxFor(objectId);
		final PoolTier pool = poolFor(objectId);
		final boolean fairyRing = objectId == ObjectID.POH_FAIRY_RING || objectId == ObjectID.POH_SPIRIT_RING;
		final boolean spiritTree = objectId == ObjectID.POH_SPIRIT_TREE || objectId == ObjectID.POH_SPIRIT_RING;
		final PohAltar altar = altarFor(objectId);
		if (box == null && pool == null && altar == null && !fairyRing && !spiritTree)
		{
			return;
		}

		found = true;
		if (box != null && (foundBox == null || box.ordinal() > foundBox.ordinal()))
		{
			foundBox = box;
		}
		if (pool != null && (foundPool == null || pool.ordinal() > foundPool.ordinal()))
		{
			foundPool = pool;
		}
		if (altar != null && foundAltar != PohAltar.OCCULT)
		{
			foundAltar = altar;
		}
		foundFairyRing |= fairyRing;
		foundSpiritTree |= spiritTree;
	}

	/** Save what the house that just loaded had. Call every game tick. */
	public void onGameTick()
	{
		checkNamePrompt();
		if (!found)
		{
			return;
		}
		final JewelleryBoxTier box = foundBox;
		final PoolTier pool = foundPool;
		final PohAltar altar = foundAltar;
		final boolean fairyRing = foundFairyRing;
		final boolean spiritTree = foundSpiritTree;
		clearFound();
		// Settings are only changed on the Swing thread.
		SwingUtilities.invokeLater(() -> apply(box, pool, altar, fairyRing, spiritTree));
	}

	/** Forget anything found but not yet saved, and that the player was in a house. */
	public void reset()
	{
		inHouse = false;
		clearFound();
	}

	/** Furniture was found and not yet saved (for tests). */
	boolean hasFound()
	{
		return found;
	}

	private void clearFound()
	{
		found = false;
		foundBox = null;
		foundPool = null;
		foundAltar = null;
		foundFairyRing = false;
		foundSpiritTree = false;
	}

	/**
	 * Clear the detected furniture so the next house visit records exactly what's there, removals included.
	 * The portal location, teleport-outside and nexus destinations are kept. Call on the Swing thread.
	 */
	public static void clearDetected(PohSetup poh)
	{
		poh.setJewelleryBox(null);
		poh.setPool(null);
		poh.setAltar(null);
		poh.setFairyRing(false);
		poh.setSpiritTree(false);
		poh.setLastDetected(0);
	}

	private void apply(JewelleryBoxTier box, PoolTier pool, PohAltar altar, boolean fairyRing, boolean spiritTree)
	{
		final PohSetup poh = settings.editAccount().getPoh();
		boolean changed = false;
		if (box != null && (poh.getJewelleryBox() == null || box.ordinal() > poh.getJewelleryBox().ordinal()))
		{
			poh.setJewelleryBox(box);
			changed = true;
		}
		if (pool != null && (poh.getPool() == null || pool.ordinal() > poh.getPool().ordinal()))
		{
			poh.setPool(pool);
			changed = true;
		}
		// The occult altar covers every spellbook, so it beats the others
		if (altar != null && poh.getAltar() != altar && poh.getAltar() != PohAltar.OCCULT)
		{
			poh.setAltar(altar);
			changed = true;
		}
		if (fairyRing && !poh.isFairyRing())
		{
			poh.setFairyRing(true);
			changed = true;
		}
		if (spiritTree && !poh.isSpiritTree())
		{
			poh.setSpiritTree(true);
			changed = true;
		}

		poh.setLastDetected(Instant.now().getEpochSecond());
		if (changed)
		{
			log.debug("Detected POH furniture: box={} pool={} altar={} fairyRing={} spiritTree={}", box, pool, altar, fairyRing,
				spiritTree);
		}
		// Always save so "last detected" updates; refresh the tab only when something new was found.
		settings.saveAccount(changed);
		if (changed)
		{
			accessChecker.requestRefresh();
		}
	}

	static JewelleryBoxTier jewelleryBoxFor(int objectId)
	{
		switch (objectId)
		{
			case ObjectID.POH_JEWELLERY_BOX_1:
				return JewelleryBoxTier.BASIC;
			case ObjectID.POH_JEWELLERY_BOX_2:
				return JewelleryBoxTier.FANCY;
			case ObjectID.POH_JEWELLERY_BOX_3:
				return JewelleryBoxTier.ORNATE;
			default:
				return null;
		}
	}

	static PohAltar altarFor(int objectId)
	{
		switch (objectId)
		{
			case ObjectID.POH_ALTAR_ANCIENT:
				return PohAltar.ANCIENT;
			case ObjectID.POH_ALTAR_LUNAR:
				return PohAltar.LUNAR;
			case ObjectID.POH_ALTAR_DARK:
				return PohAltar.DARK;
			case ObjectID.POH_ALTAR_OCCULT:
			case ObjectID.POH_ALTAR_OCCULT_STANDARD:
			case ObjectID.POH_ALTAR_OCCULT_ANCIENT:
			case ObjectID.POH_ALTAR_OCCULT_LUNAR:
			case ObjectID.POH_ALTAR_OCCULT_ARCEUUS:
				return PohAltar.OCCULT;
			default:
				return null;
		}
	}

	static PoolTier poolFor(int objectId)
	{
		switch (objectId)
		{
			case ObjectID.POH_POOL_RESTORATION:
				return PoolTier.RESTORATION;
			case ObjectID.POH_POOL_REVITALISATION:
				return PoolTier.REVITALISATION;
			case ObjectID.POH_POOL_REJUVENATION:
				return PoolTier.REJUVENATION;
			// "Recovery" (29240) and "regeneration" (29241) are the fancy and ornate pools: the wiki gives the ornate pool
			// 29241, and the five are numbered in tier order
			case ObjectID.POH_POOL_RECOVERY:
				return PoolTier.FANCY_REJUVENATION;
			case ObjectID.POH_POOL_REGENERATION:
				return PoolTier.ORNATE_REJUVENATION;
			default:
				return null;
		}
	}
}

package com.farmrunautopilot.access;

import com.farmrunautopilot.data.Unlock;
import com.farmrunautopilot.settings.AccountSettings;
import com.farmrunautopilot.settings.SettingsStore;
import java.util.Arrays;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.ObjectComposition;

/**
 * Ticks unlocks the game has no value for once the player sees them: a grown spirit tree they can travel
 * from at a planted spot, or the built Fire of Nourishment at Weiss. Driven by object spawns. Client thread.
 *
 * <p>UNVERIFIED: the region IDs, the names and the "Travel" option are from the wiki and other patches, not
 * checked in game; spotted objects are logged at debug level for checking.
 */
@Slf4j
@Singleton
public class UnlockSpotter
{
	private static final class Spot
	{
		final Unlock unlock;
		final List<Integer> regions;
		final String name;
		/** An option the object has once unlocked, e.g. "Travel"; null if the name alone is enough. */
		final String option;

		Spot(Unlock unlock, String name, String option, Integer... regions)
		{
			this.unlock = unlock;
			this.name = name;
			this.option = option;
			this.regions = Arrays.asList(regions);
		}
	}

	private static final List<Spot> SPOTS = Arrays.asList(
		new Spot(Unlock.SPIRIT_TREE_PORT_SARIM, "Spirit tree", "Travel", 12082),
		new Spot(Unlock.SPIRIT_TREE_BRIMHAVEN, "Spirit tree", "Travel", 11058, 11057),
		new Spot(Unlock.SPIRIT_TREE_FARMING_GUILD, "Spirit tree", "Travel", 4922),
		// Unbuilt, the spot offers "Build" instead
		new Spot(Unlock.FIRE_OF_NOURISHMENT, "Fire of Nourishment", null, 11325));

	private final Client client;
	private final SettingsStore settings;
	private final AccessChecker accessChecker;

	@Inject
	UnlockSpotter(Client client, SettingsStore settings, AccessChecker accessChecker)
	{
		this.client = client;
		this.settings = settings;
		this.accessChecker = accessChecker;
	}

	public void onObjectSpawned(GameObject object)
	{
		final int region = object.getWorldLocation().getRegionID();
		final AccountSettings account = settings.getAccount();
		ObjectComposition composition = null;
		for (Spot spot : SPOTS)
		{
			if (!spot.regions.contains(region) || account.getManualUnlocks().contains(spot.unlock))
			{
				continue;
			}
			// Only look the object up in a region that matters
			if (composition == null)
			{
				composition = client.getObjectDefinition(object.getId());
				if (composition != null && composition.getImpostorIds() != null)
				{
					composition = composition.getImpostor();
				}
				if (composition == null)
				{
					return;
				}
			}
			if (spot.name.equals(composition.getName()) && hasOption(composition, spot.option)
				&& !hasOption(composition, "Build"))
			{
				log.debug("Spotted {} ({} at {})", spot.unlock, object.getId(), object.getWorldLocation());
				// Settings are changed on the Swing thread (SettingsStore)
				final Unlock spotted = spot.unlock;
				SwingUtilities.invokeLater(() ->
				{
					if (settings.editAccount().getManualUnlocks().add(spotted))
					{
						settings.saveAccount(true);
						accessChecker.requestRefresh();
					}
				});
			}
		}
	}

	private static boolean hasOption(ObjectComposition composition, String option)
	{
		if (option == null)
		{
			return true;
		}
		final String[] actions = composition.getActions();
		if (actions != null)
		{
			for (String action : actions)
			{
				if (option.equalsIgnoreCase(action))
				{
					return true;
				}
			}
		}
		return false;
	}
}

