import net.runelite.api.gameval.ItemID;

/**
 * A teleport straight to a bank, carried on a run too big for one inventory so it can bank partway wherever
 * that's quickest, not only at a stop with a bank nearby. Quickest first.
 */
@Getter
public enum BankTeleport
{
	CRAFTING_CAPE("Crafting cape", "the Crafting Guild bank", new WorldPoint(2936, 3281, 0), 9,
		Requirement.skill(Skill.CRAFTING, 99),
		ItemID.SKILLCAPE_CRAFTING, ItemID.SKILLCAPE_CRAFTING_TRIMMED),
	RING_OF_DUELING("Ring of dueling", "the Castle Wars bank chest", new WorldPoint(2443, 3083, 0), 10, null,
		ItemID.RING_OF_DUELING_1, ItemID.RING_OF_DUELING_2, ItemID.RING_OF_DUELING_3, ItemID.RING_OF_DUELING_4,
		ItemID.RING_OF_DUELING_5, ItemID.RING_OF_DUELING_6, ItemID.RING_OF_DUELING_7, ItemID.RING_OF_DUELING_8),
	MAX_CAPE("Max cape", "the Crafting Guild bank", new WorldPoint(2936, 3281, 0), 11, null,
		TravelItem.MAX_CAPE.getItemIds()),
	RING_OF_WEALTH("Ring of wealth", "the Grand Exchange", new WorldPoint(3164, 3489, 0), 15, null,
		TravelItem.RING_OF_WEALTH.getItemIds());

	private final String itemName;
	/** Where it lands, e.g. "the Castle Wars bank chest". */
	private final String bankName;
	/** The bank chest or booth it lands by (Shortest Path's bank list), so the guide knows the player got there. */
	private final WorldPoint bankPoint;
	/** Teleport, landing and the walk to the bank booth or chest. */
	private final double seconds;
	private final Requirement requirement;
	private final int[] itemIds;

	BankTeleport(String itemName, String bankName, WorldPoint bankPoint, double seconds, Requirement requirement,
		int... itemIds)
	{
		this.itemName = itemName;
		this.bankName = bankName;
		this.bankPoint = bankPoint;
		this.seconds = seconds;
		this.requirement = requirement;
		this.itemIds = itemIds;
	}

	public int[] getItemIds()
	{
		return itemIds.clone();
	}

	/** The quickest bank teleport the player has anywhere the plugin can see, or null. */
	public static BankTeleport best(AccessSnapshot access, Holdings holdings)
	{
		for (BankTeleport teleport : values())
		{
			if ((teleport.requirement == null || access.isMet(teleport.requirement))
				&& holdings.countAny(teleport.itemIds) > 0)
			{
				return teleport;
			}
		}
		return null;
	}
}

package com.farmrunautopilot.data.travel;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import java.util.function.IntPredicate;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

/**
 * Diary teleports limited to a number of uses per day (wiki, checked 2026-10-10): Ardougne cloak 2 (3) and 3 (5)
 * to the farm, and Explorer's ring 2 (3) to the cabbage patch. Higher tiers are unlimited. (Rada's blessing 3
 * also has 3 a day to Mount Karuulm, but nobody spends those on a farm run, so it isn't tracked.)
 */
public final class DailyLimits
{
	/**
	 * The game value counting today's uses of each, both confirmed in game: they matched "You have used 1 of
	 * your 3 Ardougne Farm teleports for today." and "You have used 1 of your 3 Cabbage teleports for today."
	 */
	private static final Map<TravelMethod, Integer> USED_TODAY = new EnumMap<>(TravelMethod.class);

	static
	{
		USED_TODAY.put(TravelMethod.ARDOUGNE_CLOAK_FARM, VarbitID.ARDOUGNE_CLOAK_LOWBITS);
		USED_TODAY.put(TravelMethod.EXPLORERS_RING_CABBAGE_PATCH, VarbitID.LUMBRIDGE_CABBAGE_TELEPORT);
	}

	private DailyLimits()
	{
	}

	/** Teleports limited per day, with the game value that counts today's uses. */
	public static Map<TravelMethod, Integer> usedTodayVarbits()
	{
		return Collections.unmodifiableMap(USED_TODAY);
	}

	/**
	 * Uses per day of a teleport with the best tier the player holds, or null if unlimited (or not limited).
	 *
	 * @param holds whether the player holds an item ID anywhere
	 */
	public static Integer perDay(TravelMethod method, IntPredicate holds)
	{
		switch (method)
		{
			case ARDOUGNE_CLOAK_FARM:
				if (holds.test(ItemID.ARDY_CAPE_ELITE))
				{
					return null;
				}
				if (holds.test(ItemID.ARDY_CAPE_HARD))
				{
					return 5;
				}
				return holds.test(ItemID.ARDY_CAPE_MEDIUM) ? Integer.valueOf(3) : null;
			case EXPLORERS_RING_CABBAGE_PATCH:
				if (holds.test(ItemID.LUMBRIDGE_RING_ELITE) || holds.test(ItemID.LUMBRIDGE_RING_HARD))
				{
					return null;
				}
				return holds.test(ItemID.LUMBRIDGE_RING_MEDIUM) ? Integer.valueOf(3) : null;
			default:
				return null;
		}
	}
}

