	{
		switch (this)
		{
			case RING_OF_WEALTH:
			case SLAYER_RING:
			case EXPLORERS_RING:
				return WearSlot.RING;
			case SKILLS_NECKLACE:
			case GAMES_NECKLACE:
			case AMULET_OF_GLORY:
			case PENDANT_OF_ATES:
				return WearSlot.NECK;
			case COMBAT_BRACELET:
				return WearSlot.HANDS;
			case RADAS_BLESSING:
			// The Book of the dead only; Kharedst's memoirs can't be worn (see SupplyCalculator.toWear)
			case KHAREDSTS_MEMOIRS:
				return WearSlot.SHIELD;
			case ARDOUGNE_CLOAK:
			case ARDOUGNE_CLOAK_1:
			case QUEST_POINT_CAPE:
			case FARMING_CAPE:
			case HUNTER_CAPE:
			case CONSTRUCTION_CAPE:
			case MAX_CAPE:
			case ACHIEVEMENT_DIARY_CAPE:
				return WearSlot.CAPE;
			default:
				return null;
		}
	}
