	private final Location destination;
	private final String displayName;
	private final TravelKind kind;
	/** The spell to cast (or its tablet), or null. HOUSE_PORTAL methods use Teleport to House. */
	private final Spell spell;
	/** The teleport item, or null. */
	private final TravelItem item;
	private final int coins;
	/** Fairy ring code for FAIRY_RING methods, otherwise null. */
	private final String fairyRingCode;
	private final String note;
	/**
	 * Steps after landing and before the walk to the patch (a boat, a quetzal, an NPC who leads the way), in
	 * order; empty if it's just a walk. The guide shows them one at a time.
	 */
	private final List<JourneyStep> then;
	/** The rides in {@link #then} (boats, quetzals, Elkoy, a ladder out): each its own tick box on the Run tab. */
	private final List<JourneyStep> rides;
	/**
	 * The walking directions in {@link #then} (rocks, gates, stairs): part of the walk to the patch, not tick boxes of
	 * their own (Sean, 2026-10-15: they ticked early at the Troll Stronghold and don't need boxes).
	 */
	private final List<JourneyStep> directions;
	/** Requirements beyond the spell's own and owning the item. */
	private final List<Requirement> requirements;
	private final Set<PatchType> primaryFor;
	/** The same teleport from a POH portal nexus, or null. */
	private final PortalNexus.Destination nexus;
	/** The same teleport from a POH jewellery box of at least this tier, or null. */
	private final JewelleryBoxTier jewelleryBox;

	TravelMethod(Def def)
	{
		this.destination = def.destination;
		this.displayName = def.displayName;
		this.kind = def.kind;
		this.spell = def.spell;
		this.item = def.item;
		this.coins = def.coins;
		this.fairyRingCode = def.fairyRingCode;
		this.note = def.note;
		this.then = Collections.unmodifiableList(def.then);
		final List<JourneyStep> rides = new ArrayList<>();
		final List<JourneyStep> directions = new ArrayList<>();
		for (JourneyStep step : def.then)
		{
			(step.getKind() == JourneyStep.Kind.RIDE ? rides : directions).add(step);
		}
		this.rides = Collections.unmodifiableList(rides);
		this.directions = Collections.unmodifiableList(directions);
		this.requirements = Collections.unmodifiableList(def.requirements);
		this.primaryFor = Collections.unmodifiableSet(def.primaryFor);
		this.nexus = def.nexus;
		this.jewelleryBox = def.jewelleryBox;
	}

	public boolean isPrimaryFor(PatchType type)
	{
		return primaryFor.contains(type);
	}

	private static Def spell(Location destination, Spell spell)
	{
		final Def def = new Def(destination, spell.getDisplayName(), TravelKind.SPELL);
		def.spell = spell;
		return def;
	}

	private static Def item(Location destination, String displayName, TravelKind kind, TravelItem item)
	{
		final Def def = new Def(destination, displayName, kind);
		def.item = item;
		return def;
	}

	private static Def fairyRing(Location destination, String code)
	{
		final Def def = new Def(destination, "Fairy ring " + code, TravelKind.FAIRY_RING);
		def.fairyRingCode = code;
		def.requirements.add(Requirement.unlock(Unlock.FAIRY_RINGS));
		return def;
	}

	private static Def spiritTree(Location destination, String displayName)
	{
		final Def def = new Def(destination, displayName, TravelKind.SPIRIT_TREE);
		def.requirements.add(Requirement.unlock(Unlock.SPIRIT_TREES));
		return def;
	}

	/** A balloon flight: Enlightened Journey, and the route from the basket it leaves from unlocked. */
	private static Def balloon(Location destination, String displayName)
	{
		final Def def = new Def(destination, displayName, TravelKind.BALLOON);
		def.requirements.add(Requirement.quest(Quest.ENLIGHTENED_JOURNEY));
		def.requirements.add(Requirement.unlock(Unlock.BALLOON_GRAND_TREE));
		return def;
	}

	private static Def housePortal(Location destination, HousePortal portal)
	{
		final Def def = new Def(destination, "Teleport to House (" + portal.getDisplayName() + " portal)",
			TravelKind.HOUSE_PORTAL);
		def.spell = Spell.TELEPORT_TO_HOUSE;
		def.requirements.add(Requirement.housePortal(portal));
		def.note = "Lands inside the house unless it is set to teleport outside";
		return def;
	}

	private static Def quetzal(Location destination, String displayName)
	{
		final Def def = new Def(destination, displayName, TravelKind.QUETZAL);
		def.item = TravelItem.QUETZAL_WHISTLE;
		return def;
	}

	private static final class Def
	{
		private final Location destination;
		private final String displayName;
		private final TravelKind kind;
		private Spell spell;
		private TravelItem item;
		private int coins;
		private String fairyRingCode;
		private String note;
		private final List<JourneyStep> then = new ArrayList<>();
		private final List<Requirement> requirements = new ArrayList<>();
		private final Set<PatchType> primaryFor = EnumSet.noneOf(PatchType.class);
		private PortalNexus.Destination nexus;
		private JewelleryBoxTier jewelleryBox;

		private Def(Location destination, String displayName, TravelKind kind)
		{
			this.destination = destination;
			this.displayName = displayName;
			this.kind = kind;
		}

		Def primaryFor(PatchType... types)
		{
			primaryFor.addAll(Arrays.asList(types));
			return this;
		}

		Def requires(Requirement... more)
		{
			requirements.addAll(Arrays.asList(more));
			return this;
		}

		Def coins(int amount)
		{
			coins = amount;
			return this;
		}

		Def note(String text)
		{
			note = text;
			return this;
		}

		Def then(JourneyStep... steps)
		{
			then.addAll(Arrays.asList(steps));
			return this;
		}

		Def nexus(PortalNexus.Destination destination)
		{
			nexus = destination;
			return this;
		}

		Def jewelleryBox(JewelleryBoxTier tier)
		{
			jewelleryBox = tier;
			return this;
		}
	}
}

package com.farmrunautopilot.data.travel;

import com.farmrunautopilot.data.Location;
import com.farmrunautopilot.data.Unlock;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;

/**
 * Measured journeys for each travel method, from wiki research (docs/plans/travel-research.md, checked
 * 2026-10-10): the real walking path in tiles from where it lands to the nearest of the stop's patches, and
 * extra seconds for anything that isn't walking (a boat, a quetzal, Elkoy, a ladder). Every method is measured (a
 * test checks). Below them, every other distance the route uses: walks between stops, spirit trees, Renu,
 * fairy rings and banks near a stop, and the seconds each kind of travel takes.
 */
public final class TravelTimes
{
	private static final Map<TravelMethod, Integer> TILES = new EnumMap<>(TravelMethod.class);
	private static final Map<TravelMethod, Double> EXTRA_SECONDS = new EnumMap<>(TravelMethod.class);

	// Walking tiles from where each method lands to the nearest patch of its stop, measured on Shortest Path's
	// collision map (commit 7e81a40, BSD-2, see THIRD_PARTY_NOTICES) with its landing tiles, 2026-10-13. A few the map
	// can't measure keep their estimates, marked "estimate". Journeys add up the walks before and after the ride.
	static
	{
		// Lumbridge
		tiles(TravelMethod.LUMBRIDGE_TELEPORT, 45);
		tiles(TravelMethod.LUMBRIDGE_HOME_TELEPORT, 45);
		tiles(TravelMethod.DIARY_CAPE_LUMBRIDGE, 51);
		// Varrock
		tiles(TravelMethod.VARROCK_TELEPORT, 37);
		tiles(TravelMethod.DIARY_CAPE_VARROCK, 46);
		tiles(TravelMethod.SKILLS_NECKLACE_COOKS_GUILD, 93);
		tiles(TravelMethod.RING_OF_WEALTH_GRAND_EXCHANGE, 82);
		tiles(TravelMethod.SPIRIT_TREE_GRAND_EXCHANGE, 82);
		// Falador Park
		tiles(TravelMethod.RING_OF_WEALTH_FALADOR_PARK, 7);
		tiles(TravelMethod.FALADOR_TELEPORT_TO_PARK, 39);
		tiles(TravelMethod.SKILLS_NECKLACE_MINING_GUILD, 101);
		extra(TravelMethod.SKILLS_NECKLACE_MINING_GUILD, 3);
		// Taverley
		tiles(TravelMethod.HOUSE_PORTAL_TAVERLEY, 47);
		tiles(TravelMethod.TAVERLEY_TABLET, 47);
		tiles(TravelMethod.CONSTRUCTION_CAPE_TAVERLEY, 48);
		// 70 over the 66 Agility rocks, about 100 round by the gate
		tiles(TravelMethod.FALADOR_TELEPORT_TO_TAVERLEY, 89);
		tiles(TravelMethod.HOT_AIR_BALLOON_TAVERLEY, 16);
		tiles(TravelMethod.GAMES_NECKLACE_BURTHORPE, 117);
		tiles(TravelMethod.COMBAT_BRACELET_WARRIORS_GUILD, 115);
		// Gnome Stronghold (nearest patch: tree by the Slayer Cave, fruit tree by the spirit tree)
		tiles(TravelMethod.SLAYER_RING_STRONGHOLD_CAVE, 5);
		tiles(TravelMethod.SPIRIT_TREE_GNOME_STRONGHOLD, 12);
		tiles(TravelMethod.ROYAL_SEED_POD, 50); // estimate: the Grand Tree's door isn't on the map
		// Farming Guild
		tiles(TravelMethod.FARMING_CAPE, 8);
		tiles(TravelMethod.SKILLS_NECKLACE_FARMING_GUILD, 8);
