import lombok.Value;

/**
 * A bank visit partway through a run whose supplies don't fit in one inventory: after {@link #afterStop} the
 * player banks, near that stop or by a bank teleport, leaving what they no longer need and taking the rest of
 * the run's supplies.
 */
@Value
public class BankStop
{
	/** Index in the route of the stop the bank visit follows. */
	int afterStop;
	/** The stop just finished. */
	Location location;
	/** What the rest of the run needs, picked up at the bank. */
	SupplyPlan supplies;
	/** The bank teleport to use, or null to bank near {@link #location}. */
	BankTeleport teleport;

	/** e.g. "Bank near Gnome Stronghold" or "Bank at the Castle Wars bank chest". */
	public String title()
	{
		// An unplanned visit (an item gone missing) can come where there's no bank close by
		return teleport != null ? "Bank at " + teleport.getBankName()
			: TravelTimes.bankTiles(location) == null ? "Go to a bank" : "Bank near " + location.getDisplayName();
	}

	/** e.g. "Ring of dueling to the Castle Wars bank chest" or "Bank near Gnome Stronghold". */
	public String how()
	{
		return teleport != null ? teleport.getItemName() + " to " + teleport.getBankName() : title();
	}
}

package com.farmrunautopilot.route;

import com.farmrunautopilot.data.travel.DailyLimits;
import com.farmrunautopilot.data.travel.ItemCharges;
import com.farmrunautopilot.data.travel.TravelItem;
import com.farmrunautopilot.data.travel.TravelMethod;
import com.farmrunautopilot.supply.Holdings;
import com.farmrunautopilot.supply.ItemChargeTracker;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.gameval.ItemID;

/**
 * Teleport charges available for one run, pooled per item: every use of the same item in the run draws from
 * one pool, whichever teleport or fairy ring it's used for.
 */
public final class ChargeBudget
{
	/** Charges left per limited item; items not here never run out. */
	private final Map<TravelItem, Integer> left = new EnumMap<>(TravelItem.class);
	/** Uses left today per daily-limited teleport; teleports not here are unlimited. */
	private final Map<TravelMethod, Integer> leftToday = new EnumMap<>(TravelMethod.class);

	/**
	 * @param keepLastCharge hold back the last charge of rechargeable jewellery
	 */
	ChargeBudget(Holdings holdings, boolean keepLastCharge)
	{
		for (TravelItem item : TravelItem.values())
		{
			final Integer held = held(item, holdings);
			if (held != null)
			{
				left.put(item, keepLastCharge && ItemCharges.isRechargeable(item) ? Math.max(0, held - 1) : held);
			}
		}
		for (TravelMethod method : DailyLimits.usedTodayVarbits().keySet())
		{
			final Integer uses = leftToday(method, holdings);
			if (uses != null)
			{
				leftToday.put(method, uses);
			}
		}
	}

	/** The perfected quetzal whistle (i) never runs out. */
	private static boolean holdsInfinite(TravelItem item, Holdings holdings)
	{
		return item == TravelItem.QUETZAL_WHISTLE && holdings.count(ItemID.HG_QUETZALWHISTLE_PERFECTED_INFINITE) > 0;
	}

	/** A self-charged item is held but its charges aren't known yet: the player should Check it. */
	public static boolean chargesUnknown(TravelItem item, Holdings holdings)
	{
		return ItemChargeTracker.TRACKED.contains(item) && holdings.countAny(item.getItemIds()) > 0
			&& !holdsInfinite(item, holdings) && !holdings.getItemCharges().containsKey(item);
	}

	/** Uses left today of a daily-limited teleport, or null if it's unlimited for the item held. */
	public static Integer leftToday(TravelMethod method, Holdings holdings)
	{
		final Integer perDay = DailyLimits.perDay(method, id -> holdings.count(id) > 0);
		if (perDay == null)
		{
			return null;
		}
		final int used = holdings.getUsedToday().getOrDefault(method, 0);
		return Math.max(0, perDay - used);
	}

	boolean hasUseToday(TravelMethod method)
	{
		final Integer uses = leftToday.get(method);
		return uses == null || uses > 0;
	}

	void spendUseToday(TravelMethod method)
	{
		leftToday.computeIfPresent(method, (k, n) -> n - 1);
	}

	/**
	 * Charges the player has of an item, across every piece held, or null if it never runs out (an unlimited
	 * version is held, or the item isn't limited).
	 */
	public static Integer held(TravelItem item, Holdings holdings)
	{
		if (ItemChargeTracker.TRACKED.contains(item))
		{
			// Self-charged: known from chat once checked; unknown counts as usable
			return holdings.countAny(item.getItemIds()) == 0 || holdsInfinite(item, holdings) ? null
				: holdings.getItemCharges().get(item);
		}
		if (!ItemCharges.isLimited(item))
		{
			return null;
		}
		int total = 0;
		for (int id : item.getItemIds())
		{
			final int count = holdings.count(id);
			if (count == 0)
			{
				continue;
			}
			final Integer charges = ItemCharges.chargesOf(id);
			if (charges == null)
			{
				// An unlimited version, e.g. an eternal slayer ring
				return null;
			}
			total += count * charges;
		}
		return total;
	}

	boolean hasCharge(TravelItem item)
	{
		final Integer charges = left.get(item);
		return charges == null || charges > 0;
	}

	void spend(TravelItem item)
	{
		left.computeIfPresent(item, (k, n) -> n - 1);
	}
}

package com.farmrunautopilot.route;

import com.farmrunautopilot.data.travel.FairyRingAccess;
import lombok.Getter;

/**
 * How a leg starts: straight from wherever the player is, through their house first, or by getting to a
 * fairy ring some other way.
 */
@Getter
public enum Departure
{
	/** Use the travel method directly (cast, rub, walk to a nearby spirit tree, ...). */
	DIRECT(false, null),
	/** Teleport to House, then the portal nexus. */
	POH_NEXUS(true, null),
	/** Teleport to House, then the jewellery box. */
	POH_JEWELLERY_BOX(true, null),
	/** Teleport to House, then the house fairy ring. */
	POH_FAIRY_RING(true, null),
	/** Teleport to House, then the house spirit tree. */
	POH_SPIRIT_TREE(true, null),
	/** Walk to the fairy ring by the stop just finished. */
	FAIRY_RING_NEARBY(false, FairyRingAccess.NEARBY),
	FAIRY_RING_ARDOUGNE_CLOAK(false, FairyRingAccess.ARDOUGNE_CLOAK),
	FAIRY_RING_SLAYER_RING(false, FairyRingAccess.SLAYER_RING),
	FAIRY_RING_QUEST_CAPE(false, FairyRingAccess.QUEST_CAPE),
	/** Back to the quetzal landing pad by the stop just finished, then Renu (no whistle charge). */
	RENU(false, null),
	/** Just walk from the previous stop. */
	WALK(false, null),
	/** No unlocked way to get there. */
	NONE(false, null);

	/** Needs a Teleport to House first. */
	private final boolean viaHouse;
	/** How the fairy ring is reached, for the fairy ring departures; otherwise null. */
	private final FairyRingAccess fairyRingAccess;

	Departure(boolean viaHouse, FairyRingAccess fairyRingAccess)
	{
		this.viaHouse = viaHouse;
		this.fairyRingAccess = fairyRingAccess;
	}

	/** The departure that reaches a fairy ring this way. */
	public static Departure of(FairyRingAccess access)
	{
		for (Departure departure : values())
		{
			if (departure.fairyRingAccess == access)
			{
				return departure;
			}
		}
		throw new IllegalArgumentException(access.name());
	}
}

package com.farmrunautopilot.route;

import com.farmrunautopilot.data.Location;
import com.farmrunautopilot.data.travel.TravelKind;
import com.farmrunautopilot.data.travel.TravelMethod;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * The player's own recorded leg times, blended into the route's estimates (SPEC 12.4): samples more than
 * three times the estimate or under a third of it are ignored (a trip to the bank mid-leg, a leg skipped
 * through), and the estimate keeps some weight until there are three samples.
 *
 * <p>A teleport takes the same time wherever it's cast, but a walk, the spirit tree or fairy ring by the stop
 * just finished, and Renu from its landing pad depend on where the leg starts; those are kept per starting
 * stop, so a 14-tile walk to the Stronghold's spirit tree isn't averaged with a 60-tile one.
 */
public final class LearnedTimes
{
	public static final LearnedTimes NONE = new LearnedTimes(Collections.emptyMap());
	/** Samples needed before the player's own times replace the estimate completely. */
	static final int FULL_WEIGHT_SAMPLES = 3;
	private static final double OUTLIER_FACTOR = 3.0;
	/** The method name recorded for a walk between stops. */
	private static final String WALK = "WALK";

	/** Seconds per leg, keyed by {@link #key}. */
	private final Map<String, List<Double>> samples;

	public LearnedTimes(Map<String, List<Double>> samples)
	{
		this.samples = samples;
	}

	/** No legs learned yet. */
	public boolean isEmpty()
	{
		return samples.isEmpty();
	}

	/**
	 * One line per learned leg for "Share your run times" (Sprint 9): its key, the median seconds and how many
	 * samples, e.g. "CATHERBY|CAMELOT_TELEPORT|DIRECT: 34.1 s (3)". Nothing else about the player.
	 */
	public List<String> summary()
	{
		final List<String> lines = new java.util.ArrayList<>();
		for (Map.Entry<String, List<Double>> e : new java.util.TreeMap<>(samples).entrySet())
		{
			final List<Double> sorted = new java.util.ArrayList<>(e.getValue());
			if (sorted.isEmpty())
			{
				continue;
			}
			Collections.sort(sorted);
			final int n = sorted.size();
			final double median = n % 2 == 1 ? sorted.get(n / 2) : (sorted.get(n / 2 - 1) + sorted.get(n / 2)) / 2;
			lines.add(e.getKey() + ": " + Math.round(median * 10) / 10.0 + " s (" + n + ")");
		}
		return lines;
	}

	/**
	 * e.g. "CATHERBY|CAMELOT_TELEPORT|DIRECT", or "GNOME_STRONGHOLD>TREE_GNOME_VILLAGE|SPIRIT_TREE_..|DIRECT"
	 * for a leg that depends on where it starts. Null if it depends on that and the start isn't known (old
	 * samples, the first leg of a run, the leg after a bank).
	 *
	 * @param from the stop the leg started at, or null
	 * @param method the travel method, or null for a walk
	 */
	public static String key(String from, String to, String method, String departure)
	{
		final String way = (method == null ? WALK : method) + "|" + departure;
		if (!dependsOnStart(method, departure))
		{
			return to + "|" + way;
		}
		return from == null ? null : from + ">" + to + "|" + way;
	}

	/** Walks, Renu, the fairy ring by the last stop, and the spirit tree by the last stop. */
	static boolean dependsOnStart(String method, String departure)
	{
		if (method == null || Departure.WALK.name().equals(departure) || Departure.RENU.name().equals(departure)
			|| Departure.FAIRY_RING_NEARBY.name().equals(departure))
		{
			return true;
		}
		if (!Departure.DIRECT.name().equals(departure))
		{
			return false;
		}
		try
		{
			return TravelMethod.valueOf(method).getKind() == TravelKind.SPIRIT_TREE;
		}
		catch (IllegalArgumentException e)
		{
			// A method from an older version of the plugin
			return false;
		}
	}

	/** The estimate adjusted by the player's recorded times for this way from {@code from} to {@code to}. */
	double adjust(Location from, Location to, TravelMethod method, Departure departure, double estimate)
	{
		final String key = key(from == null ? null : from.name(), to.name(), method == null ? null : method.name(),
			departure.name());
		final List<Double> times = key == null ? null : samples.get(key);
		if (times == null)
		{
			return estimate;
		}
		double total = 0;
		int n = 0;
		for (double seconds : times)
		{
			if (seconds >= estimate / OUTLIER_FACTOR && seconds <= estimate * OUTLIER_FACTOR)
			{
				total += seconds;
				n++;
			}
		}
		if (n == 0)
		{
			return estimate;
		}
		final double weight = Math.min(n, FULL_WEIGHT_SAMPLES) / (double) FULL_WEIGHT_SAMPLES;
		return weight * (total / n) + (1 - weight) * estimate;
	}
}

