import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.game.ItemManager;

/**
 * Works out the next run on the client thread, at most once per game tick, when something it depends on
 * changes: which patches (SPEC 10), the route (SPEC 12) and the supplies (SPEC 11).
 */
@Slf4j
@Singleton
public class RunService
{
	/** Patches become due as they grow, so recalculate about once a minute regardless. */
	private static final int REFRESH_TICKS = 100;
	/** Within this many tiles of a patch counts as standing at its stop. */
	private static final int STANDING_TILES = 25;
	/** A stop whose patch is within this many tiles can be the first stop by walking there. */
	private static final int NEARBY_TILES = 120;

	private final Client client;
	private final ItemManager itemManager;
	private final SettingsStore settings;
	private final AccessChecker accessChecker;
	private final PatchTracker patchTracker;
	private final HoldingsTracker holdingsTracker;
	private final RunOverrides overrides;
	private final RunTimings timings;
	/** Item names are fixed, so look each up once. */
	private final Map<Integer, String> names = new HashMap<>();

	private volatile boolean dirty = true;
	/** Null until the first plan after login, so that one is always published. */
	private volatile RunPlan plan;
	private volatile Map<Location, TravelPick> autoPicks = new EnumMap<>(Location.class);
	private int ticksSinceRefresh;
	/** The stop the player was standing at on the last tick, or null. */
	private Location here;
	/** The stop the player is close to but not at, and how far (tiles); null if none. */
	private Location near;
	private int nearTiles;

	@Inject
	RunService(Client client, ItemManager itemManager, SettingsStore settings, AccessChecker accessChecker,
		PatchTracker patchTracker, HoldingsTracker holdingsTracker, RunOverrides overrides, RunTimings timings)
	{
		this.timings = timings;
		this.client = client;
		this.itemManager = itemManager;
		this.settings = settings;
		this.accessChecker = accessChecker;
		this.patchTracker = patchTracker;
		this.holdingsTracker = holdingsTracker;
		this.overrides = overrides;
	}

	public RunPlan getPlan()
	{
		final RunPlan current = plan;
		return current != null ? current : RunPlan.EMPTY;
	}

	public SupplyPlan getSupplies()
	{
		return getPlan().getSupplies();
	}

	/** Forget the last plan (login, account switch) so the next one is always published. Any thread. */
	public void reset()
	{
		plan = null;
		dirty = true;
	}

	/** Recalculate on the next game tick. Any thread. */
	public void markDirty()
	{
		dirty = true;
	}

	/**
	 * @return whether a new plan was made
	 */
	public boolean onGameTick()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return false;
		}
		final boolean holdingsChanged = holdingsTracker.rebuildIfDirty();
		final Location nowAt = standingAt();
		final Location nearNow = nearby();
		final boolean moved = nowAt != here || nearNow != near;
		here = nowAt;
		near = nearNow;
		if (moved)
		{
			log.debug("Route start: at {}, near {} ({} tiles)", here, near, nearTiles);
		}
		if (!holdingsChanged && !moved && !dirty && ++ticksSinceRefresh < REFRESH_TICKS)
		{
			return false;
		}
		dirty = false;
		ticksSinceRefresh = 0;

		final RunConfig config = settings.getRunConfig();
		final AccessSnapshot access = accessChecker.getSnapshot();
		final Holdings holdings = holdingsTracker.getHoldings();
		final RunSelection selection = RunSelector.select(config, access, patchTracker::predict,
			Instant.now().getEpochSecond(), config.isSupplyFullRun(), overrides.get());
		Route route = RoutePlanner.plan(selection.getPatches(), config, access, holdings,
			settings.getAccount().getPoh(), timings.learned(), here, near, nearTiles);
		SupplyPlan supplies = SupplyCalculator.calculate(config, access, holdings, selection, route,
			patchTracker::predict, this::itemName, itemManager::getItemPrice);
		// Starting at the stop the player stands at or near only makes sense if they can start from there: carrying
		// everything already, or with a bank close by. Otherwise (Kastori, still needing supplies) they'll bank
		// somewhere first, so plan from anywhere (Sean)
		final Location startStop = here != null ? here : near;
		if (startStop != null && TravelTimes.bankTiles(startStop) == null
			&& supplies.missingCount(startStop == Location.FARMING_GUILD) > 0)
		{
			route = RoutePlanner.plan(selection.getPatches(), config, access, holdings,
				settings.getAccount().getPoh(), timings.learned(), null, null, 0);
			supplies = SupplyCalculator.calculate(config, access, holdings, selection, route,
				patchTracker::predict, this::itemName, itemManager::getItemPrice);
		}
		// Too much for one inventory: bank partway, as often as needed, where it costs least
		final List<BankStop> bankStops = new ArrayList<>();
		if (supplies.getSlots() > SupplyCalculator.INVENTORY_SLOTS)
		{
			final Banked banked = bankStops(config, access, holdings, selection, route);
			if (banked != null)
			{
				route = banked.route;
				supplies = banked.first;
				bankStops.addAll(banked.stops);
			}
		}

		final Map<Location, List<String>> objectives = new EnumMap<>(Location.class);
		for (Patch patch : selection.getPatches())
		{
			objectives.computeIfAbsent(patch.getLocation(), k -> new ArrayList<>()).add(StepAdvisor.objectives(
				patch, patchTracker.predict(patch), supplies.getPlantings().get(patch)));
		}

		// What Auto (best) picks for every location, from anywhere, for the Travel tab
		final Map<Location, TravelPick> picks = new EnumMap<>(Location.class);
		for (Location location : Location.values())
		{
			final RouteStop pick = RoutePlanner.autoPick(location, config, access, holdings,
				settings.getAccount().getPoh(), timings.learned());
			final boolean tablet = pick.getMethod() != null && pick.getMethod().getSpell() != null
				&& SupplyCalculator.usesTablet(pick.getMethod().getSpell(), location, config, access, holdings);
			picks.put(location, new TravelPick(pick, tablet));
		}
		final boolean picksChanged = !picks.equals(autoPicks);
		autoPicks = picks;

		final RunPlan next = new RunPlan(selection, route, supplies, objectives,
			Collections.unmodifiableList(bankStops));
		if (next.equals(plan) && !picksChanged)
		{
			return false;
		}
		if ((plan == null || !next.getRoute().equals(plan.getRoute())
			|| !next.getBankStops().equals(plan.getBankStops())) && log.isDebugEnabled())
		{
			log.debug("Route planned:\n{}", explain(next));
		}
		plan = next;
		return true;
	}

	/**
	 * The route leg by leg with how each time was worked out, and where it banks, so a strange route can be
	 * explained from the log alone (docs/REBUILD.md).
	 */
	private static String explain(RunPlan plan)
	{
		final StringBuilder b = new StringBuilder();
		final List<RouteStop> stops = plan.getRoute().getStops();
		for (int i = 0; i < stops.size(); i++)
		{
			final RouteStop stop = stops.get(i);
			b.append(i + 1).append(". ").append(stop.getLocation().getDisplayName()).append(": ")
				.append(stop.describeTravel()).append(", ").append(Math.round(stop.getLegSeconds())).append(" s = ")
				.append(stop.getBreakdown()).append('\n');
			final BankStop bank = plan.bankAfter(i);
			if (bank != null)
			{
				b.append("   Bank: ").append(bank.how()).append(", ").append(bank.getSupplies().getSlots())
					.append(" slots for the next part\n");
			}
		}
		return b.append("Travel ").append(Math.round(plan.getRoute().getTravelSeconds())).append(" s, first part ")
			.append(plan.getSupplies().getSlots()).append(" slots").toString();
	}

	/** A run with its bank visits: the route, what to bring at the start, and each visit with what it takes. */
	private static final class Banked
	{
		final Route route;
		final SupplyPlan first;
		final List<BankStop> stops;

		Banked(Route route, SupplyPlan first, List<BankStop> stops)
		{
			this.route = route;
			this.first = first;
			this.stops = stops;
		}
	}

	/**
	 * Bank visits for a run too big for one inventory (see {@link BankPlanner}), with each part's supplies.
	 * Null if a part can't fit even on its own; the plan then warns about slots as before.
	 */
	private Banked bankStops(RunConfig config, AccessSnapshot access, Holdings holdings, RunSelection selection,
		Route route)
	{
		final PohSetup poh = settings.getAccount().getPoh();
		final List<RouteStop> stops = route.getStops();
		final Map<Long, Integer> slots = new HashMap<>();
		final BankPlanner.Slots slotsOf = (a, b) -> slots.computeIfAbsent((long) a * 1000 + b,
			k -> part(config, access, holdings, selection, stops.subList(a, b), route).getSlots());
		final BankPlanner.Result result = BankPlanner.place(route, slotsOf, SupplyCalculator.INVENTORY_SLOTS,
			BankTeleport.best(access, holdings),
			(from, to) -> RoutePlanner.chainSaving(from, to, config, access, holdings, poh, timings.learned()),
			to -> RoutePlanner.fromAnywhere(to, config, access, holdings, poh, timings.learned()));
		if (result == null || result.getVisits().isEmpty())
		{
			return null;
		}

		// Each part's supplies, counted against what the parts before it leave (seeds planted, runes cast), with
		// the teleport to bank with carried in the part before the bank
		final List<RouteStop> banked = result.getRoute().getStops();
		final List<BankPlanner.Visit> visits = result.getVisits();
		final List<SupplyPlan> parts = new ArrayList<>();
		int start = 0;
		Holdings left = holdings;
		for (int i = 0; i <= visits.size(); i++)
		{
			final int end = i < visits.size() ? visits.get(i).getAfterStop() + 1 : banked.size();
			SupplyPlan part = part(config, access, left, selection, banked.subList(start, end), result.getRoute());
			if (i < visits.size() && visits.get(i).getTeleport() != null)
			{
				part = withTeleport(part, visits.get(i).getTeleport(), left);
			}
			parts.add(part);
			left = part.leftAfter(left);
			start = end;
		}
		final List<BankStop> bankStops = new ArrayList<>();
		for (int i = 0; i < visits.size(); i++)
		{
			final BankPlanner.Visit v = visits.get(i);
			bankStops.add(new BankStop(v.getAfterStop(), v.getLocation(), parts.get(i + 1), v.getTeleport()));
		}

		// The guide needs every patch's crop, not only the first part's
		final Map<Patch, Crop> plantings = new EnumMap<>(Patch.class);
		for (SupplyPlan part : parts)
		{
			plantings.putAll(part.getPlantings());
		}
		final SupplyPlan first = parts.get(0);
		return new Banked(result.getRoute(), new SupplyPlan(first.getLines(), first.getPatchCounts(),
			first.getNotDue(), first.getTravelPlan(), first.getWarnings(), first.getCoins(), first.getRuneSummary(),
			first.getSlots(), Collections.unmodifiableMap(plantings)), bankStops);
	}

	/** The supplies for some of the route's stops on their own. */
	private SupplyPlan part(RunConfig config, AccessSnapshot access, Holdings holdings, RunSelection selection,
		List<RouteStop> stops, Route route)
	{
		return supplies(config, access, holdings, selection, patchesAt(selection, stops),
			new Route(new ArrayList<>(stops), route.getMode(), 0, 0));
	}

	/** A part's supplies with the bank teleport to bring, used at the bank that ends it. */
	private static SupplyPlan withTeleport(SupplyPlan before, BankTeleport teleport, Holdings holdings)
	{
		final int[] ids = teleport.getItemIds();
		final List<SupplyLine> lines = new ArrayList<>(before.getLines());
		lines.add(new SupplyLine(SupplyLine.Group.TRAVEL, teleport.getItemName() + " (bank partway)", 1,
			holdings.countAny(ids), holdings.carriedOnly().countAny(ids), holdings.where(ids),
			"To bank partway through the run: teleport to " + teleport.getBankName(), 1, false, null, ids));
		return new SupplyPlan(lines, before.getPatchCounts(), before.getNotDue(), before.getTravelPlan(),
			before.getWarnings(), before.getCoins(), before.getRuneSummary(), before.getSlots() + 1,
			before.getPlantings());
	}

	private static List<Patch> patchesAt(RunSelection selection, List<RouteStop> stops)
	{
		final Set<Location> at = EnumSet.noneOf(Location.class);
		for (RouteStop stop : stops)
		{
			at.add(stop.getLocation());
		}
		final List<Patch> patches = new ArrayList<>();
		for (Patch patch : selection.getPatches())
		{
			if (at.contains(patch.getLocation()))
			{
				patches.add(patch);
			}
		}
		return patches;
	}

	/** The supplies for some of the run's patches on their own. */
	private SupplyPlan supplies(RunConfig config, AccessSnapshot access, Holdings holdings, RunSelection selection,
		List<Patch> patches, Route route)
	{
		final RunSelection part = new RunSelection(patches, selection.getIncludedTypes(),
			selection.getSkippedTypes(), Collections.emptyList(), selection.getDueCounts());
		return SupplyCalculator.calculate(config, access, holdings, part, route, patchTracker::predict,
			this::itemName, itemManager::getItemPrice);
	}

	/**
	 * What some stops of a run in progress need, worked out afresh against what the player holds now: for spotting
	 * an item gone missing mid-run (Sean). Client thread.
	 */
	public SupplyPlan suppliesFor(RunPlan plan, List<RouteStop> stops)
	{
		return part(settings.getRunConfig(), accessChecker.getSnapshot(), holdingsTracker.getHoldings(),
			plan.getSelection(), stops, plan.getRoute());
	}

	/** The quickest bank teleport the player is carrying now, or null. Client thread. */
	public BankTeleport carriedBankTeleport()
	{
		return BankTeleport.best(accessChecker.getSnapshot(), holdingsTracker.getHoldings().carriedOnly());
	}

	/** Auto (best)'s pick for each location, from anywhere. Any thread. */
	public Map<Location, TravelPick> getAutoPicks()
	{
		return autoPicks;
	}

	/**
	 * Whether a spell is taken from its tablet at this location, by the same rule as the supply list. For
	 * labelling a teleport the player picked. Any thread.
	 */
	public boolean usesTablet(Spell spell, Location location)
	{
		return SupplyCalculator.usesTablet(spell, location, settings.getRunConfig(), accessChecker.getSnapshot(),
			holdingsTracker.getHoldings());
	}

	/** The stop the player is standing at (near one of its patches), or null. Client thread. */
	/**
	 * The stop whose patch is closest to walk to, if within {@link #NEARBY_TILES} walking tiles, so a run can start
	 * by walking there (e.g. from the Grand Tree to the Stronghold patches); sets {@link #nearTiles}. Another floor
	 * (the Grand Tree bank is upstairs) counts as a few tiles further.
	 */
	private Location nearby()
	{
		final Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null;
		}
		final WorldPoint location = player.getWorldLocation();
		Location best = null;
		int bestTiles = Integer.MAX_VALUE;
		// Only stops in the run: a nearby patch that isn't due shouldn't hide one a little further away
		final RunPlan current = plan;
		for (Map.Entry<Patch, WorldPoint> e : PatchPoints.all().entrySet())
		{
			if (current != null && !current.getSelection().getPatches().isEmpty()
				&& !current.getSelection().getPatches().contains(e.getKey()))
			{
				continue;
			}
			final WorldPoint point = e.getValue();
			// Walking distance from the measured grid (Sean: Castle Wars isn't near Lletya); straight-line only if
			// the grid didn't load
			final Integer walked = WalkGrid.loaded() ? WalkGrid.tiles(e.getKey().getLocation(), location) : null;
			if (WalkGrid.loaded() && walked == null)
			{
				continue;
			}
			final int tiles = walked != null ? walked
				: point.distanceTo2D(location) + (point.getPlane() != location.getPlane() ? 10 : 0);
			if (tiles <= NEARBY_TILES && tiles < bestTiles)
			{
				best = e.getKey().getLocation();
				bestTiles = tiles;
			}
		}
		nearTiles = best != null ? bestTiles : 0;
		return best;
	}

	private Location standingAt()
	{
		final Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null;
		}
		final WorldPoint location = player.getWorldLocation();
		for (Map.Entry<Patch, WorldPoint> e : PatchPoints.all().entrySet())
		{
			final WorldPoint point = e.getValue();
			if (point.getPlane() == location.getPlane() && point.distanceTo2D(location) <= STANDING_TILES)
			{
				return e.getKey().getLocation();
			}
		}
		return null;
	}

	/** The noted version of an item (or the item itself if it has none). Client thread. */
	public int notedId(int itemId)
	{
		final int noted = itemManager.getItemComposition(itemId).getLinkedNoteId();
		return noted > 0 ? noted : itemId;
	}

	/** An item's name, looked up once. Client thread. */
	public String itemName(int itemId)
	{
		return names.computeIfAbsent(itemId, id -> itemManager.getItemComposition(id).getName());
	}
}

package com.farmrunautopilot.route;

import com.farmrunautopilot.data.travel.Spell;
import lombok.Value;

/**
 * How a location is reached: the leg (teleport and how: directly, through the house, ...) and, for a spell
 * cast directly, whether its tablet is used. For the Travel tab's "Auto (best)" and override labels.
 */
@Value
public class TravelPick
{
	RouteStop stop;
	/** A spell taken from its tablet rather than cast from runes. */
	boolean tablet;

	/** e.g. "Camelot Teleport (tablet)", "House portal nexus: Catherby Teleport", "Walk". */
	public String describe()
	{
		final String travel = stop.describeTravel();
		final Spell spell = stop.getMethod() != null ? stop.getMethod().getSpell() : null;
		if (spell == null || stop.getDeparture() != Departure.DIRECT)
		{
			return travel;
		}
		return travel + (tablet ? " (tablet)" : " (runes)");
	}
}

package com.farmrunautopilot.route;

/**
 * The player's one-off choice for a run type, overriding the due threshold (SPEC 10).
 */
public enum TypeOverride
{
	/** Include it even though too few patches are due. */
	INCLUDE,
	/** Leave it out even though it is due. */
	SKIP
}

package com.farmrunautopilot.run;

import com.farmrunautopilot.settings.Outfit;
import com.farmrunautopilot.supply.Holdings;
import com.farmrunautopilot.supply.SupplyLine;
import com.farmrunautopilot.supply.SupplyPlan;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.IntUnaryOperator;
import lombok.Value;

/**
 * Banking and getting dressed for a part of the run (docs/REBUILD.md, Sprint 4): what to deposit at a bank visit,
 * and which teleport items and outfit to put on. Pure, so it can be tested without a client.
 */
final class BankGuide
{
	/** Items to put on, and how to say so. */
	@Value
	static class Wear
	{
		static final Wear NONE = new Wear(null, Collections.emptySet());

		/** e.g. "Wear: Graceful outfit, Ring of wealth", or null when there's nothing to put on. */
		String text;
		/** Inventory items to put on, to highlight in the wear colour. */
		Set<Integer> itemIds;
	}

	private BankGuide()
	{
	}

	/**
	 * Inventory items this part of the run doesn't need (produce, empty buckets, the last part's leftovers), to
	 * deposit. The holdings count noted items as unnoted, so each is also given noted, to outline whichever the
	 * player has.
	 *
	 * @param noted the noted version of an item (or the same item if it has none)
	 */
	static Set<Integer> toDeposit(SupplyPlan part, Holdings holdings, IntUnaryOperator noted)
	{
		final Set<Integer> needed = new HashSet<>();
		for (SupplyLine line : part.getLines())
		{
			for (int id : line.getItemIds())
			{
				needed.add(id);
			}
		}
		final Set<Integer> deposit = new LinkedHashSet<>();
		for (Map.Entry<Integer, Integer> e : holdings.in(Holdings.Source.INVENTORY).entrySet())
		{
			final int id = e.getKey();
			if (e.getValue() > 0 && !needed.contains(id))
			{
				deposit.add(id);
				deposit.add(noted.applyAsInt(id));
			}
		}
		return deposit;
	}

	/**
	 * What to put on for this part of the run: its teleport items marked to wear and its outfit, that are in the
	 * inventory but not worn. Items still in the bank are left to the bank tab.
	 */
	static Wear wear(SupplyPlan part, Holdings holdings, Outfit outfit)
	{
		final Map<Integer, Integer> inventory = holdings.in(Holdings.Source.INVENTORY);
		final Map<Integer, Integer> worn = holdings.in(Holdings.Source.WORN);
		final List<String> names = new ArrayList<>();
		final Set<Integer> ids = new LinkedHashSet<>();
		for (SupplyLine line : part.getLines())
		{
			// Teleport items, the staff and magic secateurs; the outfit is handled below, piece by piece
			if (!line.isWear() || line.getName().equals(outfit.getDisplayName()) || any(line.getItemIds(), worn))
			{
				continue;
			}
			if (any(line.getItemIds(), inventory))
			{
				names.add(line.getName());
				for (int id : line.getItemIds())
				{
					if (inventory.getOrDefault(id, 0) > 0)
					{
						ids.add(id);
					}
				}
			}
		}
		// The outfit: every piece held in the inventory and not already worn
		boolean outfitToWear = false;
		for (int[] piece : outfit.getPieces())
		{
			if (!any(piece, worn) && any(piece, inventory))
			{
				outfitToWear = true;
				for (int id : piece)
				{
					if (inventory.getOrDefault(id, 0) > 0)
					{
						ids.add(id);
					}
				}
			}
		}
		if (outfitToWear)
		{
			names.add(0, outfit.getDisplayName());
		}
		return names.isEmpty() ? Wear.NONE : new Wear("Wear: " + String.join(", ", names), ids);
	}

	private static boolean any(int[] ids, Map<Integer, Integer> counts)
	{
		for (int id : ids)
		{
			if (counts.getOrDefault(id, 0) > 0)
			{
				return true;
			}
		}
		return false;
	}
}

package com.farmrunautopilot.run;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Text under the player: what to do next, and the run timer (SPEC 13.4). Only reads the session's
 * precomputed view, so rendering stays cheap.
 */
public class GuidanceOverlay extends Overlay
{
	private static final Color INSTRUCTION = new Color(0xFF, 0xD7, 0x00);
	private static final Color TIMER = Color.WHITE;
	private static final Color REMINDER = new Color(0xFF, 0x98, 0x1F);
	/** Long instructions wrap at this width (pixels). */
	private static final int MAX_LINE_WIDTH = 360;
	/** Pixels below the player's feet for the first line, and between lines. */
	private static final int FIRST_LINE_OFFSET = 18;
	private static final int LINE_HEIGHT = 15;

	private final Client client;
	private final RunSession session;

	@Inject
	GuidanceOverlay(Client client, RunSession session)
	{
		this.client = client;
		this.session = session;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final RunView view = session.getView();
		final String instruction = view.getInstruction();
		final Player player = client.getLocalPlayer();
		if (instruction == null || player == null)
		{
			return null;
		}

		graphics.setFont(FontManager.getRunescapeBoldFont());
		final int maxWidth = Math.min(MAX_LINE_WIDTH, client.getCanvasWidth() - 40);
		int line = 0;
		// The run clock is on the Run tab, so it isn't repeated here (Sean)
		if (view.getState() == RunView.State.ARMED)
		{
			draw(graphics, player, "Timer starts when you leave", TIMER, line++);
		}
		for (String text : wrap(graphics.getFontMetrics(), instruction, maxWidth))
		{
			draw(graphics, player, text, INSTRUCTION, line++);
		}
		// What to put on, in the same colour as its item highlight
		if (view.getWear() != null)
		{
			for (String text : wrap(graphics.getFontMetrics(), view.getWear(), maxWidth))
			{
				draw(graphics, player, text, ItemHighlightOverlay.WEAR_COLOUR, line++);
			}
		}
		if (view.getReminder() != null)
		{
			for (String reminder : view.getReminder().split("\n"))
			{
				for (String text : wrap(graphics.getFontMetrics(), reminder, maxWidth))
				{
					draw(graphics, player, text, REMINDER, line++);
				}
			}
		}
		return null;
	}

	/** Splits text into lines no wider than maxWidth pixels, breaking between words. */
	static List<String> wrap(FontMetrics metrics, String text, int maxWidth)
	{
		final List<String> lines = new ArrayList<>();
		final StringBuilder current = new StringBuilder();
		for (String word : text.split(" "))
		{
			if (current.length() > 0 && metrics.stringWidth(current + " " + word) > maxWidth)
			{
				lines.add(current.toString());
				current.setLength(0);
			}
			if (current.length() > 0)
			{
				current.append(' ');
			}
			current.append(word);
		}
		if (current.length() > 0)
		{
			lines.add(current.toString());
		}
		return lines;
	}

	private static void draw(Graphics2D graphics, Player player, String text, Color colour, int line)
	{
		final Point feet = player.getCanvasTextLocation(graphics, text, 0);
		if (feet != null)
		{
			OverlayUtil.renderTextLocation(graphics,
				new Point(feet.getX(), feet.getY() + FIRST_LINE_OFFSET + line * LINE_HEIGHT), text, colour);
		}
	}

	/** e.g. "4:07" or "1:02:30". */
	public static String clock(long seconds)
	{
		final long h = seconds / 3600;
		final long m = (seconds % 3600) / 60;
		final long s = seconds % 60;
		return h > 0 ? String.format("%d:%02d:%02d", h, m, s) : String.format("%d:%02d", m, s);
	}
}

package com.farmrunautopilot.run;

import com.farmrunautopilot.FarmRunAutopilotConfig;
import com.farmrunautopilot.data.PatchPoints;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.Perspective;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Outlines the patch the current step is about and, when paying, the gardener (SPEC 13.4). Reads only the
 * session's precomputed highlights and the tracked objects, so each frame is cheap.
 */
public class HighlightOverlay extends Overlay
{
	private static final int OUTLINE_WIDTH = 2;
	private static final int OUTLINE_FEATHER = 2;

	private final Client client;
	private final RunSession session;
	private final SceneTracker scene;
	private final FarmRunAutopilotConfig config;
	private final ModelOutlineRenderer outlines;

	@Inject
	HighlightOverlay(Client client, RunSession session, SceneTracker scene, FarmRunAutopilotConfig config,
		ModelOutlineRenderer outlines)
	{
		this.client = client;
		this.session = session;
		this.scene = scene;
		this.config = config;
		this.outlines = outlines;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final Highlights highlights = session.getView().getHighlights();
		if (highlights.getPatch() != null && config.highlightPatch())
		{
			final List<GameObject> objects = scene.objectsFor(highlights.getPatch());
			if (objects.isEmpty())
			{
				// Not matched to an object (or not loaded yet): mark the patch's tile instead
				markTile(graphics, PatchPoints.of(highlights.getPatch()));
			}
			for (GameObject object : objects)
			{
				outlines.drawOutline(object, OUTLINE_WIDTH, config.patchColour(), OUTLINE_FEATHER);
			}
		}
		if (highlights.isGardener() && config.highlightGardener())
		{
			final NPC gardener = scene.gardener(highlights.getPatch());
			if (gardener != null)
			{
				outlines.drawOutline(gardener, OUTLINE_WIDTH, config.npcColour(), OUTLINE_FEATHER);
			}
		}
		if (highlights.getTravelNpc() != null && config.highlightGardener())
		{
			// The ride after the teleport, e.g. the Civitas quetzal
			final NPC ride = scene.transferNpc(highlights.getTravelNpc());
			if (ride != null)
			{
				outlines.drawOutline(ride, OUTLINE_WIDTH, config.npcColour(), OUTLINE_FEATHER);
			}
		}
		return null;
	}

	private void markTile(Graphics2D graphics, WorldPoint point)
	{
		if (point == null)
		{
			return;
		}
		final LocalPoint local = LocalPoint.fromWorld(client.getTopLevelWorldView(), point);
		if (local == null)
		{
			return;
		}
		final Polygon tile = Perspective.getCanvasTilePoly(client, local);
		if (tile != null)
		{
			OverlayUtil.renderPolygon(graphics, tile, config.patchColour());
		}
	}
}

package com.farmrunautopilot.run;

import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.travel.Spell;
import java.util.Collections;
import java.util.Set;
import lombok.Value;

/**
 * What the current step points at in the game (SPEC 13.4): the patch, the gardener, the items to use and the
 * spell to cast. Immutable, so overlays can read it every frame without locking.
 */
@Value
public class Highlights
{
	public static final Highlights NONE = new Highlights(null, false, null, Collections.emptySet(), null);

	/** The patch to outline and point the hint arrow at, or null while travelling. */
	Patch patch;
	/** Outline the patch's gardener (paying them). */
	boolean gardener;
	/** The name of an NPC to outline while travelling (Renu, the Civitas quetzal), or null. */
	String travelNpc;
	/** Items to outline in the inventory and equipment. */
	Set<Integer> itemIds;
	/** The spell to outline in the spellbook, or null. */
	Spell spell;
	/** Items to put on, outlined in their own colour with a "Wear" label, never as an item to use. */
	Set<Integer> wearItemIds;

	public Highlights(Patch patch, boolean gardener, String travelNpc, Set<Integer> itemIds, Spell spell)
	{
		this(patch, gardener, travelNpc, itemIds, spell, Collections.emptySet());
	}

	public Highlights(Patch patch, boolean gardener, String travelNpc, Set<Integer> itemIds, Spell spell,
		Set<Integer> wearItemIds)
	{
		this.patch = patch;
		this.gardener = gardener;
		this.travelNpc = travelNpc;
		this.itemIds = itemIds;
		this.spell = spell;
		this.wearItemIds = wearItemIds;
	}
}

package com.farmrunautopilot.run;

import com.farmrunautopilot.FarmRunAutopilotConfig;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.PatchPoints;
import java.util.List;
import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

/**
 * Points the game's hint arrow (which also shows on the minimap) at the current patch. Only touches the
 * arrow when the target changes, and only clears an arrow it set itself. Client thread only.
 */
@Singleton
public class HintArrowController
{
	private final Client client;
	private final RunSession session;
	private final SceneTracker scene;
	private final FarmRunAutopilotConfig config;
	/** Where our arrow is, or null if we haven't set one. */
	private LocalPoint shown;

	@Inject
	HintArrowController(Client client, RunSession session, SceneTracker scene, FarmRunAutopilotConfig config)
	{
		this.client = client;
		this.session = session;
		this.scene = scene;
		this.config = config;
	}

	/** Call every game tick, after the run session has updated. */
	public void update()
	{
		final Patch patch = session.getView().getHighlights().getPatch();
		final LocalPoint target = patch != null && config.hintArrow() ? pointFor(patch) : null;
		if (Objects.equals(target, shown))
		{
			return;
		}
		if (target == null)
		{
			clear();
			return;
		}
		client.setHintArrow(target);
		shown = target;
	}

	/** Remove our arrow, if it's still up and nothing else has replaced it with an NPC or player arrow. */
	public void clear()
	{
		if (shown != null)
		{
			if (client.hasHintArrow() && client.getHintArrowNpc() == null && client.getHintArrowPlayer() == null)
			{
				client.clearHintArrow();
			}
			shown = null;
		}
	}

	/** The middle of the patch: a game object's location is its centre, so a 2x2 herb patch gets the middle of 4 tiles. */
	private LocalPoint pointFor(Patch patch)
	{
		final List<GameObject> objects = scene.objectsFor(patch);
		if (!objects.isEmpty())
		{
			return objects.get(0).getLocalLocation();
		}
		final WorldPoint point = PatchPoints.of(patch);
		return point == null ? null : LocalPoint.fromWorld(client.getTopLevelWorldView(), point);
	}
}

package com.farmrunautopilot.run;

import com.farmrunautopilot.FarmRunAutopilotConfig;
import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Outlines the item to use next in the inventory and equipment: seed, compost, tool, payment or teleport
 * (SPEC 13.4). Items to put on get their own colour and a "Wear" label, so an item to wear is never mistaken for
 * the next teleport.
 */
public class ItemHighlightOverlay extends WidgetItemOverlay
{
	private static final int MAX_CACHED_OUTLINES = 100;
	/** Items to put on: a colour no other highlight uses. */
	static final Color WEAR_COLOUR = new Color(0x40, 0xC8, 0xFF);
	private static final String WEAR_LABEL = "Wear";
	private static final Color LABEL_BACKGROUND = new Color(0, 0, 0, 170);

	private final RunSession session;
	private final FarmRunAutopilotConfig config;
	private final ItemManager itemManager;
	/**
	 * Outline images, made once per item, stack size and colour rather than every frame; cleared when the colour
	 * changes.
	 */
	private final Map<String, BufferedImage> outlineCache = new HashMap<>();

	@Inject
	ItemHighlightOverlay(RunSession session, FarmRunAutopilotConfig config, ItemManager itemManager)
	{
		this.session = session;
		this.config = config;
		this.itemManager = itemManager;
		showOnInventory();
		showOnEquipment();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!config.highlightItems())
		{
			return;
		}
		final Highlights highlights = session.getView().getHighlights();
		final boolean wear = highlights.getWearItemIds().contains(itemId);
		if (!wear && !highlights.getItemIds().contains(itemId))
		{
			return;
		}
		final Color colour = wear ? WEAR_COLOUR : config.itemColour();
		// Stacks change picture with their size (a pile of seeds, a heap of coins), so the outline depends on it
		final int quantity = widgetItem.getQuantity();
		final String key = itemId + ":" + quantity + ":" + wear;
		if (outlineCache.size() > MAX_CACHED_OUTLINES && !outlineCache.containsKey(key))
		{
			outlineCache.clear();
		}
		final BufferedImage outline = outlineCache.computeIfAbsent(key,
			k -> itemManager.getItemOutline(itemId, quantity, colour));
		final Rectangle bounds = widgetItem.getCanvasBounds();
		graphics.drawImage(outline, (int) bounds.getX(), (int) bounds.getY(), null);
		if (wear)
		{
			drawLabel(graphics, bounds);
		}
	}

	/** "Wear" on a dark strip along the bottom of the slot, outlined all round, so it reads on pale items too. */
	private static void drawLabel(Graphics2D graphics, Rectangle bounds)
	{
		graphics.setFont(FontManager.getRunescapeSmallFont());
		final FontMetrics metrics = graphics.getFontMetrics();
		final int width = metrics.stringWidth(WEAR_LABEL);
		final int x = (int) bounds.getCenterX() - width / 2;
		final int y = (int) bounds.getMaxY() - 1;
		graphics.setColor(LABEL_BACKGROUND);
		graphics.fillRect(x - 2, y - metrics.getAscent(), width + 4, metrics.getAscent() + 2);
		graphics.setColor(Color.BLACK);
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				if (dx != 0 || dy != 0)
				{
					graphics.drawString(WEAR_LABEL, x + dx, y + dy);
				}
			}
		}
		graphics.setColor(WEAR_COLOUR);
		graphics.drawString(WEAR_LABEL, x, y);
	}

	/** Forget cached outlines (colour changed, plugin stopped). */
	public void clearCache()
	{
		outlineCache.clear();
	}
}

package com.farmrunautopilot.run;

import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.travel.JourneyStep;
import com.farmrunautopilot.data.travel.TravelMethod;
import com.farmrunautopilot.route.Departure;
import com.farmrunautopilot.route.RouteStop;
import com.farmrunautopilot.tracking.PatchTracker;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;

/**
 * Getting to the current stop (docs/REBUILD.md, Sprint 4): spots the teleport landing, steps through the
 * journey after it (a boat, a quetzal, Elkoy), notices arriving at the stop's patches, and says where the
 * walk goes for Shortest Path. One stop at a time; {@link #nextStop()} starts over. Client thread.
 */
@Singleton
class Navigator
{
	/** Further than this from a patch and the step starts with "Run to the ... patch". */
	static final int NEAR_PATCH_TILES = 7;
	/** Running covers 2 tiles a tick, so a bigger move in one tick is a teleport. */
	private static final int JUMP_TILES = 10;
	/** A teleport landing this close to the stop's patch counts as having arrived in the area. */
	private static final int LANDED_NEAR_TILES = 150;
	/** A journey step's walk is done this close to where it goes. */
	private static final int JOURNEY_NEAR_TILES = 4;
	/** A teleport landing this close to a journey's first step counts as having arrived in the area. */
	private static final int FIRST_STEP_LANDING_TILES = 60;
	/** The quetzal that flies between Varlamore landing pads, matched by name. */
	static final String RENU = "Renu";

	private final Client client;
	private final PatchTracker patchTracker;
	private final SceneTracker scene;

	private boolean arrived;
	/** When the player reached the current stop (epoch seconds); patches must be seen after this to count. */
	private long arrivedAtSeconds;
	/** Teleported close to the current stop but its patch hasn't loaded yet. */
	private boolean teleported;
	/** How many of the travel method's journey steps (boat, quetzal, Elkoy...) are done since landing. */
	private int journeyStep;
	/** The player's position last tick, to spot teleports. */
	private WorldPoint lastPosition;

	@Inject
	Navigator(Client client, PatchTracker patchTracker, SceneTracker scene)
	{
		this.client = client;
		this.patchTracker = patchTracker;
		this.scene = scene;
	}

	/** A new run: nothing travelled yet. */
	void reset()
	{
		nextStop();
		lastPosition = null;
	}

	/** On to the next stop. */
	void nextStop()
	{
		arrived = false;
		teleported = false;
		journeyStep = 0;
	}

	boolean isArrived()
	{
		return arrived;
	}

	/** Landed from the teleport (or set off on foot); the journey steps come next. */
	boolean isTeleported()
	{
		return teleported;
	}

	/** How many of the travel method's journey steps are done since landing. */
	int getJourneyStep()
	{
		return journeyStep;
	}

	long getArrivedAtSeconds()
	{
		return arrivedAtSeconds;
	}

	void markArrived(long nowMillis)
	{
		arrived = true;
		arrivedAtSeconds = nowMillis / 1000;
	}

	/**
	 * "Mark done" while travelling: on one step at a time, the teleport, then each journey step (Sean: it skipped
	 * them all). After the last one the stop counts as reached, so the patch's own "Walk to the ... patch" is next.
	 */
	void markStepDone(RouteStop stop, long nowMillis)
	{
		if (arrived)
		{
			return;
		}
		final int journey = journeySteps(stop);
		if (!teleported)
		{
			teleported = true;
			if (journey == 0)
			{
				markArrived(nowMillis);
			}
		}
		else if (journeyStep < journey - 1)
		{
			journeyStep++;
		}
		else
		{
			journeyStep = journey;
			markArrived(nowMillis);
		}
	}

	/**
	 * A travel step ticked by hand is unticked: back to it, so it and the steps after it are to do again (the
	 * landing or arrival is spotted again if it did happen).
	 *
	 * @param step 0 for the way there, 1 on for the journey steps after it
	 */
	void rewindTo(int step)
	{
		arrived = false;
		teleported = step > 0;
		journeyStep = Math.max(0, step - 1);
	}

	/** How many journey steps follow the way there (a boat, Elkoy...); none for a walk. */
	static int journeySteps(RouteStop stop)
	{
		return stop.getMethod() == null || stop.getDeparture() == Departure.WALK ? 0 : stop.getMethod().getRides().size();
	}

	/**
	 * Follow the travel to this stop for one tick.
	 *
	 * @param here the stop's patches in the run
	 * @return the travel step to show, or null once arrived
	 */
	String travel(RouteStop stop, List<Patch> here, long nowMillis)
	{
		final Player player = client.getLocalPlayer();
		final WorldPoint position = player != null ? player.getWorldLocation() : null;
		final WorldPoint previous = lastPosition;
		lastPosition = position;
		if (arrived)
		{
			return null;
		}
		if (inRange(here))
		{
			// Teleported straight into range still counts as teleported, so the way there shows as done; walking in,
			// or being there already, doesn't
			if (jumped(previous, position))
			{
				teleported = true;
			}
			markArrived(nowMillis);
			return null;
		}
		// A walk from the last stop (Falador Park to Taverley, or to a stop near the start) has nothing to travel to
		// first: arrived straight away, so the patch's own "Walk to the ... patch" is the one step, with its walking
		// line (Sean: it took two Mark done presses)
		if (stop.getDeparture() == Departure.WALK)
		{
			markArrived(nowMillis);
			return null;
		}
		if (!teleported && (jumpedTowards(previous, position, here.get(0)) || jumpedToFirstStep(stop, previous, position)))
		{
			teleported = true;
		}
		else if (teleported && journeyStepDone(journeyStep(stop), previous, position))
		{
			journeyStep++;
		}
		final JourneyStep step = journeyStep(stop);
		return !teleported ? stop.describeWay() + " to " + stop.getLocation().getDisplayName()
			: step != null ? step.textFor(client.getBoostedSkillLevel(Skill.AGILITY))
			: withDirections(stop, walkInstruction(here.get(0)));
	}

	/**
	 * The stop's walking directions (rocks, gates, stairs) for the player's Agility level, e.g. "Climb the Rocks
	 * beside the entrance up to the roof (73 Agility)"; null if none or it's a walk from the last stop.
	 */
	String directions(RouteStop stop)
	{
		if (stop.getMethod() == null || stop.getDeparture() == Departure.WALK || stop.getMethod().getDirections().isEmpty())
		{
			return null;
		}
		final int agility = client.getBoostedSkillLevel(Skill.AGILITY);
		final List<String> parts = new ArrayList<>();
		for (JourneyStep step : stop.getMethod().getDirections())
		{
			parts.add(step.textFor(agility));
		}
		return String.join(", then ", parts);
	}

	/** e.g. "Climb the Rocks ... (73 Agility), then walk to the ... patch": the directions first, if any. */
	String withDirections(RouteStop stop, String step)
	{
		final String directions = directions(stop);
		return directions == null ? step
			: directions + ", then " + Character.toLowerCase(step.charAt(0)) + step.substring(1);
	}

	/**
	 * Where the travel says to walk, for Shortest Path: back to Renu's landing pad, to the boat or NPC of a
	 * journey step, or to the stop's nearest patch after landing. Null while teleporting or riding.
	 */
	WorldPoint travelTarget(RouteStop stop, List<Patch> here)
	{
		if (!teleported)
		{
			// A Renu leg starts with the walk back to the landing pad
			final NPC renu = renuFirst(stop) ? scene.transferNpc(RENU) : null;
			return renu != null ? renu.getWorldLocation() : null;
		}
		final JourneyStep step = journeyStep(stop);
		final WorldPoint stepAt = step != null ? journeyTarget(step) : null;
		if (stepAt != null)
		{
			// To the boat, quetzal or NPC: where it stands once loaded, else where it's expected
			return stepAt;
		}
		final List<Patch> ordered = nearestFirst(here, null);
		return ordered.isEmpty() ? null : scene.locationOf(ordered.get(0));
	}

	/** The NPC to outline while travelling (Renu before a Renu flight, a journey step's NPC), or null. */
	String travelNpc(RouteStop stop)
	{
		if (renuFirst(stop))
		{
			return RENU;
		}
		final JourneyStep step = journeyStep(stop);
		return step != null ? step.getNpc() : null;
	}

	/**
	 * A stop's patches, closest to the player first, so nobody runs past one patch to reach another (Catherby's
	 * herb patch is on the way from the Camelot teleport to the fruit tree). The patch already being worked on
	 * stays first until it's done, so the step doesn't flip between patches while walking.
	 */
	List<Patch> nearestFirst(List<Patch> here, Patch current)
	{
		final Player player = client.getLocalPlayer();
		final WorldPoint at = player != null ? player.getWorldLocation() : null;
		final List<Patch> ordered = new ArrayList<>(here);
		if (at != null)
		{
			ordered.sort(Comparator.comparingInt(p ->
			{
				final WorldPoint point = scene.locationOf(p);
				return point == null || point.getPlane() != at.getPlane() ? Integer.MAX_VALUE : point.distanceTo2D(at);
			}));
		}
		if (current != null && ordered.remove(current))
		{
			ordered.add(0, current);
		}
		return ordered;
	}

	boolean inRange(List<Patch> here)
	{
		final Set<Patch> inRange = patchTracker.getPatchesInRange();
		for (Patch patch : here)
		{
			if (inRange.contains(patch))
			{
				return true;
			}
		}
		return false;
	}

	boolean nearAny(List<Patch> here)
	{
		for (Patch patch : here)
		{
			if (!farFrom(patch))
			{
				return true;
			}
		}
		return false;
	}

	boolean farFrom(Patch patch)
	{
		final Player player = client.getLocalPlayer();
		final WorldPoint point = scene.locationOf(patch);
		return player != null && point != null && player.getWorldLocation().distanceTo(point) > NEAR_PATCH_TILES;
	}

	/**
	 * A teleport (or other jump) that landed near the stop: the position changed by more than running could in
	 * one tick, and the patch is now close. Some teleports land too far out for the patch to load yet
	 * (Trollheim), so without this the step would keep saying to teleport.
	 */
	private boolean jumpedTowards(WorldPoint from, WorldPoint to, Patch patch)
	{
		final WorldPoint target = scene.locationOf(patch);
		return jumped(from, to) && target != null && target.getPlane() == to.getPlane()
			&& target.distanceTo2D(to) <= LANDED_NEAR_TILES;
	}

	/** The position changed by more than running could in one tick: a teleport, ride or plane change. */
	private static boolean jumped(WorldPoint from, WorldPoint to)
	{
		return from != null && to != null && (from.getPlane() != to.getPlane() || from.distanceTo2D(to) > JUMP_TILES);
	}

	/** This leg is a Renu flight not taken yet: the way starts at the quetzal on the landing pad. */
	private boolean renuFirst(RouteStop stop)
	{
		return stop.getDeparture() == Departure.RENU && !teleported && !arrived;
	}

	/** The journey step to do now, after the teleport and before the walk to the patch, or null. */
	private JourneyStep journeyStep(RouteStop stop)
	{
		final TravelMethod method = stop.getMethod();
		return teleported && !arrived && method != null && journeyStep < method.getRides().size()
			? method.getRides().get(journeyStep) : null;
	}

	/**
	 * A teleport that landed by the journey's first step rather than near the patch, e.g. the Mining Guild,
	 * which is underground with coordinates far from Falador Park.
	 */
	private boolean jumpedToFirstStep(RouteStop stop, WorldPoint from, WorldPoint to)
	{
		final TravelMethod method = stop.getMethod();
		if (method == null || method.getRides().isEmpty() || !jumped(from, to))
		{
			return false;
		}
		final WorldPoint at = method.getRides().get(0).getAt();
		return at != null && at.getPlane() == to.getPlane() && at.distanceTo2D(to) <= FIRST_STEP_LANDING_TILES;
	}

	/** A ride is done when the player is moved; a walk when they get close to where it goes. */
	private boolean journeyStepDone(JourneyStep step, WorldPoint from, WorldPoint to)
	{
		if (step == null || to == null)
		{
			return false;
		}
		if (step.getKind() == JourneyStep.Kind.RIDE)
		{
			return jumped(from, to);
		}
		final WorldPoint target = journeyTarget(step);
		return target != null && target.getPlane() == to.getPlane() && target.distanceTo2D(to) <= JOURNEY_NEAR_TILES;
	}

	/** Where a journey step happens: its NPC's spot once loaded, otherwise the expected spot. */
	private WorldPoint journeyTarget(JourneyStep step)
	{
		final NPC npc = step.getNpc() != null ? scene.transferNpc(step.getNpc()) : null;
		return npc != null ? npc.getWorldLocation() : step.getAt();
	}

	/** After teleporting: the way on from the landing spot, e.g. "Walk to the Troll Stronghold herb patch". */
	private static String walkInstruction(Patch patch)
	{
		return "Walk to the " + patch.getDisplayName() + " patch";
	}
}

