 * Outlines the spell to cast next in the spellbook (SPEC 13.4): the teleport while travelling, Teleport to
 * House for routes through the house, or Cure Plant on a diseased patch. Only drawn while the spellbook is
 * open and the spell is on it.
 */
public class SpellHighlightOverlay extends Overlay
{
	/** Each spell's button in the spellbook. */
	private static final Map<Spell, Integer> BUTTONS = new EnumMap<>(Spell.class);

	static
	{
		BUTTONS.put(Spell.LUMBRIDGE_HOME_TELEPORT, InterfaceID.MagicSpellbook.TELEPORT_HOME_STANDARD);
		BUTTONS.put(Spell.VARROCK_TELEPORT, InterfaceID.MagicSpellbook.VARROCK_TELEPORT);
		BUTTONS.put(Spell.LUMBRIDGE_TELEPORT, InterfaceID.MagicSpellbook.LUMBRIDGE_TELEPORT);
		BUTTONS.put(Spell.FALADOR_TELEPORT, InterfaceID.MagicSpellbook.FALADOR_TELEPORT);
		BUTTONS.put(Spell.TELEPORT_TO_HOUSE, InterfaceID.MagicSpellbook.TELEPORT_TO_YOUR_HOUSE);
		BUTTONS.put(Spell.CAMELOT_TELEPORT, InterfaceID.MagicSpellbook.CAMELOT_TELEPORT);
		BUTTONS.put(Spell.ARDOUGNE_TELEPORT, InterfaceID.MagicSpellbook.ARDOUGNE_TELEPORT);
		BUTTONS.put(Spell.CIVITAS_ILLA_FORTIS_TELEPORT, InterfaceID.MagicSpellbook.FORTIS_TELEPORT);
		BUTTONS.put(Spell.TROLLHEIM_TELEPORT, InterfaceID.MagicSpellbook.TROLLHEIM_TELEPORT);
		BUTTONS.put(Spell.DRAYNOR_MANOR_TELEPORT, InterfaceID.MagicSpellbook.TELEPORT_DRAYNOR_MANOR);
		BUTTONS.put(Spell.BATTLEFRONT_TELEPORT, InterfaceID.MagicSpellbook.TELEPORT_BATTLEFRONT);
		BUTTONS.put(Spell.FENKENSTRAINS_CASTLE_TELEPORT, InterfaceID.MagicSpellbook.TELEPORT_FENKENSTRAIN_CASTLE);
		BUTTONS.put(Spell.HARMONY_ISLAND_TELEPORT, InterfaceID.MagicSpellbook.TELEPORT_HARMONY_ISLAND);
		BUTTONS.put(Spell.RESURRECT_CROPS, InterfaceID.MagicSpellbook.RESURRECT_CROPS);
		// UNVERIFIED: Kharyrll is assumed to be the third Ancient teleport button (Paddewwa, Senntisten, Kharyrll)
		BUTTONS.put(Spell.KHARYRLL_TELEPORT, InterfaceID.MagicSpellbook.ZAROSTELEPORT3);
		BUTTONS.put(Spell.CURE_PLANT, InterfaceID.MagicSpellbook.CURE_PLANT);
		BUTTONS.put(Spell.FERTILE_SOIL, InterfaceID.MagicSpellbook.FERTILE_SOIL);
		BUTTONS.put(Spell.FISHING_GUILD_TELEPORT, InterfaceID.MagicSpellbook.TELE_FISH);
		BUTTONS.put(Spell.CATHERBY_TELEPORT, InterfaceID.MagicSpellbook.TELE_CATHER);
		BUTTONS.put(Spell.SPELLBOOK_SWAP, InterfaceID.MagicSpellbook.SPELLBOOK_SWAP);
	}

	private final Client client;
	private final RunSession session;
	private final FarmRunAutopilotConfig config;

	@Inject
	SpellHighlightOverlay(Client client, RunSession session, FarmRunAutopilotConfig config)
	{
		this.client = client;
		this.session = session;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	/** The spellbook button for a spell, or null if there isn't one. */
	static Integer buttonFor(Spell spell)
	{
		return BUTTONS.get(spell);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final Spell spell = session.getView().getHighlights().getSpell();
		if (spell == null || !config.highlightSpell())
		{
			return null;
		}
		final Integer button = BUTTONS.get(spell);
		final Widget widget = button != null ? client.getWidget(button) : null;
		if (widget == null || widget.isHidden())
		{
			return null;
		}
		final Rectangle bounds = widget.getBounds();
		graphics.setColor(config.itemColour());
		graphics.setStroke(new BasicStroke(2));
		graphics.drawRect(bounds.x, bounds.y, bounds.width, bounds.height);
		return null;
	}
}

package com.farmrunautopilot.run;

import com.farmrunautopilot.data.Crop;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.PatchType;
import com.farmrunautopilot.settings.Compost;
import com.farmrunautopilot.tracking.PatchPrediction;
import java.util.ArrayList;
import java.util.List;
import lombok.Value;

/**
 * What to do next at a patch, worked out from its live state (SPEC 13.4). Working from the state rather
 * than a fixed checklist means the guide keeps up if the player does things in another order or the game
 * does them (a gardener clearing a tree, weeds growing back).
 */
public final class StepAdvisor
{
	public enum Action
	{
		/** No data for the patch yet; walk up to it. */
		INSPECT,
		RAKE,
		CLEAR_DEAD,
		CURE,
		/** A diseased tree or fruit tree: pruned with secateurs, not cured with plant cure. */
		PRUNE,
		CHECK_HEALTH,
		PICK,
		PAY_TO_CLEAR,
		CHOP,
		DIG_STUMP,
		COMPOST,
		PLANT,
		PAY,
		DONE
	}

	@Value
	public static class Advice
	{
		Action action;
		String text;
	}

	/** What the run plan wants at a patch, and what has happened there this run. */
	@Value
	public static class PatchGoal
	{
		Patch patch;
		Crop crop;
		/** Seed or sapling item name, e.g. "Ranarr seed". */
		String plantName;
		Compost compost;
		/** The gardener must be paid for this patch. */
		boolean protectionNeeded;
		/** e.g. "25 x Coconut (noted is fine)". */
		String paymentText;
		boolean payToClear;
		boolean composted;
		boolean paid;
		/** Seen empty, ready or dead during this run, so a growing crop was planted this run. */
		boolean plantedThisRun;
	}

	private StepAdvisor()
	{
	}

	public static Advice advise(PatchGoal goal, PatchPrediction live)
	{
		final Patch patch = goal.getPatch();
		if (live == null)
		{
			return new Advice(Action.INSPECT, "Walk to the " + patch.getDisplayName() + " patch");
		}
		final String gardener = patch.getGardenerName() != null ? patch.getGardenerName() : "the gardener";
		final String what = live.getCrop() != null ? live.getCrop().getDisplayName().toLowerCase() : "plant";
		final boolean tree = patch.getType().isProtectable();

		switch (live.getState())
		{
			case GROWING:
				// Compost and payment are only asked for if it was planted this run; otherwise it was already
				// growing. Compost works before or after planting, so planting first still leaves it to do.
				if (goal.isPlantedThisRun() && wantsCompost(goal))
				{
					return compost(goal);
				}
				if (goal.isPlantedThisRun() && goal.isProtectionNeeded() && !goal.isPaid())
				{
					return new Advice(Action.PAY, "Pay " + gardener + ": " + goal.getPaymentText());
				}
				return new Advice(Action.DONE, "Done");
			case CHECK_HEALTH:
				return new Advice(Action.CHECK_HEALTH, "Check the health of the " + (live.getCrop() != null
					? what + " tree" : patch.getType().getDisplayName().toLowerCase()) + " (replanting: "
					+ goal.getPlantName() + ")");
			case HARVESTABLE:
				if (patch.getType() == PatchType.HERB)
				{
					return new Advice(Action.PICK, "Pick the " + what);
				}
				if (patch.getType() == PatchType.FRUIT_TREE && live.getStage() > 0)
				{
					return new Advice(Action.PICK, "Pick the " + what + " fruit (" + live.getStage() + " left)");
				}
				return clearTree(goal, gardener);
			case STUMP:
				return goal.isPayToClear()
					? new Advice(Action.PAY_TO_CLEAR, "Ask " + gardener + " to remove the stump (200 coins)")
					: new Advice(Action.DIG_STUMP, "Dig up the stump with your spade");
			case DEAD:
				return new Advice(Action.CLEAR_DEAD, "Clear the dead " + what + (tree ? " tree" : "") + " (spade)");
			case DISEASED:
				return tree
					? new Advice(Action.PRUNE, "Prune the diseased " + what + " tree with secateurs")
					: new Advice(Action.CURE, "Cure the diseased " + what + " with plant cure, or clear it");
			case WEEDS:
				return new Advice(Action.RAKE, "Rake the patch");
			case EMPTY:
				if (wantsCompost(goal))
				{
					return compost(goal);
				}
				return new Advice(Action.PLANT, "Plant: " + goal.getPlantName());
			default:
				return new Advice(Action.INSPECT, "Inspect the patch");
		}
	}

	/**
	 * A short plan for a patch, for hovering a route stop, e.g. "Herb: harvest guam and plant ranarr" or
	 * "Fruit tree: check health of papaya, clear and plant papaya".
	 *
	 * @param live what's in the patch now, or null if unknown
	 * @param plant what to plant, or null if not decided
	 */
	public static String objectives(Patch patch, PatchPrediction live, Crop plant)
	{
		final List<String> steps = new ArrayList<>();
		final boolean tree = patch.getType() == PatchType.TREE || patch.getType() == PatchType.FRUIT_TREE;
		boolean replant = true;
		if (live == null)
		{
			steps.add("check the patch");
		}
		else
		{
			final String what = live.getCrop() != null ? live.getCrop().getDisplayName().toLowerCase() : "the crop";
			switch (live.getState())
			{
				case GROWING:
					steps.add(what + " still growing");
					replant = false;
					break;
				case CHECK_HEALTH:
					steps.add("check health of " + what);
					if (tree)
					{
						steps.add("clear");
					}
					break;
				case HARVESTABLE:
					if (patch.getType() == PatchType.FRUIT_TREE)
					{
						steps.add((live.getStage() > 0 ? "pick " : "") + what);
						steps.add("clear");
					}
					else
					{
						steps.add((tree ? "clear " : "harvest ") + what);
					}
					break;
				case STUMP:
					steps.add("clear the stump");
					break;
				case DEAD:
					steps.add("clear dead " + what);
					break;
				case DISEASED:
					steps.add((tree ? "prune " : "cure or clear ") + what);
					break;
				case WEEDS:
					steps.add("rake");
					break;
				default:
					break;
			}
		}
		if (replant)
		{
			steps.add("plant " + (plant != null ? plant.getDisplayName().toLowerCase() : "a seed"));
		}
		String text = steps.get(0);
		for (int i = 1; i < steps.size(); i++)
		{
			text += (i == steps.size() - 1 ? " and " : ", ") + steps.get(i);
		}
		return patch.getType().getDisplayName() + ": " + text;
	}

	private static boolean wantsCompost(PatchGoal goal)
	{
		return goal.getCompost() != null && goal.getCompost() != Compost.NONE && !goal.isComposted();
	}

	private static Advice compost(PatchGoal goal)
	{
		return new Advice(Action.COMPOST, "Use " + goal.getCompost().getDisplayName().toLowerCase() + " on the patch");
	}

	private static Advice clearTree(PatchGoal goal, String gardener)
	{
		return goal.isPayToClear()
			? new Advice(Action.PAY_TO_CLEAR, "Ask " + gardener + " to remove the tree (200 coins)")
			: new Advice(Action.CHOP, "Chop down the tree");
	}
}

package com.farmrunautopilot.settings;

import com.farmrunautopilot.data.Unlock;
import com.farmrunautopilot.data.travel.TravelItem;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import lombok.Data;

/**
 * Facts about the account that can't be detected automatically. Kept apart from {@link RunConfig} so
 * presets don't carry them.
 */
@Data
public class AccountSettings
{
	/** Unlocks the player ticked in Setup. Only used for unlocks with no automatic detection. */
	private Set<Unlock> manualUnlocks = EnumSet.noneOf(Unlock.class);
	/** The player has checked the unlocks the plugin can't read, so the Run tab stops asking. */
	private boolean unlocksReviewed;
	private PohSetup poh = new PohSetup();
	/** Beta: detect house furniture on entering the house. Off until the player ticks it. */
	private boolean autoDetectHouse;
	/** Uses left in the bottomless compost bucket, from its game messages; null until seen. */
	private Integer bottomlessUses;
	/** What the bottomless compost bucket holds, from its game messages; null until seen. */
	private Compost bottomlessCompost;
	/** Charges of self-charged teleport items (quetzal whistle, Xeric's talisman, pendant of Ates), from chat. */
	private Map<TravelItem, Integer> itemCharges = new EnumMap<>(TravelItem.class);

	public AccountSettings sanitise()
	{
		manualUnlocks = RunConfig.cleanSet(manualUnlocks, Unlock.class, EnumSet.noneOf(Unlock.class));
		itemCharges = RunConfig.cleanMap(itemCharges, TravelItem.class);
		if (poh == null)
		{
			poh = new PohSetup();
		}
		poh.sanitise();
		return this;
	}
}

package com.farmrunautopilot.settings;

import com.farmrunautopilot.data.DataConstants;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.gameval.ItemID;

@Getter
@RequiredArgsConstructor
public enum Compost
{
	NONE("No compost", DataConstants.NONE),
	COMPOST("Compost", ItemID.BUCKET_COMPOST),
	SUPERCOMPOST("Supercompost", ItemID.BUCKET_SUPERCOMPOST),
	ULTRACOMPOST("Ultracompost", ItemID.BUCKET_ULTRACOMPOST);

	private final String displayName;
	private final int itemId;

	@Override
	public String toString()
	{
		return displayName;
	}

	/** From game text such as "ultracompost", or null. */
	public static Compost fromName(String name)
	{
		for (Compost compost : values())
		{
			if (compost != NONE && compost.displayName.equalsIgnoreCase(name))
			{
				return compost;
			}
		}
		return null;
	}

	/** The tool leprechaun's bottomless bucket type value for an empty bucket (the game's farming_tools_getstored script). */
	public static final int EMPTY_BUCKET_TYPE = 1;

	/**
	 * The compost in a bucket stored at the tool leprechaun, from its type value, or null (empty, or unknown). The
	 * game's farming_tools_getstored script says 1 is an empty bucket and anything higher a filled one. UNVERIFIED
	 * which filled value is which compost: assumed 2 compost, 3 super, 4 ultra (guided test BUCKET_COMPOST).
	 */
	public static Compost fromBucketType(int type)
	{
		switch (type)
		{
			case 2:
				return COMPOST;
			case 3:
				return SUPERCOMPOST;
			case 4:
				return ULTRACOMPOST;
			default:
				return null;
		}
	}
}

