}

package com.farmrunautopilot.supply;

import com.farmrunautopilot.settings.AccountSettings;
import com.farmrunautopilot.settings.Compost;
import com.farmrunautopilot.settings.SettingsStore;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

/**
 * Keeps the uses left in the bottomless compost bucket (GitHub #3). The game only shows them in chat (Check,
 * filling) and, for a bucket stored at the tool leprechaun, in its varbits; each patch treated uses one. Saved
 * per account so they survive logging out. Message wording is from the wiki's bucket transcript.
 *
 * <p>Client thread, except that settings are written on the Swing thread.
 */
@Slf4j
@Singleton
public class BottomlessBucketTracker
{
	private static final String TYPES = "(ultracompost|supercompost|compost)";
	static final Pattern CHECK = Pattern.compile(
		"Your bottomless compost bucket is currently holding ([\\d,]+) uses? of " + TYPES + "\\.");
	static final Pattern EMPTY = Pattern.compile("Your (?:bottomless )?compost bucket is currently empty\\.");
	static final Pattern FILL_TYPE = Pattern.compile(
		"You fill your bottomless compost bucket with (?:a single bucket|[\\d,]+ buckets) of " + TYPES + "\\.");
	static final Pattern FILL_TOTAL = Pattern.compile(
		"Your bottomless compost bucket now contains a total of ([\\d,]+) uses\\.");
	/** As in RuneLite core CompostTracker (BSD-2). */
	static final Pattern TREATED = Pattern.compile("You treat the .+ with (ultra|super|)compost\\.");

	private final Client client;
	private final SettingsStore settings;

	/** Uses left, or -1 if not known. */
	private volatile int uses = -1;
	/**
	 * What the player last used on an object: true for the bottomless bucket, false for something else, null
	 * if not seen. Decides whose compost the next "You treat..." message was.
	 */
	private Boolean lastUseWasBucket;
	/** What it holds, or null if not known. */
	private volatile Compost compost;

	@Inject
	BottomlessBucketTracker(Client client, SettingsStore settings)
	{
		this.client = client;
		this.settings = settings;
	}

	/** Read the saved values for the current account. Call after settings load. */
	public void reload()
	{
		final AccountSettings account = settings.getAccount();
		uses = account.getBottomlessUses() != null ? account.getBottomlessUses() : -1;
		compost = account.getBottomlessCompost();
	}

	public int getUses()
	{
		return uses;
	}

	public Compost getCompost()
	{
		return compost;
	}

	/**
	 * @return whether the uses or type changed
	 */
	public boolean onChatMessage(String message)
	{
		Matcher m = CHECK.matcher(message);
		if (m.matches())
		{
			return record(number(m.group(1)), Compost.fromName(m.group(2)));
		}
		if (EMPTY.matcher(message).matches())
		{
			return record(0, null);
		}
		m = FILL_TYPE.matcher(message);
		if (m.matches())
		{
			return record(uses, Compost.fromName(m.group(1)));
		}
		m = FILL_TOTAL.matcher(message);
		if (m.matches())
		{
			return record(number(m.group(1)), compost);
		}
		m = TREATED.matcher(message);
		if (m.matches())
		{
			final Boolean clicked = lastUseWasBucket;
			lastUseWasBucket = null;
			final boolean bucketUsed = clicked != null ? clicked : usedTheBucket(Compost.fromName(m.group(1) + "compost"));
			if (bucketUsed && uses > 0)
			{
				return record(uses - 1, compost);
			}
		}
		return false;
	}

	/** Remember which item was used on an object, so the compost message can be put down to the right one. */
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (event.getMenuAction() != MenuAction.WIDGET_TARGET_ON_GAME_OBJECT)
		{
			return;
		}
		final Widget selected = client.getSelectedWidget();
		lastUseWasBucket = selected != null && selected.getItemId() == ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED;
	}

	/**
	 * The bucket turned into the empty one (used up or emptied): no uses left.
	 *
	 * @return whether the uses changed
	 */
	public boolean onInventoryChanged(ItemContainer inventory)
	{
		if (uses != 0 && inventory.contains(ItemID.BOTTOMLESS_COMPOST_BUCKET)
			&& !inventory.contains(ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED))
		{
			return record(0, null);
		}
		return false;
	}

	/**
	 * A bucket stored at the tool leprechaun shows its uses in varbits; keep them for when it's taken out.
	 *
	 * @return whether the uses or type changed
	 */
	public boolean onVarbitChanged(int varbitId)
	{
		if (varbitId != VarbitID.FARMING_TOOLS_BOTTOMLESS_BUCKET_TYPE
			&& varbitId != VarbitID.FARMING_TOOLS_BOTTOMLESS_BUCKET_QUANTITY)
		{
			return false;
		}
		final int type = client.getVarbitValue(VarbitID.FARMING_TOOLS_BOTTOMLESS_BUCKET_TYPE);
		final int quantity = client.getVarbitValue(VarbitID.FARMING_TOOLS_BOTTOMLESS_BUCKET_QUANTITY);
		if (type <= Compost.EMPTY_BUCKET_TYPE || quantity <= 0)
		{
			// Taken out, never stored, or stored empty: the bucket keeps what it had
			return false;
		}
		final Compost stored = Compost.fromBucketType(type);
		return record(quantity, stored != null ? stored : compost);
	}

	/**
	 * Treated with the bucket rather than an ordinary bucket of compost: a filled bucket is carried and no
	 * ordinary bucket of that compost is. A guess when both are carried; the next Check corrects it.
	 */
	private boolean usedTheBucket(Compost used)
	{
		final ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null || !inventory.contains(ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED))
		{
			return false;
		}
		return used == null || !inventory.contains(used.getItemId());
	}

	private boolean record(int newUses, Compost newCompost)
	{
		if (newUses == uses && newCompost == compost)
		{
			return false;
		}
		uses = newUses;
		compost = newCompost;
		log.debug("Bottomless compost bucket: {} uses of {}", newUses, newCompost);
		final Integer savedUses = newUses >= 0 ? newUses : null;
		SwingUtilities.invokeLater(() ->
		{
			settings.editAccount().setBottomlessUses(savedUses);
			settings.editAccount().setBottomlessCompost(newCompost);
			settings.saveAccount(false);
		});
		return true;
	}

	static int number(String text)
	{
		return Integer.parseInt(text.replace(",", ""));
	}
}

package com.farmrunautopilot.supply;

import com.farmrunautopilot.data.Crop;
import com.farmrunautopilot.data.Patch;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Predicate;
import java.util.function.ToIntFunction;

/**
 * Decides which crop goes in which patch of one run type.
 *
 * <p>Safe patches (disease-free or protected) are filled first. They take reserved crops first (e.g. the
 * player's valuable herbs for disease-free patches), then the normal choices. Other patches never get
 * reserved crops. Each patch gets the best crop still in stock; if everything has run out it gets its
 * first allowed choice, and that crop shows as short.
 */
public final class CropAllocator
{
	private CropAllocator()
	{
	}

	/**
	 * @param patches the patches of one run type in this run
	 * @param choices crops in order of preference (1st choice first)
	 * @param held how many of a crop's seed or sapling the player holds
	 * @param safe whether a patch is disease-free or protected
	 * @param reservedForSafe crops only for safe patches, best first; may be empty
	 * @return crop per patch, in the order patches were given
	 */
	public static Map<Patch, Crop> allocate(List<Patch> patches, List<Crop> choices, ToIntFunction<Crop> held,
		Predicate<Patch> safe, List<Crop> reservedForSafe)
	{
		final List<Patch> order = new ArrayList<>();
		for (Patch patch : patches)
		{
			if (safe.test(patch))
			{
				order.add(patch);
			}
		}
		for (Patch patch : patches)
		{
			if (!safe.test(patch))
			{
				order.add(patch);
			}
		}

		final Map<Crop, Integer> stock = new HashMap<>();
		for (Crop crop : choices)
		{
			stock.put(crop, held.applyAsInt(crop));
		}
		for (Crop crop : reservedForSafe)
		{
			stock.put(crop, held.applyAsInt(crop));
		}

		// Normal choices for patches that aren't safe: never a reserved crop, unless every choice is reserved.
		final List<Crop> unsafeChoices = new ArrayList<>();
		for (Crop crop : choices)
		{
			if (!reservedForSafe.contains(crop))
			{
				unsafeChoices.add(crop);
			}
		}
		if (unsafeChoices.isEmpty())
		{
			unsafeChoices.add(choices.get(0));
		}

		final Map<Patch, Crop> byPatch = new HashMap<>();
		for (Patch patch : order)
		{
			final List<Crop> candidates = new ArrayList<>();
			if (safe.test(patch))
			{
				candidates.addAll(reservedForSafe);
				candidates.addAll(choices);
			}
			else
			{
				candidates.addAll(unsafeChoices);
			}

			Crop pick = null;
			for (Crop crop : candidates)
			{
				if (stock.get(crop) > 0)
				{
					pick = crop;
					break;
				}
			}
			if (pick == null)
			{
				// Everything is out: use the first normal choice this patch may have.
				pick = safe.test(patch) ? choices.get(0) : unsafeChoices.get(0);
			}
			stock.merge(pick, -1, Integer::sum);
			byPatch.put(patch, pick);
		}

		final Map<Patch, Crop> result = new LinkedHashMap<>();
		for (Patch patch : patches)
		{
			result.put(patch, byPatch.get(patch));
		}
		return result;
	}
}

package com.farmrunautopilot.supply;

import com.farmrunautopilot.data.travel.Rune;
import com.farmrunautopilot.data.travel.TravelItem;
import com.farmrunautopilot.data.travel.TravelMethod;
import com.farmrunautopilot.settings.Compost;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import lombok.Value;

/**
 * Everything the player has, by where it is (SPEC 11). Item IDs are canonical: noted items are counted
 * as their unnoted item. Immutable; built on the client thread, read anywhere.
 */
@Value
public class Holdings
{
	public enum Source
	{
		INVENTORY("inventory"),
		WORN("worn"),
		BANK("bank"),
		LEPRECHAUN("leprechaun"),
		GROUP_STORAGE("group storage"),
		SEED_VAULT("seed vault (Farming Guild)");

		private final String label;

		Source(String label)
		{
			this.label = label;
		}

		public String getLabel()
		{
			return label;
		}
	}

	public static final Holdings EMPTY = new Holdings(Collections.emptyMap(), Collections.emptyMap(),
		Collections.emptySet(), false, false);

	/** Item counts per source. Sources that are switched off or never seen are absent. */
	Map<Source, Map<Integer, Integer>> items;
	/** Rune pouch contents by rune item (combination runes included), only when a pouch is in the inventory. */
	Map<Integer, Integer> runePouch;
	/** Runes supplied without limit by an equipped staff or tome. */
	Set<Rune> infiniteRunes;
	/** The bank has been opened at least once on this account, so its contents are known. */
	boolean bankKnown;
	/** Tithe Farm Auto-weed is owned and switched on. */
	boolean autoweedOn;
	/** Uses left in the bottomless compost bucket, or -1 if not known. */
	int bucketUses;
	/** What the bottomless compost bucket holds, or null if not known. */
	Compost bucketCompost;
	/** Today's uses of teleports limited per day (Ardougne cloak, Explorer's ring). */
	Map<TravelMethod, Integer> usedToday;
	/** Known charges of self-charged items (quetzal whistle, Xeric's talisman, pendant of Ates). */
	Map<TravelItem, Integer> itemCharges;

	public Holdings(Map<Source, Map<Integer, Integer>> items, Map<Integer, Integer> runePouch, Set<Rune> infiniteRunes,
		boolean bankKnown, boolean autoweedOn, int bucketUses, Compost bucketCompost,
		Map<TravelMethod, Integer> usedToday, Map<TravelItem, Integer> itemCharges)
	{
		this.items = items;
		this.runePouch = runePouch;
		this.infiniteRunes = infiniteRunes;
		this.bankKnown = bankKnown;
		this.autoweedOn = autoweedOn;
		this.bucketUses = bucketUses;
		this.bucketCompost = bucketCompost;
		this.usedToday = usedToday;
		this.itemCharges = itemCharges;
	}

	public Holdings(Map<Source, Map<Integer, Integer>> items, Map<Integer, Integer> runePouch, Set<Rune> infiniteRunes,
		boolean bankKnown, boolean autoweedOn, int bucketUses, Compost bucketCompost,
		Map<TravelMethod, Integer> usedToday)
	{
		this(items, runePouch, infiniteRunes, bankKnown, autoweedOn, bucketUses, bucketCompost, usedToday,
			Collections.emptyMap());
	}

	public Holdings(Map<Source, Map<Integer, Integer>> items, Map<Integer, Integer> runePouch, Set<Rune> infiniteRunes,
		boolean bankKnown, boolean autoweedOn, int bucketUses, Compost bucketCompost)
	{
		this(items, runePouch, infiniteRunes, bankKnown, autoweedOn, bucketUses, bucketCompost,
			Collections.emptyMap());
	}

	/** Without anything known about a bottomless compost bucket. */
	public Holdings(Map<Source, Map<Integer, Integer>> items, Map<Integer, Integer> runePouch, Set<Rune> infiniteRunes,
		boolean bankKnown, boolean autoweedOn)
	{
		this(items, runePouch, infiniteRunes, bankKnown, autoweedOn, -1, null);
	}

	public int count(int itemId)
	{
		int total = runePouch.getOrDefault(itemId, 0);
		for (Map<Integer, Integer> source : items.values())
		{
			total += source.getOrDefault(itemId, 0);
		}
		return total;
	}

	/** Total held of any of these items. */
	public int countAny(int[] itemIds)
	{
		int total = 0;
		for (int id : itemIds)
		{
			total += count(id);
		}
		return total;
	}

	/** Where these items are, e.g. {BANK=12, INVENTORY=3}. Rune pouch contents count as inventory. */
	public Map<Source, Integer> where(int... itemIds)
	{
		final Map<Source, Integer> where = new EnumMap<>(Source.class);
		int pouch = 0;
		for (int id : itemIds)
		{
			pouch += runePouch.getOrDefault(id, 0);
		}
		items.forEach((source, counts) ->
		{
			int n = 0;
			for (int id : itemIds)
			{
				n += counts.getOrDefault(id, 0);
			}
			if (n > 0)
			{
				where.put(source, n);
			}
		});
		if (pouch > 0)
		{
			where.merge(Source.INVENTORY, pouch, Integer::sum);
		}
		return where;
	}

	/** Only what the player is carrying: inventory (with rune pouch) and worn items. */
	public Holdings carriedOnly()
	{
		final Map<Source, Map<Integer, Integer>> carried = new EnumMap<>(Source.class);
		carried.put(Source.INVENTORY, in(Source.INVENTORY));
		carried.put(Source.WORN, in(Source.WORN));
		return new Holdings(carried, runePouch, infiniteRunes, bankKnown, autoweedOn, bucketUses, bucketCompost,
			usedToday,
			itemCharges);
	}

	public Map<Integer, Integer> in(Source source)
	{
		return items.getOrDefault(source, Collections.emptyMap());
	}

	/**
	 * What's left after using up {@code amount} of these items (any of them, in order), taken from what's carried
	 * first, then the rune pouch, then the bank and other storage. For planning later parts of a run.
	 */
	public Holdings use(int[] itemIds, int amount)
	{
		final Map<Source, Map<Integer, Integer>> left = new EnumMap<>(Source.class);
		items.forEach((source, counts) -> left.put(source, new HashMap<>(counts)));
		final Map<Integer, Integer> pouch = new HashMap<>(runePouch);
		int remaining = amount;
		for (Source source : Source.values())
		{
			remaining = take(left.get(source), itemIds, remaining);
			if (source == Source.WORN)
			{
				remaining = take(pouch, itemIds, remaining);
			}
		}
		return new Holdings(left, pouch, infiniteRunes, bankKnown, autoweedOn, bucketUses, bucketCompost, usedToday,
			itemCharges);
	}

	/** Takes up to {@code amount} of these items from {@code counts}; returns how many are still to take. */
	private static int take(Map<Integer, Integer> counts, int[] itemIds, int amount)
	{
		if (counts == null)
		{
			return amount;
		}
		for (int id : itemIds)
		{
			if (amount <= 0)
			{
				break;
			}
			final int have = counts.getOrDefault(id, 0);
			final int used = Math.min(have, amount);
			if (used > 0)
			{
				counts.put(id, have - used);
				amount -= used;
			}
		}
		return amount;
	}
}

package com.farmrunautopilot.supply;

import com.farmrunautopilot.FarmRunAutopilotConfig;
import com.farmrunautopilot.data.DataConstants;
import com.farmrunautopilot.data.SupplyItems;
import com.farmrunautopilot.data.travel.Rune;
import com.farmrunautopilot.data.travel.DailyLimits;
import com.farmrunautopilot.data.travel.TravelMethod;
import com.farmrunautopilot.settings.RunConfig;
import com.farmrunautopilot.settings.SettingsStore;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.farmrunautopilot.settings.Compost;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;

/**
 * Keeps {@link Holdings} up to date (SPEC 11, 14). Inventory, equipment, rune pouch and leprechaun are
 * read live; the bank, group storage and seed vault are cached per account when their windows open,
 * because the game only sends them then. All methods except {@link #getHoldings()} run on the client
 * thread.
 */
@Slf4j
@Singleton
public class HoldingsTracker
{
	private static final String BANK_KEY = "cache.bank";
	private static final String GROUP_STORAGE_KEY = "cache.groupStorage";
	private static final String SEED_VAULT_KEY = "cache.seedVault";
	/** FARMING_BLOCKWEEDS value when Auto-weed is owned and switched on. */
	private static final int AUTOWEED_ON = 2;

	private static final int[] POUCH_TYPE_VARBITS = {
		VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3,
		VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_TYPE_6
	};
	private static final int[] POUCH_AMOUNT_VARBITS = {
		VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2, VarbitID.RUNE_POUCH_QUANTITY_3,
		VarbitID.RUNE_POUCH_QUANTITY_4, VarbitID.RUNE_POUCH_QUANTITY_5, VarbitID.RUNE_POUCH_QUANTITY_6
	};

	/** Varbits whose changes affect holdings. */
	private static final Set<Integer> WATCHED_VARBITS = new HashSet<>();

	static
	{
		for (int varbit : POUCH_TYPE_VARBITS)
		{
			WATCHED_VARBITS.add(varbit);
		}
		for (int varbit : POUCH_AMOUNT_VARBITS)
		{
			WATCHED_VARBITS.add(varbit);
		}
		for (LeprechaunItem item : LeprechaunItem.values())
		{
			WATCHED_VARBITS.add(item.getBaseVarbit());
			if (item.getExtraVarbit() != DataConstants.NONE)
			{
				WATCHED_VARBITS.add(item.getExtraVarbit());
			}
		}
		WATCHED_VARBITS.add(VarbitID.FARMING_BLOCKWEEDS);
		WATCHED_VARBITS.add(VarbitID.FARMING_TOOLS_BOTTOMLESS_BUCKET_TYPE);
		WATCHED_VARBITS.add(VarbitID.FARMING_TOOLS_BOTTOMLESS_BUCKET_QUANTITY);
		WATCHED_VARBITS.addAll(DailyLimits.usedTodayVarbits().values());
	}

	private final Client client;
	private final ConfigManager configManager;
	private final Gson gson;
	private final ItemManager itemManager;
	private final SettingsStore settings;
	private final BottomlessBucketTracker bucket;
	private final ItemChargeTracker itemCharges;

	private Map<Integer, Integer> bank;
	private Map<Integer, Integer> groupStorage;
	private Map<Integer, Integer> seedVault;
	private boolean dirty = true;
	private volatile Holdings holdings = Holdings.EMPTY;

	@Inject
	HoldingsTracker(Client client, ConfigManager configManager, Gson gson, ItemManager itemManager,
		SettingsStore settings, BottomlessBucketTracker bucket, ItemChargeTracker itemCharges)
	{
		this.client = client;
		this.configManager = configManager;
		this.gson = gson;
		this.itemManager = itemManager;
		this.settings = settings;
		this.bucket = bucket;
		this.itemCharges = itemCharges;
	}

	public Holdings getHoldings()
	{
		return holdings;
	}

	/** The seed vault has been opened on this account, so its contents are known. */
	public boolean hasSeenSeedVault()
	{
		return seedVault != null;
	}

	/** Reload the cached containers for the current account (startup, account switch). */
	public void loadCaches()
	{
		bank = readCache(BANK_KEY);
		groupStorage = readCache(GROUP_STORAGE_KEY);
		seedVault = readCache(SEED_VAULT_KEY);
		dirty = true;
	}

	public void markDirty()
	{
		dirty = true;
	}

	public void onItemContainerChanged(int containerId, ItemContainer container)
	{
		switch (containerId)
		{
			case InventoryID.INV:
			case InventoryID.WORN:
				dirty = true;
				break;
			case InventoryID.BANK:
				bank = writeCache(BANK_KEY, container);
				dirty = true;
				break;
			case InventoryID.SEED_VAULT:
				seedVault = writeCache(SEED_VAULT_KEY, container);
				dirty = true;
				break;
			case InventoryID.INV_GROUP_TEMP:
				// Only save group storage once the player's edits are committed (as Quest Helper does).
				if (settings.getRunConfig().isUseGroupStorage()
					&& client.getVarbitValue(VarbitID.GIM_SHARED_BANK_HASEDITED) == 0)
				{
					groupStorage = writeCache(GROUP_STORAGE_KEY, container);
					dirty = true;
				}
				break;
			default:
				break;
		}
	}

	public void onVarbitChanged(int varbitId)
	{
		if (WATCHED_VARBITS.contains(varbitId))
		{
			dirty = true;
		}
	}

	/**
	 * Rebuilds the holdings if anything changed. Call once per game tick.
	 *
	 * @return whether the holdings changed
	 */
	public boolean rebuildIfDirty()
	{
		if (!dirty)
		{
			return false;
		}
		dirty = false;

		final RunConfig config = settings.getRunConfig();
		final Map<Holdings.Source, Map<Integer, Integer>> items = new EnumMap<>(Holdings.Source.class);
		final Map<Integer, Integer> inventory = read(client.getItemContainer(InventoryID.INV));
		final Map<Integer, Integer> worn = read(client.getItemContainer(InventoryID.WORN));
		items.put(Holdings.Source.INVENTORY, inventory);
		items.put(Holdings.Source.WORN, worn);
		if (bank != null)
		{
			items.put(Holdings.Source.BANK, bank);
		}
		items.put(Holdings.Source.LEPRECHAUN, readLeprechaun());
		if (config.isUseGroupStorage() && groupStorage != null)
		{
			items.put(Holdings.Source.GROUP_STORAGE, groupStorage);
		}
		if (config.isUseSeedVault() && seedVault != null)
		{
			items.put(Holdings.Source.SEED_VAULT, seedVault);
		}

		final Set<Rune> infinite = EnumSet.noneOf(Rune.class);
		for (Integer id : worn.keySet())
		{
			final Set<Rune> runes = SupplyItems.INFINITE_RUNE_ITEMS.get(id);
			if (runes != null)
			{
				infinite.addAll(runes);
			}
		}

		final Holdings next = new Holdings(Collections.unmodifiableMap(items), readRunePouch(inventory),
			Collections.unmodifiableSet(infinite), bank != null,
			client.getVarbitValue(VarbitID.FARMING_BLOCKWEEDS) == AUTOWEED_ON,
			bucket.getUses(), bucket.getCompost(), readUsedToday(), itemCharges.getCharges());
		if (next.equals(holdings))
		{
			return false;
		}
		holdings = next;
		return true;
	}

	private Map<Integer, Integer> read(ItemContainer container)
	{
		final Map<Integer, Integer> counts = new HashMap<>();
		if (container == null)
		{
			return counts;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() >= 0 && item.getQuantity() > 0)
			{
				// Noted items and placeholders count as the real item.
				counts.merge(itemManager.canonicalize(item.getId()), item.getQuantity(), Integer::sum);
			}
		}
		return counts;
	}

	private Map<Integer, Integer> readRunePouch(Map<Integer, Integer> inventory)
	{
		boolean hasPouch = false;
		for (int pouch : SupplyItems.RUNE_POUCHES)
		{
			hasPouch |= inventory.containsKey(pouch);
		}
		if (!hasPouch)
		{
			return Collections.emptyMap();
		}

		final EnumComposition runeEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		final Map<Integer, Integer> runes = new HashMap<>();
		for (int i = 0; i < POUCH_TYPE_VARBITS.length; i++)
		{
			final int type = client.getVarbitValue(POUCH_TYPE_VARBITS[i]);
			final int amount = client.getVarbitValue(POUCH_AMOUNT_VARBITS[i]);
			if (type != 0 && amount > 0)
			{
				runes.merge(runeEnum.getIntValue(type), amount, Integer::sum);
			}
		}
		return Collections.unmodifiableMap(runes);
	}

	private Map<Integer, Integer> readLeprechaun()
	{
		final Map<Integer, Integer> counts = new HashMap<>();
		for (LeprechaunItem item : LeprechaunItem.values())
		{
			if (item == LeprechaunItem.MAGIC_SECATEURS)
			{
				continue;
			}
			final int base = client.getVarbitValue(item.getBaseVarbit());
			final int extra = item.getExtraVarbit() == DataConstants.NONE ? 0 : client.getVarbitValue(item.getExtraVarbit());
			final int total = item.total(base, extra);
			if (total > 0)
			{
				counts.put(item.getItemId(), total);
			}
		}
		// A bottomless compost bucket stored here: type 1 is an empty one, higher a filled one (the game's
		// farming_tools_getstored script)
		final int bucketType = client.getVarbitValue(VarbitID.FARMING_TOOLS_BOTTOMLESS_BUCKET_TYPE);
		if (bucketType == Compost.EMPTY_BUCKET_TYPE)
		{
			counts.put(ItemID.BOTTOMLESS_COMPOST_BUCKET, 1);
		}
		else if (bucketType > Compost.EMPTY_BUCKET_TYPE)
		{
			counts.put(ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED, 1);
		}
		// The secateurs slot holds magic secateurs when this flag is set.
		if (client.getVarbitValue(LeprechaunItem.MAGIC_SECATEURS.getBaseVarbit()) > 0)
		{
			final Integer secateurs = counts.remove(LeprechaunItem.SECATEURS.getItemId());
			if (secateurs != null)
			{
				counts.put(LeprechaunItem.MAGIC_SECATEURS.getItemId(), secateurs);
			}
		}
		return counts;
	}

	/** Today's uses of each teleport limited per day. */
	private Map<TravelMethod, Integer> readUsedToday()
	{
		final Map<TravelMethod, Integer> used = new EnumMap<>(TravelMethod.class);
		DailyLimits.usedTodayVarbits().forEach((method, varbit) -> used.put(method, client.getVarbitValue(varbit)));
		return Collections.unmodifiableMap(used);
	}


	private Map<Integer, Integer> writeCache(String key, ItemContainer container)
	{
		final Map<Integer, Integer> counts = Collections.unmodifiableMap(read(container));
		final int[] pairs = new int[counts.size() * 2];
		int i = 0;
		for (Map.Entry<Integer, Integer> e : counts.entrySet())
		{
			pairs[i++] = e.getKey();
			pairs[i++] = e.getValue();
		}
		configManager.setRSProfileConfiguration(FarmRunAutopilotConfig.GROUP, key, gson.toJson(pairs));
		return counts;
	}

	private Map<Integer, Integer> readCache(String key)
	{
		final String json = configManager.getRSProfileConfiguration(FarmRunAutopilotConfig.GROUP, key);
		if (json == null)
		{
			return null;
		}
		try
		{
			final int[] pairs = gson.fromJson(json, int[].class);
			final Map<Integer, Integer> counts = new HashMap<>();
			for (int i = 0; pairs != null && i + 1 < pairs.length; i += 2)
			{
				counts.put(pairs[i], pairs[i + 1]);
			}
			return Collections.unmodifiableMap(counts);
		}
		catch (JsonParseException e)
		{
			log.warn("Couldn't read cached {}", key, e);
			return null;
		}
	}
}

package com.farmrunautopilot.supply;

import com.farmrunautopilot.data.travel.TravelItem;
import com.farmrunautopilot.settings.SettingsStore;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.util.Text;

/**
 * Charges of teleport items the player charges themselves, which the game only shows in chat: the quetzal
 * whistle, Xeric's talisman and the pendant of Ates. Set from their Check and charging messages (wiki
 * transcripts) and the whistle's own "...charges remaining" after each flight. Xeric's talisman, which may
 * not say, is counted down by one when a teleport click is followed by the player being moved (picking a
 * destination can take a while; a cancelled teleport or a closed menu uses nothing). A count from the game wins,
 * so a use is never counted twice. Saved per account. Kharedst's memoirs / Book of the dead have no known
 * messages, so aren't tracked.
 *
 * <p>Client thread, except that settings are written on the Swing thread.
 */
@Slf4j
@Singleton
public class ItemChargeTracker
{
	/** Items whose charges are kept here. */
	public static final Set<TravelItem> TRACKED = Collections.unmodifiableSet(EnumSet.of(
		TravelItem.QUETZAL_WHISTLE, TravelItem.XERICS_TALISMAN, TravelItem.PENDANT_OF_ATES));
	private static final String COUNT = "(no|one|[\\d,]+)";
	/** Confirmed in game. */
	public static final Pattern WHISTLE_CHECK = Pattern.compile("Your quetzal whistle has " + COUNT + " charges? remaining\\.");
	public static final Pattern TALISMAN_CHECK = Pattern.compile("The talisman has " + COUNT + " charges?\\.");
	static final Pattern TALISMAN_CHARGED = Pattern.compile("Your talisman now has ([\\d,]+) charges?\\.");
	public static final Pattern PENDANT_CHECK = Pattern.compile("The pendant has " + COUNT + " charges?\\.");
	static final Pattern PENDANT_CHARGED = Pattern.compile(".*It now has ([\\d,]+) charges?\\.");
	private static final int FULL = 1000;
	/** A teleport click counts only if the player is moved within this many ticks (about 30 seconds). */
	private static final int PENDING_TICKS = 50;
	/** Moving further than this in one tick can only be a teleport. */
	private static final int TELEPORT_TILES = 30;
	/** Menu options on these items that aren't a teleport. */
	private static final Set<String> NOT_TELEPORTS = new HashSet<>(Arrays.asList("Check", "Wear", "Wield", "Remove",
		"Drop", "Examine", "Use", "Destroy", "Uncharge", "Charge", "Cancel"));

	private final SettingsStore settings;
	private volatile Map<TravelItem, Integer> charges = Collections.emptyMap();
	/** The item a teleport was just chosen from, waiting for the player to be moved; null if none. */
	private TravelItem pending;
	private int pendingTicks;
	private WorldPoint lastLocation;

	@Inject
	ItemChargeTracker(SettingsStore settings)
	{
		this.settings = settings;
	}

	/** Read the saved charges for the current account. Call after settings load. */
	public void reload()
	{
		charges = Collections.unmodifiableMap(new EnumMap<>(withDefaults(settings.getAccount().getItemCharges())));
	}

	private static Map<TravelItem, Integer> withDefaults(Map<TravelItem, Integer> saved)
	{
		final Map<TravelItem, Integer> map = new EnumMap<>(TravelItem.class);
		if (saved != null)
		{
			map.putAll(saved);
		}
		return map;
	}

	/** Known charges per item; items not here haven't been checked yet. */
	public Map<TravelItem, Integer> getCharges()
	{
		return charges;
	}

	/**
	 * @return whether a charge count changed
	 */
	public boolean onChatMessage(String message)
	{
		// Recharged by Soar Leader Pitri: the message has no count, so the old one is wrong; unknown until the next
		// Check or flight says (Sean, 2026-10-11)
		if (message.endsWith("Some whistle charges for you!"))
		{
			return forget(TravelItem.QUETZAL_WHISTLE);
		}
		if (message.equals("The talisman is full."))
		{
			return reported(TravelItem.XERICS_TALISMAN, FULL);
		}
		if (message.equals("The pendant is already fully charged."))
		{
			return reported(TravelItem.PENDANT_OF_ATES, FULL);
		}
		Matcher m = WHISTLE_CHECK.matcher(message);
		if (m.matches())
		{
			return reported(TravelItem.QUETZAL_WHISTLE, count(m.group(1)));
		}
		m = TALISMAN_CHECK.matcher(message);
		if (m.matches())
		{
			return reported(TravelItem.XERICS_TALISMAN, count(m.group(1)));
		}
		m = TALISMAN_CHARGED.matcher(message);
		if (m.matches())
		{
			return reported(TravelItem.XERICS_TALISMAN, count(m.group(1)));
		}
		m = PENDANT_CHECK.matcher(message);
		if (m.matches())
		{
			return reported(TravelItem.PENDANT_OF_ATES, count(m.group(1)));
		}
		m = PENDANT_CHARGED.matcher(message);
		if (m.matches() && message.contains("pendant"))
		{
			return reported(TravelItem.PENDANT_OF_ATES, count(m.group(1)));
		}
		return false;
	}

	/**
	 * The pendant of Ates keeps its charges in a varbit (UNVERIFIED: picked by its name), which is exact, so it
	 * replaces the chat and click counting for the pendant whenever it changes.
	 *
	 * @return whether a charge count changed
	 */
	public boolean onVarbitChanged(int varbitId, int value)
	{
		return varbitId == VarbitID.CHARGES_PENDANT_OF_ATES_QUANTITY && record(TravelItem.PENDANT_OF_ATES, value);
	}

	/**
	 * A teleport chosen from one of these items: it uses a charge once the player is moved (see
	 * {@link #onGameTick}).
	 *
	 * @return whether a charge count changed (never, now; kept for callers)
	 */
	public boolean onMenuOptionClicked(MenuOptionClicked event)
	{
		final int itemId = event.getItemId();
		final String option = Text.removeTags(event.getMenuOption());
		// Moving it in or out of the bank (Withdraw-1, Deposit-All...) isn't a teleport
		if (itemId <= 0 || NOT_TELEPORTS.contains(option) || option.startsWith("Withdraw")
			|| option.startsWith("Deposit"))
		{
			return false;
		}
		for (TravelItem item : TRACKED)
		{
			// The pendant's varbit says when a charge is really used; the whistle says so in chat after every flight
			// ("Your quetzal whistle has 19 charges remaining."). Guessing from movement as well counted a Renu flight
			// after the whistle menu was opened and closed (Sean, 2026-10-11)
			if (item == TravelItem.PENDANT_OF_ATES || item == TravelItem.QUETZAL_WHISTLE)
			{
				continue;
			}
			final Integer left = charges.get(item);
			if (left != null && left > 0 && Arrays.stream(item.getItemIds()).anyMatch(id -> id == itemId))
			{
				pending = item;
				pendingTicks = 0;
				return false;
			}
		}
		return false;
	}

	/**
	 * Each game tick: a chosen teleport uses its charge when the player is moved, and is forgotten if they aren't
	 * within about 30 seconds.
	 *
	 * @return whether a charge count changed
	 */
	public boolean onGameTick(WorldPoint location)
	{
		final WorldPoint previous = lastLocation;
		lastLocation = location;
		if (pending == null)
		{
			return false;
		}
		final boolean moved = previous != null && location != null
			&& (previous.getPlane() != location.getPlane() || previous.distanceTo2D(location) > TELEPORT_TILES);
		if (moved)
		{
			final TravelItem used = pending;
			pending = null;
			final Integer left = charges.get(used);
			return left != null && left > 0 && record(used, left - 1);
		}
		if (++pendingTicks > PENDING_TICKS)
		{
			pending = null;
		}
		return false;
	}

	public static int count(String text)
	{
		if (text.equals("no"))
		{
			return 0;
		}
		return text.equals("one") ? 1 : Integer.parseInt(text.replace(",", ""));
	}

	/** The count isn't known any more (recharged without a number). */
	private boolean forget(TravelItem item)
	{
		if (!charges.containsKey(item))
		{
			return false;
		}
		final Map<TravelItem, Integer> next = new EnumMap<>(TravelItem.class);
		next.putAll(charges);
		next.remove(item);
		charges = Collections.unmodifiableMap(next);
		log.debug("{} charges: unknown (recharged)", item);
		final Map<TravelItem, Integer> saved = new EnumMap<>(next);
		SwingUtilities.invokeLater(() ->
		{
			settings.editAccount().setItemCharges(saved);
			settings.saveAccount(false);
		});
		return true;
	}

	/** A count the game reported: exact, and any teleport waiting to be counted for this item already is. */
	private boolean reported(TravelItem item, int value)
	{
		if (pending == item)
		{
			pending = null;
		}
		return record(item, value);
	}

	private boolean record(TravelItem item, int value)
	{
		if (Integer.valueOf(value).equals(charges.get(item)))
		{
			return false;
		}
		final Map<TravelItem, Integer> next = new EnumMap<>(TravelItem.class);
		next.putAll(charges);
		next.put(item, value);
		charges = Collections.unmodifiableMap(next);
		log.debug("{} charges: {}", item, value);
		final Map<TravelItem, Integer> saved = new EnumMap<>(next);
		SwingUtilities.invokeLater(() ->
		{
			settings.editAccount().setItemCharges(saved);
			settings.saveAccount(false);
		});
		return true;
	}
}

package com.farmrunautopilot.supply;

import static com.farmrunautopilot.data.DataConstants.NONE;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

/**
 * Items the tool leprechaun stores, read from player varbits (sent everywhere, so no need to visit).
 *
 * <p>Large counts are split over a base varbit and an "extra" varbit: the total is {@code base + extra * 2^shift},
 * with the shift the game's own farming_tools_getstored script uses (1 for tools, 8 for compost and supercompost).
 */
@Getter
@RequiredArgsConstructor
public enum LeprechaunItem
{
	RAKE(ItemID.RAKE, VarbitID.FARMING_TOOLS_RAKE, VarbitID.FARMING_TOOLS_EXTRARAKES, 1),
	SEED_DIBBER(ItemID.DIBBER, VarbitID.FARMING_TOOLS_DIBBER, VarbitID.FARMING_TOOLS_EXTRADIBBERS, 1),
	SPADE(ItemID.SPADE, VarbitID.FARMING_TOOLS_SPADE, VarbitID.FARMING_TOOLS_EXTRASPADES, 1),
	SECATEURS(ItemID.SECATEURS, VarbitID.FARMING_TOOLS_SECATEURS, VarbitID.FARMING_TOOLS_EXTRASECATEURS, 1),
	/** A flag: the secateurs slot holds magic secateurs. */
	MAGIC_SECATEURS(ItemID.FAIRY_ENCHANTED_SECATEURS, VarbitID.FARMING_TOOLS_FAIRYSECATEURS, NONE, 0),
	COMPOST(ItemID.BUCKET_COMPOST, VarbitID.FARMING_TOOLS_COMPOST, VarbitID.FARMING_TOOLS_EXTRACOMPOST, 8),
	SUPERCOMPOST(ItemID.BUCKET_SUPERCOMPOST, VarbitID.FARMING_TOOLS_SUPERCOMPOST,
		VarbitID.FARMING_TOOLS_EXTRASUPERCOMPOST, 8),
	ULTRACOMPOST(ItemID.BUCKET_ULTRACOMPOST, VarbitID.FARMING_TOOLS_ULTRACOMPOST, NONE, 0),
	PLANT_CURE(ItemID.PLANT_CURE, VarbitID.FARMING_TOOLS_PLANTCURE, NONE, 0);

	private final int itemId;
	private final int baseVarbit;
	/** Overflow varbit, or {@link com.farmrunautopilot.data.DataConstants#NONE}. */
	private final int extraVarbit;
	/** How far the extra varbit is shifted (the game's script multiplies it by 2^shift). */
	private final int extraShift;

	/** The total stored, as the game's script works it out. */
	public int total(int base, int extra)
	{
		return base + (extra << extraShift);
	}
}

