	/**
	 * Which stored-bucket type value means which compost (the game's script only says 1 is empty, higher filled):
	 * the player says which compost is in theirs, the test captures the value.
	 */
	private static final class BucketCompost extends GuidedTest
	{
		private static Step isIt(Compost compost)
		{
			return ask("Is the bucket filled with " + compost.getDisplayName().toLowerCase() + "?").onAnswer((ctx, yes) ->
			{
				if (!yes)
				{
					return;
				}
				final int type = ctx.varbit(VarbitID.FARMING_TOOLS_BOTTOMLESS_BUCKET_TYPE);
				ctx.capture("Compost in it / type value", compost.getDisplayName() + " / " + type);
				ctx.capture("Uses value", ctx.varbit(VarbitID.FARMING_TOOLS_BOTTOMLESS_BUCKET_QUANTITY));
				if (Compost.fromBucketType(type) != compost)
				{
					ctx.problem("Type value " + type + " was read as " + Compost.fromBucketType(type) + ", not "
						+ compost.getDisplayName());
				}
			});
		}

		@Override
		public List<Step> steps()
		{
			return Arrays.asList(
				// An empty or missing bucket reads 0 or 1 whichever compost values are right, which proves nothing
				ask("Do you have a bottomless compost bucket with compost in it?").onAnswer((ctx, yes) ->
				{
					if (!yes)
					{
						ctx.cannotTest("a bottomless compost bucket with compost in it");
					}
				}),
				doThis("Store the bucket with a tool leprechaun",
					ctx -> ctx.varbit(VarbitID.FARMING_TOOLS_BOTTOMLESS_BUCKET_TYPE) > Compost.EMPTY_BUCKET_TYPE),
				isIt(Compost.COMPOST),
				isIt(Compost.SUPERCOMPOST),
				isIt(Compost.ULTRACOMPOST));
		}
	}

	/** The Grand Tree balloon route's unlock value (from Shortest Path's data, not checked in game). */
	private static final class HotAirBalloons extends GuidedTest
	{
		@Override
		public List<Step> steps()
		{
			return Arrays.asList(
				// Without the route, the value reads 0 whether or not it's the right one, which proves nothing
				ask("Have you done Enlightened Journey and unlocked the hot air balloon route to the Grand Tree?")
					.onAnswer((ctx, yes) ->
					{
						if (!yes)
						{
							ctx.cannotTest("the Grand Tree balloon route unlocked");
							return;
						}
						final int value = ctx.varbit(Unlock.BALLOON_GRAND_TREE.getVarbit());
						ctx.capture("Grand Tree route value", value);
						ctx.capture("Taverley route value", ctx.varbit(net.runelite.api.gameval.VarbitID.ZEP_MULTI_PICCARD));
						if (value <= 0)
						{
							ctx.problem("The Grand Tree route is unlocked but its game value is " + value);
						}
					}),
				ask("In Account > Unlocks, is \"Hot air balloon route to the Grand Tree unlocked\" ticked and marked "
					+ "(detected)?"));
		}
	}

	private static final class SpiritTrees extends GuidedTest
	{
		private static final Set<Unlock> PLANTED = Collections.unmodifiableSet(EnumSet.of(
			Unlock.SPIRIT_TREE_PORT_SARIM, Unlock.SPIRIT_TREE_BRIMHAVEN, Unlock.SPIRIT_TREE_FARMING_GUILD));

		@Override
		public List<String> missing(AccessSnapshot access, Holdings holdings, AccountSettings account)
		{
			return access.level(Skill.FARMING) >= 83 ? Collections.emptyList()
				: Collections.singletonList("Have a planted spirit tree (83 Farming)");
		}

		@Override
		public void setUp(RunConfig config, AccountSettings account)
		{
			account.getManualUnlocks().removeAll(PLANTED);
		}

		private static boolean spotted(TestContext ctx)
		{
			for (Unlock unlock : PLANTED)
			{
				if (ctx.hasUnlock(unlock))
				{
					ctx.capture("Spotted", unlock);
					return true;
				}
			}
			return false;
		}

		@Override
		public List<Step> steps()
		{
			return Arrays.asList(
				doThis("Go to a spirit tree you've planted: Port Sarim, Brimhaven or the Farming Guild",
					ctx -> ctx.inRegion(12082, 11058, 11057, 4922))
					.onDone(ctx -> ctx.capture("Arrived at", ctx.location())),
				doThis("Walk up to the spirit tree", GuidedTests.SpiritTrees::spotted)
					.orAskAfter(SPOT_TICKS, "The plugin hasn't spotted it. Is your spirit tree here fully grown?")
					.onAnswer((ctx, yes) ->
					{
						if (!yes)
						{
							ctx.cannotTest("a fully grown spirit tree you've planted");
							return;
						}
						ctx.capture("Spirit trees loaded", ctx.objectsNamed("Spirit tree"));
						ctx.capture("Standing at", ctx.location());
						ctx.problem("The grown spirit tree wasn't spotted");
					}));
		}

		@Override
		public void keep(AccountSettings kept, AccountSettings during)
		{
			for (Unlock unlock : PLANTED)
			{
				if (during.getManualUnlocks().contains(unlock))
				{
					kept.getManualUnlocks().add(unlock);
				}
			}
		}
	}

	private static final class HouseScan extends GuidedTest
	{
		@Override
		public void setUp(RunConfig config, AccountSettings account)
		{
			account.setAutoDetectHouse(true);
		}

		@Override
		public List<Step> steps()
		{
			return Arrays.asList(
				doThis("Enter your own house", TestContext::inOwnHouse)
					.onStart(ctx -> ctx.capture("My house before", ctx.houseSummary())),
				ask("Look at Account > My house. Do the jewellery box, pool, altar, fairy ring and spirit tree match your "
					+ "house? (The portal nexus isn't scanned: it stays as you set it.)")
					.onAnswer((ctx, yes) ->
					{
						ctx.capture("My house after", ctx.houseSummary());
						if (!yes)
						{
							ctx.problem("My house didn't match the house after scanning");
						}
					}),
				doThis("Now visit someone else's house", TestContext::visitingHouse)
					.onStart(ctx -> ctx.remember("house", ctx.houseSummary()))
					.optional(),
				ask("Did Account > My house stay the same while you were in their house?")
					.onAnswer((ctx, yes) ->
					{
						final String before = ctx.recall("house");
						if (before == null)
						{
							ctx.capture("Visited someone else's house", "no");
							return;
						}
						final boolean same = ctx.houseSummary().equals(before);
						ctx.capture("My house unchanged while visiting", same);
						if (!yes || !same)
						{
							ctx.problem("My house changed while visiting someone else's house");
						}
					})
					.optional());
		}

		@Override
		public void keep(AccountSettings kept, AccountSettings during)
		{
			// What the scan found is the point of the test
			kept.setPoh(during.getPoh());
		}
	}
}

package com.farmrunautopilot.testing;

import com.farmrunautopilot.access.AccessChecker;
import com.farmrunautopilot.access.AccessSnapshot;
import com.farmrunautopilot.access.PohDetector;
import com.farmrunautopilot.data.Unlock;
import com.farmrunautopilot.data.travel.TravelItem;
import com.farmrunautopilot.route.RunPlan;
import com.farmrunautopilot.route.RunService;
import com.farmrunautopilot.run.RunSession;
import com.farmrunautopilot.run.RunView;
import com.farmrunautopilot.run.SceneTracker;
import com.farmrunautopilot.settings.SettingsStore;
import com.farmrunautopilot.supply.Holdings;
import com.farmrunautopilot.supply.HoldingsTracker;
import com.farmrunautopilot.supply.ItemChargeTracker;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.coords.WorldPoint;

/**
 * What a guided test can see while it runs, and what it has found for the report. Client thread while the
 * test runs; read on the Swing thread only once it has finished.
 */
public class TestContext
{
	@Getter
	private final Client client;
	private final AccessChecker accessChecker;
	private final HoldingsTracker holdingsTracker;
	private final ItemChargeTracker itemCharges;
	private final RunSession runSession;
	private final RunService runService;
	@Getter
	private final SceneTracker scene;
	private final PohDetector pohDetector;
	private final SettingsStore settings;

	/** Game messages since the last check. */
	private final List<String> chat = new ArrayList<>();
	/** Values for the report, in the order found. */
	@Getter
	private final Map<String, String> captured = new LinkedHashMap<>();
	@Getter
	private final List<String> problems = new ArrayList<>();
	/** Set when the player lacks what the test needs. */
	private String cannotTest;
	/** Anything a test wants to remember between steps. */
	private final Map<String, Object> memory = new HashMap<>();

	TestContext(Client client, AccessChecker accessChecker, HoldingsTracker holdingsTracker,
		ItemChargeTracker itemCharges, RunSession runSession, RunService runService, SceneTracker scene,
		PohDetector pohDetector, SettingsStore settings)
	{
		this.client = client;
		this.accessChecker = accessChecker;
		this.holdingsTracker = holdingsTracker;
		this.itemCharges = itemCharges;
		this.runSession = runSession;
		this.runService = runService;
		this.scene = scene;
		this.pohDetector = pohDetector;
		this.settings = settings;
	}

	void addChat(String message)
	{
		chat.add(message);
	}

	void clearChat()
	{
		chat.clear();
	}

	/** Game messages since the last check. */
	public List<String> chat()
	{
		return Collections.unmodifiableList(chat);
	}

	public void capture(String what, Object value)
	{
		captured.put(what, String.valueOf(value));
	}

	public void problem(String text)
	{
		problems.add(text);
	}

	/**
	 * The player doesn't have what the test needs, so it stops without a result (nothing reported, and it can
	 * be run again later).
	 *
	 * @param needs what's missing, e.g. "a statue of Ates you've activated"
	 */
	public void cannotTest(String needs)
	{
		cannotTest = needs;
	}

	/** What the player was missing, or null. */
	public String getCannotTest()
	{
		return cannotTest;
	}

	public void remember(String key, Object value)
	{
		memory.put(key, value);
	}

	@SuppressWarnings("unchecked")
	public <T> T recall(String key)
	{
		return (T) memory.get(key);
	}

	public AccessSnapshot access()
	{
		return accessChecker.getSnapshot();
	}

	public Holdings holdings()
	{
		return holdingsTracker.getHoldings();
	}

	/** In the inventory or worn. */
	public boolean carries(int[] itemIds)
	{
		return holdings().carriedOnly().countAny(itemIds) > 0;
	}

	/** The plugin's count of an item's charges, or null if unknown. */
	public Integer charges(TravelItem item)
	{
		return itemCharges.getCharges().get(item);
	}

	public int varbit(int varbitId)
	{
		return client.getVarbitValue(varbitId);
	}

	public RunView runView()
	{
		return runSession.getView();
	}

	public RunPlan plan()
	{
		return runService.getPlan();
	}

	/** Ticked or detected in the plugin's settings right now. */
	public boolean hasUnlock(Unlock unlock)
	{
		return settings.getAccount().getManualUnlocks().contains(unlock) || access().getUnlocks().contains(unlock);
	}

	public boolean inOwnHouse()
	{
		return pohDetector.isScanningHouse();
	}

	public boolean visitingHouse()
	{
		return client.isInInstancedRegion() && pohDetector.isVisiting();
	}

	public String houseSummary()
	{
		return String.valueOf(settings.getAccount().getPoh());
	}

	public WorldPoint location()
	{
		final Player player = client.getLocalPlayer();
		return player != null ? player.getWorldLocation() : null;
	}

	public int region()
	{
		final WorldPoint location = location();
		return location != null ? location.getRegionID() : -1;
	}

	public boolean inRegion(Integer... regions)
	{
		return Arrays.asList(regions).contains(region());
	}

	/**
	 * Loaded objects whose name contains this, with their ID, place and options. Looks at the whole scene, so
	 * only call it once, when a step needs it for the report.
	 */
	public String objectsNamed(String name)
	{
		final List<String> found = new ArrayList<>();
		final Scene scene = client.getTopLevelWorldView().getScene();
		final Tile[][][] tiles = scene.getTiles();
		final int plane = client.getTopLevelWorldView().getPlane();
		for (Tile[] column : tiles[plane])
		{
			for (Tile tile : column)
			{
				if (tile == null || tile.getGameObjects() == null)
				{
					continue;
				}
				for (GameObject object : tile.getGameObjects())
				{
					if (object == null || found.size() >= 10)
					{
						continue;
					}
					ObjectComposition composition = client.getObjectDefinition(object.getId());
					if (composition != null && composition.getImpostorIds() != null)
					{
						composition = composition.getImpostor();
					}
					if (composition != null && composition.getName() != null
						&& composition.getName().toLowerCase().contains(name.toLowerCase()))
					{
						found.add(composition.getName() + " #" + object.getId() + " at " + object.getWorldLocation()
							+ " " + Arrays.toString(composition.getActions()));
					}
				}
			}
		}
		return found.isEmpty() ? "none" : String.join("; ", found);
	}

	/** Loaded NPCs whose name contains this, with their ID and place. */
	public String npcsNamed(String name)
	{
		final List<String> found = new ArrayList<>();
		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			if (npc.getName() != null && npc.getName().toLowerCase().contains(name.toLowerCase()) && found.size() < 10)
			{
				found.add(npc.getName() + " #" + npc.getId() + " at " + npc.getWorldLocation());
			}
		}
		return found.isEmpty() ? "none" : String.join("; ", found);
	}
}

package com.farmrunautopilot.testing;

import lombok.Getter;

/**
 * A feature that couldn't be tried in development and needs feedback (the "I NEED YOUR HELP!" list), with
 * steps a player can follow by hand. Each also has a guided test ({@link GuidedTests}). The constant's name
 * keys its saved result and appears in logs and reports, so don't rename one once released. Remove an item
 * once it's confirmed (see CLAUDE.md).
 */
@Getter
public enum TestItem
{
	SPELLBOOK_SWAP(Tab.RUN, "Spellbook Swap",
		"On the Lunar spellbook (96 Magic, Dream Mentor done) with no house altar for the other spellbook, "
			+ "plan a stop whose teleport is from another spellbook and that you have no tablet for. The Run "
			+ "tab should warn that you need Spellbook Swap, its runes should be on the bank's Farm run tab, and the "
			+ "spell should be outlined in your spellbook on that step."),
	WEISS_FIRE(Tab.FARM, "Fire of Nourishment at Weiss",
		"If you've built the Fire of Nourishment, untick it in Account > Unlocks, then go to Weiss. It should "
			+ "tick itself once the fire is in view, and the Weiss herb patch should join your herb runs."),
	FORTIS_CHAMPION(Tab.FARM, "Civitas herbs and the Colosseum",
		"With \"Champion rank at the Fortis Colosseum\" ticked in Account > Unlocks, the Civitas herb patch "
			+ "should count as disease-free: no plant cure or protection asked for it.", 2),
	ATES_CHARGES(Tab.TRAVEL, "Pendant of Ates charges",
		"With the pendant on you, Settings > Debug > Detected should show the same charges as its Check. Teleport once "
			+ "and it should drop by one. Start a teleport and cancel it: it shouldn't change."),
	TALISMAN_CHARGES(Tab.TRAVEL, "Xeric's talisman charges",
		"Check the talisman. Settings > Debug > Detected should show the same number. Teleport once and it should drop "
			+ "by one. At 0 charges, Auto (best) should stop picking it."),
	KHARYRLL(Tab.TRAVEL, "Kharyrll Teleport highlight",
		"On the Ancient spellbook with Kharyrll Teleport planned for Port Phasmatys (and no tablet), the "
			+ "spell should be outlined in your spellbook on that step."),
	BUCKET_COMPOST(Tab.FARM, "Bottomless bucket at the tool leprechaun",
		"With a bottomless compost bucket that has compost in it, store it with any tool leprechaun. Settings > "
			+ "Debug > Detected should then show the bucket with the right compost and uses."),
	SPIRIT_TREES(Tab.ACCOUNT, "Planted spirit trees",
		"Untick your planted spirit tree in Account > Unlocks, then go to it (Port Sarim, Brimhaven or the "
			+ "Farming Guild). It should tick itself once the grown tree is in view."),
	HOT_AIR_BALLOONS(Tab.ACCOUNT, "Hot air balloon from the Grand Tree",
		"If you've done Enlightened Journey and unlocked the Grand Tree balloon route (60 Firemaking, 3 magic logs), Account > "
			+ "Unlocks should show \"Hot air balloon route to the Grand Tree unlocked (detected)\" ticked. A run with "
			+ "Gnome Stronghold and Taverley can then fly from the Grand Tree to Taverley with one normal log."),
	HOUSE_SCAN(Tab.ACCOUNT, "House scanning (beta)",
		"Tick \"Detect furniture when I enter my house\" in Account > My house, then enter your house: your "
			+ "jewellery box, pool, altar, fairy ring and spirit tree should fill in (the portal nexus isn't scanned). "
			+ "Then visit someone else's house: nothing of yours should change.", 2);

	/** The sidebar tab a feature belongs to. */
	@Getter
	public enum Tab
	{
		RUN("Run"), FARM("Farm"), TRAVEL("Travel"), ACCOUNT("Account");

		private final String label;

		Tab(String label)
		{
			this.label = label;
		}
	}

	private final Tab tab;
	private final String title;
	private final String howToTry;
	/**
	 * Bump this when a fix means earlier results no longer count, so players who already ran the test are
	 * asked again.
	 */
	private final int revision;

	TestItem(Tab tab, String title, String howToTry)
	{
		this(tab, title, howToTry, 1);
	}

	TestItem(Tab tab, String title, String howToTry, int revision)
	{
		this.tab = tab;
		this.title = title;
		this.howToTry = howToTry;
		this.revision = revision;
	}

	/** Where this client's result for the current revision is saved. */
	public String key()
	{
		return "help." + name() + (revision > 1 ? ".v" + revision : "");
	}
}

package com.farmrunautopilot.testing;

import java.io.UnsupportedEncodingException;
import java.net.URLEncoder;
import java.util.List;
import java.util.Map;

/** A finished guided test as a pre-filled GitHub issue. */
public final class TestReport
{
	static final String NEW_ISSUE_URL = "https://github.com/elzerma/farm-run-autopilot/issues/new";
	/** Long links are refused by browsers and GitHub; the body is cut to stay well under. */
	private static final int MAX_BODY = 6000;

	private TestReport()
	{
	}

	/** One line for the log and the developer's clipboard, e.g. "Guided test finished: X = Good to go". */
	public static String summary(TestItem item, boolean passed, List<String> problems)
	{
		return "Guided test finished: " + item.name() + " = " + (passed ? TestRunner.GOOD : TestRunner.ATTENTION)
			+ (problems.isEmpty() ? "" : " " + problems) + " (full report in the client log)";
	}

	public static String title(TestItem item, boolean passed)
	{
		return "Test: " + item.getTitle() + " - " + (passed ? "works" : "needs attention");
	}

	/**
	 * @param steps each step's text and how it went, e.g. "Detected" or "Answered No"
	 */
	public static String body(TestItem item, boolean passed, String version, List<String[]> steps,
		Map<String, String> captured, List<String> problems)
	{
		final StringBuilder b = new StringBuilder();
		b.append("**Guided test:** ").append(item.getTitle()).append(" (`").append(item.name()).append("`)\n");
		b.append("**Result:** ").append(passed ? "Works" : "Needs attention").append('\n');
		b.append("**RuneLite:** ").append(version).append("\n\n");
		b.append("### Steps\n");
		for (String[] step : steps)
		{
			// A plain list: an unticked box next to a "No" answer read like a failure when it wasn't one
			b.append("- ").append(step[0]).append(" **").append(step[1]).append("**\n");
		}
		if (!problems.isEmpty())
		{
			b.append("\n### Problems\n");
			for (String problem : problems)
			{
				b.append("- ").append(problem).append('\n');
			}
		}
		if (!captured.isEmpty())
		{
			b.append("\n### What the plugin saw\n");
			for (Map.Entry<String, String> e : captured.entrySet())
			{
				b.append("- **").append(e.getKey()).append(":** `").append(e.getValue().replace('`', '\'')).append("`\n");
			}
		}
		b.append("\n### Anything else?\n\n");
		return b.length() <= MAX_BODY ? b.toString() : b.substring(0, MAX_BODY) + "\n\n(cut short)\n";
	}

	/**
	 * The "Share your run times" report (Sprint 9): the plugin version, the unlocks that change travel times, and
	 * the learned legs, nothing else about the player. Cut short like a test report if it's long.
	 *
	 * @param unlocks e.g. "Fairy rings: yes", one per line
	 * @param legs from {@code LearnedTimes.summary()}
	 */
	public static String runTimesBody(String version, List<String> unlocks, List<String> legs)
	{
		final StringBuilder b = new StringBuilder();
		b.append("Run times shared from Farm Run Autopilot ").append(version).append(".\n\n");
		b.append("**Unlocks that change times**\n");
		for (String line : unlocks)
		{
			b.append("- ").append(line).append('\n');
		}
		b.append("\n**Learned legs** (stop, way, how; median seconds; samples)\n```\n");
		for (String line : legs)
		{
			b.append(line).append('\n');
		}
		b.append("```\n");
		return b.length() <= MAX_BODY ? b.toString() : b.substring(0, MAX_BODY) + "\n```\n\n(cut short)\n";
	}

	public static String url(String title, String body)
	{
		return NEW_ISSUE_URL + "?title=" + encode(title) + "&body=" + encode(body);
	}

	private static String encode(String text)
	{
		try
		{
			// URLEncoder makes spaces "+", which GitHub reads as spaces in a query
			return URLEncoder.encode(text, "UTF-8");
		}
		catch (UnsupportedEncodingException e)
		{
			throw new IllegalStateException(e);
		}
	}
}

package com.farmrunautopilot.testing;

import com.farmrunautopilot.access.AccessChecker;
import com.farmrunautopilot.access.PohDetector;
import com.farmrunautopilot.route.RunService;
import com.farmrunautopilot.run.RunSession;
import com.farmrunautopilot.run.RunView;
import com.farmrunautopilot.run.SceneTracker;
import com.farmrunautopilot.settings.SettingsStore;
import com.farmrunautopilot.supply.Holdings;
import com.farmrunautopilot.supply.HoldingsTracker;
import com.farmrunautopilot.supply.ItemChargeTracker;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Named;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.RuneLiteProperties;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.LinkBrowser;

/**
 * Runs one guided test at a time: backs up the settings and applies the test's, walks the player through its
 * steps on the Run tab, then puts the settings back and opens a pre-filled GitHub issue with the result.
 *
 * <p>{@link #start} and {@link #cancel} are called on the Swing thread; everything else on the client thread.
 */
@Slf4j
@Singleton
public class TestRunner
{
	/** Result names shared with the "I NEED YOUR HELP!" list. */
	public static final String GOOD = "Good to go";
	public static final String ATTENTION = "Needs attention";
	/** Dev client only: show the player view of the help list and tests. */
	private static final String PREVIEW_AS_PLAYER = "help.previewAsPlayer";

	private final Client client;
	private final ClientThread clientThread;
	private final SettingsStore settings;
	private final AccessChecker accessChecker;
	private final HoldingsTracker holdingsTracker;
	private final ItemChargeTracker itemCharges;
	private final RunSession runSession;
	private final RunService runService;
	private final SceneTracker scene;
	private final PohDetector pohDetector;
	/** The dev client: the whole report also goes to the log, to be read back without submitting it. */
	private final boolean developerMode;

	// Client thread
	private TestItem item;
	private GuidedTest test;
	private List<GuidedTest.Step> steps;
	private int stepIndex;
	private int stepTicks;
	private boolean asking;
	private TestContext context;
	/** Each finished step's text and how it went. */
	private final List<String[]> results = new ArrayList<>();

	private volatile TestView view = TestView.NONE;
	/** Set on the Swing thread as soon as a test is started, so a second can't start before the first begins. */
	private volatile boolean busy;

	@Inject
	TestRunner(Client client, ClientThread clientThread, SettingsStore settings, AccessChecker accessChecker,
		HoldingsTracker holdingsTracker, ItemChargeTracker itemCharges, RunSession runSession, RunService runService,
		SceneTracker scene, PohDetector pohDetector, @Named("developerMode") boolean developerMode)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.settings = settings;
		this.accessChecker = accessChecker;
		this.holdingsTracker = holdingsTracker;
		this.itemCharges = itemCharges;
		this.runSession = runSession;
		this.runService = runService;
		this.scene = scene;
		this.pohDetector = pohDetector;
		this.developerMode = developerMode;
	}

	public TestView getView()
	{
		return view;
	}

	public boolean isBusy()
	{
		return busy;
	}

	/** The dev client (RuneLite developer mode), whether or not it's previewing the player view. */
	public boolean isDeveloperMode()
	{
		return developerMode;
	}

	/** The dev client, not previewing as a player: results go to the clipboard instead of GitHub. */
	public boolean asDeveloper()
	{
		return developerMode && !Boolean.parseBoolean(settings.getClientValue(PREVIEW_AS_PLAYER));
	}

	/** In the dev client, show what players see. Swing thread. */
	public void setPreviewAsPlayer(boolean preview)
	{
		settings.setClientValue(PREVIEW_AS_PLAYER, preview ? "true" : null);
	}

	/** Open the pre-filled GitHub issue from a finished test's last step. Swing thread. */
	public void openReport()
	{
		final TestView shown = view;
		if (shown.isReporting())
		{
			LinkBrowser.browse(shown.getReportUrl());
		}
	}

	/** Close a finished test's last step. Swing thread. */
	public void closeReport()
	{
		if (view.isFinished())
		{
			view = TestView.NONE;
		}
	}

	/** Why this test can't be started now; empty if it can. Swing thread. */
	public List<String> missing(TestItem item)
	{
		final List<String> missing = new ArrayList<>();
		if (busy)
		{
			missing.add("Another test is running");
			return missing;
		}
		if (!accessChecker.getSnapshot().isKnown())
		{
			missing.add("Log in first");
			return missing;
		}
		// A route built but not started doesn't count (Sean: "no run going" was told to stop it); begin clears it
		if (runSession.getView().getState() == RunView.State.RUNNING)
		{
			missing.add("Stop your run first");
		}
		missing.addAll(GuidedTests.of(item).missing(accessChecker.getSnapshot(), holdingsTracker.getHoldings(),
			settings.getAccount()));
		return missing;
	}

	/** Back up the settings, apply the test's and begin. Swing thread. */
	public void start(TestItem item)
	{
		if (busy)
		{
			return;
		}
		busy = true;
		final GuidedTest test = GuidedTests.of(item);
		settings.startTest(test::setUp);
		log.info("Guided test started: {}", item.name());
		clientThread.invoke(() -> begin(item, test));
	}

	private void begin(TestItem item, GuidedTest test)
	{
		runSession.cancelIfNotRunning();
		this.item = item;
		this.test = test;
		this.steps = test.steps();
		this.stepIndex = -1;
		this.context = new TestContext(client, accessChecker, holdingsTracker, itemCharges, runSession, runService,
			scene, pohDetector, settings);
		results.clear();
		nextStep();
	}

	/** Stop without reporting. Swing thread. */
	public void cancel()
	{
		clientThread.invoke(() ->
		{
			if (item != null)
			{
				log.info("Guided test cancelled: {}", item.name());
				finish(false, false);
			}
		});
	}

	public void answer(boolean yes)
	{
		clientThread.invoke(() ->
		{
			if (item == null || !asking)
			{
				return;
			}
			final GuidedTest.Step step = steps.get(stepIndex);
			if (step.onAnswer != null)
			{
				step.onAnswer.accept(context, yes);
			}
			else if (!yes)
			{
				context.problem("Answered No: " + step.question);
			}
			results.add(new String[]{step.question, yes ? "Answered Yes" : "Answered No"});
			nextStep();
		});
	}

	public void skip()
	{
		clientThread.invoke(() ->
		{
			if (item != null && steps.get(stepIndex).optional)
			{
				results.add(new String[]{steps.get(stepIndex).text, "Skipped"});
				nextStep();
			}
		});
	}

	public void onChatMessage(String message)
	{
		if (item != null)
		{
			context.addChat(message);
			check();
		}
	}

	public void onGameTick()
	{
		if (item == null)
		{
			return;
		}
		stepTicks++;
		final GuidedTest.Step step = steps.get(stepIndex);
		if (!asking && step.askAfterTicks >= 0 && stepTicks >= step.askAfterTicks)
		{
			asking = true;
			publish();
		}
		check();
	}

	/** Account switched or logged out: give up quietly, so the settings go back to the right account. */
	public void onLoggedOut()
	{
		if (item != null)
		{
			finish(false, false);
		}
	}

	private void check()
	{
		final GuidedTest.Step step = steps.get(stepIndex);
		if (step.check != null && step.check.test(context))
		{
			if (step.onDone != null)
			{
				step.onDone.accept(context);
			}
			results.add(new String[]{step.text, "Detected"});
			context.clearChat();
			nextStep();
			return;
		}
		context.clearChat();
	}

	private void nextStep()
	{
		if (context.getCannotTest() != null)
		{
			cannotTest();
			return;
		}
		stepIndex++;
		stepTicks = 0;
		if (stepIndex >= steps.size())
		{
			finish(true, context.getProblems().isEmpty());
			return;
		}
		final GuidedTest.Step step = steps.get(stepIndex);
		asking = step.check == null;
		if (step.onStart != null)
		{
			step.onStart.accept(context);
		}
		publish();
	}

	private void publish()
	{
		final GuidedTest.Step step = steps.get(stepIndex);
		final String text = asking && step.check != null ? step.question : step.text;
		view = new TestView(item, item.getTitle(), stepIndex + 1, steps.size(), text, asking, step.optional,
			bringLines(), false, null);
	}

	private List<String> bringLines()
	{
		final Holdings holdings = holdingsTracker.getHoldings();
		final List<String> lines = new ArrayList<>();
		for (GuidedTest.Need need : test.bring())
		{
			final String where;
			if (holdings.carriedOnly().countAny(need.getItemIds()) > 0)
			{
				where = "on you";
			}
			else if (holdings.countAny(need.getItemIds()) > 0)
			{
				where = "in your bank or storage";
			}
			else
			{
				where = "not found";
			}
			lines.add(need.getLabel() + ": " + where);
		}
		return lines;
	}

	/**
	 * @param report open the GitHub issue (not when cancelled)
	 */
	/**
	 * The player doesn't have what the test needs: stop without a result. Nothing is reported or saved, so the
	 * test stays on the list for later.
	 */
	private void cannotTest()
	{
		final TestItem done = item;
		final GuidedTest finished = test;
		final String needs = context.getCannotTest();
		if (finished.usesRun())
		{
			runSession.cancel();
		}
		item = null;
		test = null;
		this.steps = null;
		context = null;
		view = TestView.NONE;
		final String summary = "Guided test not possible: " + done.name() + " (needs " + needs + ")";
		log.info(summary);
		final boolean developer = asDeveloper();
		if (developer)
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Farm Run Autopilot: this test couldn't be done. "
				+ "The result is on your clipboard to paste to Claude.", null);
		}
		SwingUtilities.invokeLater(() ->
		{
			busy = false;
			settings.endTest(finished::keep);
			if (developer)
			{
				Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(summary), null);
			}
			view = TestView.finished(done, "This test needs " + needs + ", so there's nothing to report yet. Your "
				+ "settings are back to how they were. Come back to it once you have it.", null);
		});
	}

	private void finish(boolean report, boolean passed)
	{
		final TestItem done = item;
		final GuidedTest finished = test;
		final TestContext seen = context;
		final List<String[]> steps = new ArrayList<>(results);
		final Map<String, String> captured = Collections.unmodifiableMap(seen.getCaptured());
		final List<String> problems = new ArrayList<>(seen.getProblems());
		if (finished.usesRun())
		{
			// The run was planned with the test's settings, which are about to change back
			runSession.cancel();
		}
		item = null;
		test = null;
		this.steps = null;
		context = null;
		view = TestView.NONE;
		final String summary = TestReport.summary(done, passed, problems);
		if (report)
		{
			log.info(summary);
			if (asDeveloper())
			{
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Farm Run Autopilot: test "
					+ (passed ? "passed" : "needs attention") + ". The result is on your clipboard to paste to Claude.",
					null);
			}
		}
		SwingUtilities.invokeLater(() ->
		{
			busy = false;
			if (report)
			{
				// Before the settings go back, which redraws the list without this test
				settings.setClientValue(done.key(), passed ? GOOD : ATTENTION);
			}
			settings.endTest(finished::keep);
			if (!report)
			{
				return;
			}
			final String body = TestReport.body(done, passed, RuneLiteProperties.getVersion(), steps, captured,
				problems);
			if (asDeveloper())
			{
				// The developer pastes the summary to Claude, who reads the full report from the log
				log.info("Guided test report: {}\n{}", done.name(), body);
				Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(summary), null);
			}
			else
			{
				// The last step on the Run tab: the player opens it and submits it themselves
				view = TestView.reporting(done, passed, TestReport.url(TestReport.title(done, passed), body));
			}
		});
	}
}

package com.farmrunautopilot.testing;

import java.util.Collections;
import java.util.List;
import lombok.Value;

/**
 * What the Run tab shows for a guided test in progress, or once it has finished: the GitHub report to send,
 * or why it couldn't be done. Immutable.
 */
@Value
public class TestView
{
	public static final TestView NONE = new TestView(null, null, 0, 0, null, false, false, Collections.emptyList(),
		false, null);

	/** Null when no test is running. */
	TestItem item;
	String title;
	int step;
	int steps;
	String text;
	/** Waiting for Yes or No. */
	boolean question;
	boolean optional;
	/** What to bring, e.g. "Pendant of Ates: in your bank". */
	List<String> bring;
	/** The test is over; only a message (and maybe the report) is left, with a Close button. */
	boolean finished;
	/** The pre-filled GitHub issue to open, for a finished test that has a report; otherwise null. */
	String reportUrl;

	public boolean isActive()
	{
		return item != null;
	}

	/** The test is done and only the GitHub report is left. */
	public boolean isReporting()
	{
		return reportUrl != null;
	}

	static TestView reporting(TestItem item, boolean passed, String reportUrl)
	{
		return finished(item, (passed
			? "Done, and it looks like it works. "
			: "Done, and something needs attention. ")
			+ "Last step: open the GitHub issue form. Your results are already filled in. Sign in to GitHub if it "
			+ "asks, add anything else you noticed at the bottom, then press \"Create\" (or \"Submit new issue\") "
			+ "to send it. Nothing is sent until you do. Your settings are already back to how they were.",
			reportUrl);
	}

	static TestView finished(TestItem item, String text, String reportUrl)
	{
		return new TestView(item, item.getTitle(), 0, 0, text, false, false, Collections.emptyList(), true,
			reportUrl);
	}
}

package com.farmrunautopilot.tracking;

import lombok.Value;

/**
 * Farming tick maths, following RuneLite core {@code FarmingTracker.getTickTime}. Crops grow on fixed
 * minute boundaries (every 5, 20, 40, 160 ... minutes), shifted by an account-specific offset that is
 * learned by watching a crop grow.
 */
@Value
public class FarmingTick
{
	/** Offset in minutes (stored as a positive number), or null if never observed. */
	Integer offsetMinutes;
	/** Tick rate the offset was observed on; longer rates give a more precise offset. */
	Integer offsetPrecisionMinutes;

	public static final FarmingTick UNKNOWN = new FarmingTick(null, null);

	/**
	 * Time (epoch seconds) of the tick boundary {@code ticks} ticks after the boundary at or before
	 * {@code epochSeconds}.
	 */
	public long tickTime(int tickMinutes, int ticks, long epochSeconds)
	{
		final long offsetSeconds = offsetSecondsFor(tickMinutes);
		final long shifted = epochSeconds + offsetSeconds;
		final long tickSeconds = tickMinutes * 60L;
		final long currentTick = shifted - (shifted % tickSeconds);
		return currentTick + ticks * tickSeconds - offsetSeconds;
	}

	private long offsetSecondsFor(int tickMinutes)
	{
		if (offsetMinutes == null || offsetPrecisionMinutes == null)
		{
			return 0;
		}
		if (offsetPrecisionMinutes >= tickMinutes || offsetPrecisionMinutes >= 40)
		{
			return (offsetMinutes % tickMinutes) * 60L;
		}
		return 0;
	}

	/**
	 * The offset implied by seeing a growth tick happen at {@code epochSeconds} on a crop with this tick
	 * rate.
	 */
	public static int observedOffsetMinutes(int tickMinutes, long epochSeconds)
	{
		return (int) Math.abs(((epochSeconds / 60) % tickMinutes) - tickMinutes);
	}
}

package com.farmrunautopilot.tracking;

import com.farmrunautopilot.data.Crop;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.PatchState;
import lombok.Value;

/**
 * Best guess at a patch's state right now, worked forward from the last observation.
 */
@Value
public class PatchPrediction
{
	public enum Source
	{
		/** Seen by this plugin. */
		THIS_PLUGIN,
		/** Borrowed from RuneLite's Time Tracking plugin (patch not seen by us yet). */
		TIME_TRACKING
	}

	Patch patch;
	/** Null for empty or weedy patches and crops outside the v1 catalogue. */
	Crop crop;
	PatchState state;
	/** Growth stage, weed level or fruit count; see {@link com.farmrunautopilot.data.DecodedPatch}. */
	int stage;
	int stages;
	/**
	 * When growth (or weed regrowth, or fruit regrowth) finishes, in epoch seconds; 0 if nothing is
	 * changing on its own.
	 */
	long doneAt;
	long observedAt;
	/** When we saw this crop planted, in epoch seconds; 0 if unknown. */
	long plantedAt;
	Source source;
}

package com.farmrunautopilot.tracking;

import com.farmrunautopilot.data.Crop;
import com.farmrunautopilot.data.DecodedPatch;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.PatchState;
import com.farmrunautopilot.data.PatchStateDecoder;
import com.farmrunautopilot.data.PatchType;

/**
 * Works a patch observation forward to "now" (SPEC 10.3), following RuneLite core
 * {@code FarmingTracker.predictPatch}.
 *
 * <p>Unlike RuneLite, weeds are not predicted to grow back on empty patches: in-game testing showed a raked
 * patch staying clear well past a 5 minute tick, so the last seen weed level is kept.
 */
public final class PatchPredictor
{
	/** A grown fruit tree holds 0-6 fruit. */
	static final int FRUIT_STAGES = 7;

	private PatchPredictor()
	{
	}

	public static PatchPrediction predict(Patch patch, PatchRecord record, long plantedAt,
		PatchPrediction.Source source, long now, FarmingTick tick, boolean leagues)
	{
		final DecodedPatch decoded = PatchStateDecoder.decode(patch.getType(), record.getValue());
		final Crop crop = decoded.getCrop();
		PatchState state = decoded.getState();
		int stage = decoded.getStage();
		int stages = 1;
		int tickMinutes = 0;

		if (state == PatchState.GROWING && crop != null)
		{
			tickMinutes = crop.getTickMinutes();
			stages = crop.getStages();
		}
		else if (state == PatchState.HARVESTABLE && patch.getType() == PatchType.FRUIT_TREE)
		{
			tickMinutes = Crop.FRUIT_REGROW_MINUTES;
			stages = FRUIT_STAGES;
		}

		if (leagues)
		{
			// Farming ticks on leagues worlds are 1 minute instead of 5
			tickMinutes /= 5;
		}

		long doneAt = 0;
		if (tickMinutes > 0)
		{
			final long tickNow = tick.tickTime(tickMinutes, 0, now);
			final long tickSeen = tick.tickTime(tickMinutes, 0, record.getObservedAt());
			final int ticksPassed = (int) ((tickNow - tickSeen) / (tickMinutes * 60L));

			doneAt = tick.tickTime(tickMinutes, stages - 1 - stage, tickSeen);
			stage = Math.min(stage + Math.max(ticksPassed, 0), stages - 1);

			if (state == PatchState.GROWING && stage == stages - 1)
			{
				state = patch.getType().isProtectable() ? PatchState.CHECK_HEALTH : PatchState.HARVESTABLE;
			}
		}

		return new PatchPrediction(patch, crop, state, stage, stages, doneAt, record.getObservedAt(), plantedAt, source);
	}

	/**
	 * Whether going from {@code previous} to {@code current} can only be the game's growth tick (not a
	 * player action), so its timing reveals the account's tick offset. Mirrors RuneLite core
	 * {@code FarmingTracker.isObservedGrowthTick}.
	 */
	public static boolean isObservedGrowthTick(PatchType type, DecodedPatch previous, DecodedPatch current)
	{
		final Crop crop = previous.getCrop();
		if (crop == null || current.getCrop() != crop)
		{
			return false;
		}

		switch (previous.getState())
		{
			case GROWING:
				switch (current.getState())
				{
					case GROWING:
					case CHECK_HEALTH:
						return current.getStage() - previous.getStage() == 1;
					case DISEASED:
						return true;
					case HARVESTABLE:
						// Trees only reach HARVESTABLE through the player's check-health.
						return !type.isProtectable();
					default:
						return false;
				}
			case DISEASED:
				return current.getState() == PatchState.DEAD;
			default:
				return false;
		}
	}

	/** Whether this change means the player just planted something. */
	public static boolean isPlanting(DecodedPatch previous, DecodedPatch current)
	{
		return current.getState() == PatchState.GROWING && current.getCrop() != null && current.getStage() == 0
			&& (previous.getCrop() == null || previous.getState() != PatchState.GROWING);
	}
}

package com.farmrunautopilot.tracking;

import lombok.Value;

/**
 * One saved observation of a patch: the raw varbit value and when it was seen. Stored as
 * {@code "<value>:<epochSeconds>"}, the same format as RuneLite core Time Tracking.
 */
@Value
public class PatchRecord
{
	int value;
	long observedAt;

	public String format()
	{
		return value + ":" + observedAt;
	}

	/**
	 * @return the record, or null if the text is missing or malformed
	 */
	public static PatchRecord parse(String text)
	{
		if (text == null)
		{
			return null;
		}
		final String[] parts = text.split(":");
		if (parts.length != 2)
		{
			return null;
		}
		try
		{
			final int value = Integer.parseInt(parts[0]);
			final long observedAt = Long.parseLong(parts[1]);
			return observedAt > 0 ? new PatchRecord(value, observedAt) : null;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

package com.farmrunautopilot.tracking;

import com.farmrunautopilot.data.PatchType;

/**
 * Short plain-language descriptions of patch predictions for the sidebar.
 */
public final class PatchStatusText
{
	private PatchStatusText()
	{
	}

	/**
	 * e.g. "Ranarr - ready in 34m", "Magic - check health", "Empty".
	 */
	public static String describe(PatchPrediction p, long now)
	{
		if (p == null)
		{
			return "Not seen yet";
		}

		final String crop = p.getCrop() != null ? p.getCrop().getDisplayName() : null;
		final PatchType type = p.getPatch().getType();
		switch (p.getState())
		{
			case EMPTY:
				return "Empty";
			case WEEDS:
				return "Weeds";
			case GROWING:
				if (crop == null)
				{
					return "Something else growing";
				}
				return crop + " - ready in " + duration(p.getDoneAt() - now);
			case CHECK_HEALTH:
				return crop + " - check health";
			case HARVESTABLE:
				if (crop == null)
				{
					return "Something else ready";
				}
				if (type == PatchType.HERB)
				{
					return crop + " - ready to pick";
				}
				if (type == PatchType.FRUIT_TREE)
				{
					final int fruit = p.getStage();
					final String count = crop + " - " + fruit + " fruit";
					return fruit < p.getStages() - 1 && p.getDoneAt() > now
						? count + " (full in " + duration(p.getDoneAt() - now) + ")"
						: count;
				}
				return crop + " - grown, ready to clear";
			case STUMP:
				return crop + " - stump";
			case DISEASED:
				return (crop != null ? crop : "Crop") + " - diseased";
			case DEAD:
				return "Dead " + (crop != null ? crop : type.getDisplayName()).toLowerCase();
			default:
				return "Unknown state";
		}
	}

	/**
	 * e.g. "2h 05m", "45m", "<1m".
	 */
	public static String duration(long seconds)
	{
		if (seconds < 60)
		{
			return "<1m";
		}
		final long minutes = (seconds + 59) / 60;
		final long hours = minutes / 60;
		final long mins = minutes % 60;
		if (hours == 0)
		{
			return mins + "m";
		}
		return hours + "h " + (mins < 10 ? "0" : "") + mins + "m";
	}

	/**
	 * e.g. "seen 3h 10m ago".
	 */
	public static String age(long epochSeconds, long now)
	{
		final long seconds = now - epochSeconds;
		return seconds < 60 ? "seen just now" : "seen " + duration(seconds) + " ago";
	}
}

package com.farmrunautopilot.tracking;

import com.farmrunautopilot.FarmRunAutopilotConfig;
import com.farmrunautopilot.data.DecodedPatch;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.PatchState;
import com.farmrunautopilot.data.PatchStateDecoder;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.WidgetNode;
import net.runelite.api.WorldType;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.WidgetModalMode;
import net.runelite.client.config.ConfigManager;

/**
 * Records patch varbits while the player is near a patch and predicts every patch's state (SPEC 10).
 * Observations are stored per account under {@code patch.<regionId>.<varbitId>}.
 */
@Slf4j
@Singleton
public class PatchTracker
{
	private static final String PATCH_PREFIX = "patch.";
	private static final String PLANTED_SUFFIX = ".planted";
	private static final String AUTOWEED_KEY = "autoweed";
	private static final String TICK_OFFSET_KEY = "farmTickOffset";
	private static final String TICK_OFFSET_PRECISION_KEY = "farmTickOffsetPrecision";
	/** RuneLite core Time Tracking, read only as a fallback for patches we have never seen (SPEC 10.5). */
	private static final String TIME_TRACKING_GROUP = "timetracking";
	/** Re-save an unchanged observation at most this often, like core Time Tracking. */
	private static final long RESAVE_SECONDS = 5 * 60;

	private static final Map<Integer, List<Patch>> PATCHES_BY_REGION = new HashMap<>();

	static
	{
		for (Patch patch : Patch.values())
		{
			PATCHES_BY_REGION.computeIfAbsent(patch.getRegionId(), k -> new ArrayList<>()).add(patch);
			for (int region : patch.getExtraRegionIds())
			{
				PATCHES_BY_REGION.computeIfAbsent(region, k -> new ArrayList<>()).add(patch);
			}
		}
	}

	private final Client client;
	/** A Leagues world (patches grow faster), read on the client thread. */
	private volatile boolean leaguesWorld;
	private final ConfigManager configManager;

	private Set<Patch> lastPatches = Collections.emptySet();
	/** When each patch was last seen unchanged this session; saved config only refreshes every few minutes.
	 * Written on the client thread, read on the Swing thread. */
	private final Map<Patch, Long> lastSeen = new ConcurrentHashMap<>();

	@Inject
	PatchTracker(Client client, ConfigManager configManager)
	{
		this.client = client;
		this.configManager = configManager;
	}

	/** Patches whose varbits the game is sending right now, i.e. the player is next to them. Client thread. */
	public Set<Patch> getPatchesInRange()
	{
		return lastPatches;
	}

	/** Forget per-session state, e.g. after logging in to another account. */
	public void reset()
	{
		lastPatches = Collections.emptySet();
		lastSeen.clear();
	}

	/**
	 * Saves the varbits of the patches around {@code location}. Call once per game tick on the client
	 * thread, with the player's location from the previous tick.
	 *
	 * @param ticksSinceModalClose game ticks since a modal interface was closed
	 * @return whether any saved data changed
	 */
	public boolean update(WorldPoint location, int ticksSinceModalClose)
	{
		leaguesWorld = isLeagues(client.getWorldType());
		// Varbits don't get sent when a modal widget is open
		for (WidgetNode node : client.getComponentTable())
		{
			if (node.getModalMode() != WidgetModalMode.NON_MODAL)
			{
				return false;
			}
		}

		boolean changed = false;

		// Saved for the supply calculator: no rake needed when Auto-weed is on (SPEC 11.4)
		final String autoweed = Integer.toString(client.getVarbitValue(VarbitID.FARMING_BLOCKWEEDS));
		if (!autoweed.equals(getConfig(AUTOWEED_KEY)))
		{
			setConfig(AUTOWEED_KEY, autoweed);
			changed = true;
		}

		final Set<Patch> patches = patchesAt(location);
		final boolean newRegionLoaded = !patches.equals(lastPatches);
		lastPatches = patches;

		final long now = Instant.now().getEpochSecond();
		for (Patch patch : patches)
		{
			final int value = client.getVarbitValue(patch.getVarbitId());
			final DecodedPatch current = PatchStateDecoder.decode(patch.getType(), value);
			if (current.getState() == PatchState.UNKNOWN)
			{
				continue;
			}

			lastSeen.put(patch, now);
			final PatchRecord stored = PatchRecord.parse(getConfig(key(patch)));
			if (stored != null && stored.getValue() == value)
			{
				// Unchanged: only refresh the timestamp every few minutes
				if (stored.getObservedAt() + RESAVE_SECONDS > now && now + 30 > stored.getObservedAt())
				{
					continue;
				}
			}
			else if (stored != null)
			{
				final DecodedPatch previous = PatchStateDecoder.decode(patch.getType(), stored.getValue());
				if (PatchPredictor.isPlanting(previous, current))
				{
					setConfig(key(patch) + PLANTED_SUFFIX, Long.toString(now));
					log.debug("Saw {} planted with {}", patch, current.getCrop());
				}
				// Right after arriving or closing an interface, a change may be old news, not a live tick
				if (!newRegionLoaded && ticksSinceModalClose > 1
					&& PatchPredictor.isObservedGrowthTick(patch.getType(), previous, current))
				{
					recordTickOffset(previous.getCrop().getTickMinutes(), now);
				}
			}

			setConfig(key(patch), new PatchRecord(value, now).format());
			changed = true;
		}
		return changed;
	}

	/**
	 * @return the predicted state of this patch now, or null if it has never been seen
	 */
	public PatchPrediction predict(Patch patch)
	{
		PatchPrediction.Source source = PatchPrediction.Source.THIS_PLUGIN;
		PatchRecord record = PatchRecord.parse(getConfig(key(patch)));
		if (record == null)
		{
			record = PatchRecord.parse(configManager.getRSProfileConfiguration(TIME_TRACKING_GROUP,
				patch.getRegionId() + "." + patch.getVarbitId()));
			source = PatchPrediction.Source.TIME_TRACKING;
		}
		if (record == null)
		{
			return null;
		}

		final Long seen = lastSeen.get(patch);
		if (seen != null && seen > record.getObservedAt() && source == PatchPrediction.Source.THIS_PLUGIN)
		{
			record = new PatchRecord(record.getValue(), seen);
		}
		return PatchPredictor.predict(patch, record, plantedAt(patch), source, Instant.now().getEpochSecond(),
			farmingTick(), isLeaguesWorld());
	}

	private void recordTickOffset(int tickMinutes, long now)
	{
		final int offset = FarmingTick.observedOffsetMinutes(tickMinutes, now);
		final Integer precision = parseInt(getConfig(TICK_OFFSET_PRECISION_KEY));
		log.debug("Observed a growth tick on a {} minute crop, offset {}", tickMinutes, offset);
		if (precision == null || tickMinutes >= precision)
		{
			setConfig(TICK_OFFSET_PRECISION_KEY, Integer.toString(tickMinutes));
			setConfig(TICK_OFFSET_KEY, Integer.toString(offset));
		}
	}

	private FarmingTick farmingTick()
	{
		return new FarmingTick(parseInt(getConfig(TICK_OFFSET_KEY)), parseInt(getConfig(TICK_OFFSET_PRECISION_KEY)));
	}

	private long plantedAt(Patch patch)
	{
		final String text = getConfig(key(patch) + PLANTED_SUFFIX);
		try
		{
			return text == null ? 0 : Long.parseLong(text);
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	private static Set<Patch> patchesAt(WorldPoint location)
	{
		final List<Patch> candidates = PATCHES_BY_REGION.get(location.getRegionID());
		if (candidates == null)
		{
			return Collections.emptySet();
		}
		final Set<Patch> patches = EnumSet.noneOf(Patch.class);
		for (Patch patch : candidates)
		{
			if (patch.isInBounds(location))
			{
				patches.add(patch);
			}
		}
		return patches;
	}

	/** Read on the client thread each update, since predict() is also called from the sidebar (Swing). */
	private boolean isLeaguesWorld()
	{
		return leaguesWorld;
	}

	private static boolean isLeagues(Set<WorldType> worldTypes)
	{
		return worldTypes.contains(WorldType.SEASONAL) && !worldTypes.contains(WorldType.DEADMAN);
	}

	private static String key(Patch patch)
	{
		return PATCH_PREFIX + patch.getRegionId() + "." + patch.getVarbitId();
	}

	private String getConfig(String key)
	{
		return configManager.getRSProfileConfiguration(FarmRunAutopilotConfig.GROUP, key);
	}

	private void setConfig(String key, String value)
	{
		configManager.setRSProfileConfiguration(FarmRunAutopilotConfig.GROUP, key, value);
	}

	private static Integer parseInt(String text)
	{
		try
		{
			return text == null ? null : Integer.valueOf(text);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

package com.farmrunautopilot.ui;

import com.farmrunautopilot.access.AccessChecker;
import com.farmrunautopilot.access.AccessSnapshot;
import com.farmrunautopilot.access.PohDetector;
import com.farmrunautopilot.data.Unlock;
import com.farmrunautopilot.data.poh.HousePortal;
import com.farmrunautopilot.data.poh.JewelleryBoxTier;
import com.farmrunautopilot.data.poh.PohAltar;
import com.farmrunautopilot.data.poh.PoolTier;
import com.farmrunautopilot.data.poh.PortalNexus;
import com.farmrunautopilot.settings.AccountSettings;
import com.farmrunautopilot.settings.PohSetup;
import com.farmrunautopilot.settings.RunConfig;
import com.farmrunautopilot.settings.SettingsStore;
import java.awt.Rectangle;
import java.text.DateFormat;
import java.util.ArrayList;
import java.util.Date;
import java.util.List;
import java.util.Set;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.SwingUtilities;
import net.runelite.client.util.LinkBrowser;

/**
 * The Account tab: what you have that the plugin can't read by itself (Sean: Account is what you have): your
 * house, unlocks and where you store things. Display, debug and testing are on the {@link SettingsPage}.
 */
class AccountPage extends SetupPanel
{
	/** The Unlocks section's title, which is also how the Run tab opens it. */
	static final String UNLOCKS = "Unlocks";
	/** The Unlocks section as last drawn, to scroll to it. */
	private JComponent unlocksSectionShown;

	AccountPage(SettingsStore settings, AccessChecker accessChecker, Runnable changed)
	{
		super(settings, accessChecker, changed);
		rebuild();
	}

	@Override
	void addSections(RunConfig config, AccountSettings account, AccessSnapshot access)
	{
		add(pohSection(account));
		unlocksSectionShown = unlocksSection(account);
		add(unlocksSectionShown);
		add(storageSection(config));
	}

	/** Open the Unlocks section and scroll to it (Account page). Swing thread. */
	void revealUnlocks()
	{
		settings.setSectionOpen(UNLOCKS, true);
		rebuild();
		SwingUtilities.invokeLater(() ->
		{
			final JComponent section = unlocksSectionShown;
			if (section != null)
			{
				section.scrollRectToVisible(new Rectangle(0, 0, section.getWidth(), section.getHeight()));
			}
		});
	}

	private JComponent pohSection(AccountSettings account)
	{
		final PohSetup poh = account.getPoh();
		final CollapsibleSection s = section("My house");
		s.addContent(checkBox("Detect furniture when I enter my house (beta)", account.isAutoDetectHouse(), true,
			"Fills in the jewellery box, pool, altar, fairy ring and spirit tree below from your house. Beta: it skips "
				+ "other players' houses by how you got in, which can't be fully checked yet; if it gets your house wrong, "
				+ "please report it.",
			on -> saveAccount(() -> account.setAutoDetectHouse(on), false)));
		if (account.isAutoDetectHouse())
		{
			final JButton report = smallButton("Report a problem");
			report.setToolTipText("Opens the plugin's GitHub issues page");
			report.addActionListener(e -> LinkBrowser.browse(HelpWanted.ISSUES_URL));
			s.addContent(report);
			s.addContent(note(poh.getLastDetected() > 0
				? "Last scanned " + DateFormat.getDateTimeInstance(DateFormat.SHORT, DateFormat.SHORT)
				.format(new Date(poh.getLastDetected() * 1000))
				: "Enter your house to scan it"));
			final JButton rescan = smallButton("Rescan house");
			rescan.setToolTipText("<html>Detection only adds furniture. If you removed or downgraded something, "
				+ "rescan:<br>this clears the detected furniture and your next house visit fills it in again.<br>"
				+ "The portal location and nexus destinations are kept.</html>");
			rescan.addActionListener(e ->
			{
				PohDetector.clearDetected(poh);
				settings.saveAccount(true);
				accessChecker.requestRefresh();
			});
			s.addContent(rescan);
		}
		s.help("Set the portal location and nexus destinations by hand.");

		final List<Choice<HousePortal>> portals = new ArrayList<>();
		portals.add(Choice.of(null, "Unknown / no house"));
		for (HousePortal portal : HousePortal.values())
		{
			portals.add(Choice.of(portal, portal.getDisplayName() + " (" + portal.getConstructionLevel() + " Con)"));
		}
		s.addContent(label("House portal location"));
		s.addContent(combo(portals, poh.getPortal(), p -> saveAccount(() -> poh.setPortal(p), true)));
		s.addContent(checkBox("House set to teleport outside", poh.isTeleportOutside(), true,
			"Teleport to House lands outside the portal instead of inside",
			on -> saveAccount(() -> poh.setTeleportOutside(on), false)));

		final List<Choice<JewelleryBoxTier>> boxes = new ArrayList<>();
		boxes.add(Choice.of(null, "None"));
		for (JewelleryBoxTier tier : JewelleryBoxTier.values())
		{
			boxes.add(Choice.of(tier, title(tier.name()) + " (" + tier.getConstructionLevel() + " Con)"));
		}
		s.addContent(label("Jewellery box"));
		s.addContent(combo(boxes, poh.getJewelleryBox(), b -> saveAccount(() -> poh.setJewelleryBox(b), false)));

		final List<Choice<PoolTier>> pools = new ArrayList<>();
		pools.add(Choice.of(null, "None"));
		for (PoolTier tier : PoolTier.values())
		{
			pools.add(Choice.of(tier, title(tier.name()) + (tier.isRestoresRunEnergy() ? "" : " (no run energy)")));
		}
		s.addContent(label("Pool"));
		s.addContent(combo(pools, poh.getPool(), p -> saveAccount(() -> poh.setPool(p), false)));

		final List<Choice<PohAltar>> altars = new ArrayList<>();
		altars.add(Choice.of(null, "None"));
		for (PohAltar altar : PohAltar.values())
		{
			altars.add(Choice.of(altar, altar.getDisplayName()));
		}
		s.addContent(label("Spellbook altar"));
		s.addContent(combo(altars, poh.getAltar(), a -> saveAccount(() -> poh.setAltar(a), true)));
		s.addContent(checkBox("Fairy ring", poh.isFairyRing(), true, null,
			on -> saveAccount(() -> poh.setFairyRing(on), false)));
		s.addContent(checkBox("Spirit tree", poh.isSpiritTree(), true, null,
			on -> saveAccount(() -> poh.setSpiritTree(on), false)));

		s.addContent(subheader("Portal nexus destinations"));
		for (PortalNexus.Destination destination : PortalNexus.Destination.values())
		{
			s.addContent(checkBox(destination.getDisplayName(), poh.getNexusDestinations().contains(destination), true, null,
				on -> saveAccount(() ->
				{
					if (on)
					{
						poh.getNexusDestinations().add(destination);
					}
					else
					{
						poh.getNexusDestinations().remove(destination);
					}
				}, false)));
		}
		return s;
	}

	private JComponent unlocksSection(AccountSettings account)
	{
		final AccessSnapshot access = accessChecker.getSnapshot();
		final List<Unlock> review = AccessChecker.toReview(settings.editRunConfig(), account);
		final int ticked = account.getManualUnlocks().size();
		final CollapsibleSection s = section(UNLOCKS, ticked == 0 ? null : ticked + " ticked");
		s.help("Ticked for you where the game shows it, or once you pass a planted spirit tree or the Weiss "
			+ "fire. Tick the rest that you have; the plugin can't "
			+ "see them until you do.");
		for (Unlock unlock : Unlock.values())
		{
			if (AccessChecker.isDetected(unlock))
			{
				// Shown in Detected
				continue;
			}
			if (unlock.hasVarbit() && access.getUnlocks().contains(unlock) && !account.getManualUnlocks().contains(unlock))
			{
				s.addContent(checkBox(unlock.getDescription() + " (detected)", true, false,
					"Read from the game", on ->
					{
					}));
				continue;
			}
			final boolean flagged = review.contains(unlock);
			s.addContent(checkBox(unlock.getDescription() + (flagged ? " (check)" : ""),
				account.getManualUnlocks().contains(unlock), true,
				flagged ? "Your run has a patch or a way to one that needs this" : null,
				on -> saveAccount(() ->
				{
					if (on)
					{
						account.getManualUnlocks().add(unlock);
					}
					else
					{
						account.getManualUnlocks().remove(unlock);
					}
				}, true)));
		}
		if (!account.isUnlocksReviewed())
		{
			final JButton done = smallButton("These are right");
			done.setToolTipText("Stop asking on the Run tab; you can still change these any time");
			done.addActionListener(e -> saveAccount(() -> account.setUnlocksReviewed(true), true));
			s.addContent(done);
		}
		return s;
	}

	private JComponent storageSection(RunConfig config)
	{
		final CollapsibleSection s = section("Storage sources");
		s.help("Bank, inventory, equipment and the tool leprechaun are always counted.");
		s.addContent(checkBox("Group storage (GIM)", config.isUseGroupStorage(), true, null,
			on -> saveRun(() -> config.setUseGroupStorage(on))));
		s.addContent(checkBox("Seed vault", config.isUseSeedVault(), true, null,
			on -> saveRun(() -> config.setUseSeedVault(on))));
		return s;
	}

}

package com.farmrunautopilot.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.RenderingHints;
import javax.swing.Icon;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;

/**
 * The sidebar's building block (Sprint 7 facelift, Sean: RuneLite's colours, a modern look): a rounded panel in
 * RuneLite's darker grey, optionally with a coloured bar down its left edge to mark the current or important one.
 */
class Card extends JPanel
{
	/** Corner rounding, in pixels: the one radius everything shares. */
	static final int ARC = Style.ARC;
	/** Width of the accent bar down the left edge. */
	private static final int ACCENT_WIDTH = 3;

	private Color fill = ColorScheme.DARKER_GRAY_COLOR;
	private Color accent;

	Card(LayoutManager layout)
	{
		super(layout);
		setOpaque(false);
		setBorder(new EmptyBorder(4, 7, 4, 7));
	}

	/** The card's background; RuneLite's darker grey unless changed. */
	Card fill(Color fill)
	{
		this.fill = fill;
		repaint();
		return this;
	}

	/** Clickable: one step lighter while the mouse is over it. */
	Card hoverable()
	{
		final Color normal = fill;
		addMouseListener(new java.awt.event.MouseAdapter()
		{
			@Override
			public void mouseEntered(java.awt.event.MouseEvent e)
			{
				fill(ColorScheme.DARK_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(java.awt.event.MouseEvent e)
			{
				fill(normal);
			}
		});
		return this;
	}

	/** A bar down the left edge in this colour (and room for it), or null for none. */
	Card accent(Color accent)
	{
		this.accent = accent;
		setBorder(new EmptyBorder(4, accent != null ? 7 + ACCENT_WIDTH : 7, 4, 7));
		repaint();
		return this;
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		final Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setColor(fill);
		g2.fillRoundRect(0, 0, getWidth(), getHeight(), ARC, ARC);
		if (accent != null)
		{
			// Clipped to the card's rounded shape, so the bar follows its corners
			g2.clip(new java.awt.geom.RoundRectangle2D.Float(0, 0, getWidth(), getHeight(), ARC, ARC));
			g2.setColor(accent);
			g2.fillRect(0, 0, ACCENT_WIDTH, getHeight());
		}
		g2.dispose();
		super.paintComponent(g);
	}

	/**
	 * A group's heading that opens and closes it: a card with a chevron, the title, and a count on the right
	 * (e.g. "3 of 7 due"). Used for the patch timers and the guided tests.
	 */
	static javax.swing.JComponent groupHeader(String title, String summary, boolean open, Runnable toggle)
	{
		final Card head = new Card(new java.awt.BorderLayout(8, 0)).hoverable();
		final javax.swing.JLabel name = new javax.swing.JLabel(title, chevron(open, Color.WHITE),
			javax.swing.JLabel.LEFT);
		name.setIconTextGap(8);
		name.setForeground(Color.WHITE);
		name.setFont(net.runelite.client.ui.FontManager.getRunescapeFont());
		final javax.swing.JLabel count = new javax.swing.JLabel(summary);
		count.setForeground(Color.WHITE);
		count.setFont(net.runelite.client.ui.FontManager.getRunescapeSmallFont());
		head.add(name, java.awt.BorderLayout.CENTER);
		head.add(count, java.awt.BorderLayout.EAST);
		head.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
		head.addMouseListener(new java.awt.event.MouseAdapter()
		{
			@Override
			public void mouseClicked(java.awt.event.MouseEvent e)
			{
				toggle.run();
			}
		});
		// As wide as its parent, as tall as its text at each layout
		final JPanel wrapper = new JPanel(new java.awt.BorderLayout())
		{
			@Override
			public java.awt.Dimension getMaximumSize()
			{
				return new java.awt.Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		wrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrapper.setBorder(new EmptyBorder(0, 0, 3, 0));
		wrapper.add(head, java.awt.BorderLayout.CENTER);
		wrapper.setAlignmentX(LEFT_ALIGNMENT);
		return wrapper;
	}

	/** A small chevron for a collapsible header: pointing right when closed, down when open. */
	static Icon chevron(boolean open, Color color)
	{
		return new Icon()
		{
			@Override
			public void paintIcon(Component c, Graphics g, int x, int y)
			{
				final Graphics2D g2 = (Graphics2D) g.create();
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g2.setColor(color);
				g2.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				final int cx = x + 5;
				final int cy = y + 5;
				if (open)
				{
					g2.drawPolyline(new int[]{cx - 4, cx, cx + 4}, new int[]{cy - 2, cy + 2, cy - 2}, 3);
				}
				else
				{
					g2.drawPolyline(new int[]{cx - 2, cx + 2, cx - 2}, new int[]{cy - 4, cy, cy + 4}, 3);
				}
				g2.dispose();
			}

			@Override
			public int getIconWidth()
			{
				return 10;
			}

			@Override
			public int getIconHeight()
			{
				return 10;
			}
		};
	}
}

package com.farmrunautopilot.ui;

import lombok.Value;

/**
 * One dropdown entry. Disabled entries are shown greyed with a tooltip and can't be picked.
 */
@Value
class Choice<T>
{
	/** May be null, e.g. for "Auto" or "None". */
	T value;
	String label;
	boolean enabled;
	String tooltip;

	static <T> Choice<T> of(T value, String label)
	{
		return new Choice<>(value, label, true, null);
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.farmrunautopilot.ui;

import java.awt.BorderLayout;
import java.awt.Cursor;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;

/**
 * A titled section whose content can be shown or hidden by clicking the title.
 */
class CollapsibleSection extends JPanel
{
	/** The clickable title bar: a rounded card with a chevron (Sprint 7 facelift). */
	private final Card headCard = new Card(new BorderLayout()).hoverable();
	private final JLabel header = new JLabel();
	private final JPanel content = new JPanel();
	private final String title;
	/** What's set inside, shown after the title so a closed section still says it, e.g. "18 of 24"; or null. */
	private final String summary;
	private boolean expanded;
	/** What the section is for, shown on hovering its title (Sprint 7: explanations out of the way); or null. */
	private String help;

	/**
	 * @param onToggle told the new expanded state, so it can be remembered across rebuilds
	 */
	CollapsibleSection(String title, boolean expanded, Consumer<Boolean> onToggle)
	{
		this(title, null, expanded, onToggle);
	}

	CollapsibleSection(String title, String summary, boolean expanded, Consumer<Boolean> onToggle)
	{
		this.title = title;
		this.summary = summary;
		setLayout(new BorderLayout());
		setAlignmentX(LEFT_ALIGNMENT);
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(new EmptyBorder(0, 0, 3, 0));

		Style.title(header);
		header.setIconTextGap(8);
		headCard.add(header, BorderLayout.CENTER);
		headCard.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		headCard.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				setExpanded(!CollapsibleSection.this.expanded);
				onToggle.accept(CollapsibleSection.this.expanded);
			}
		});

		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.setBorder(new EmptyBorder(3, 2, 1, 2));

		add(headCard, BorderLayout.NORTH);
		add(content, BorderLayout.CENTER);
		setExpanded(expanded);
	}

	/** Explain the section on hovering its title, marked with a faint "(?)", instead of a note inside it. */
	CollapsibleSection help(String text)
	{
		help = text;
		// On the card only: a tooltip on the label would take its clicks
		headCard.setToolTipText(UiText.tooltip(text, 250));
		setExpanded(expanded);
		return this;
	}

	void addContent(JComponent component)
	{
		component.setAlignmentX(LEFT_ALIGNMENT);
		content.add(component);
	}

	private void setExpanded(boolean expanded)
	{
		this.expanded = expanded;
		final String text = UiText.escape(title)
			+ (help != null ? " <font color='#6f6f6f'>(?)</font>" : "");
		header.setText(summary == null ? "<html>" + text + "</html>"
			: "<html>" + text + " <font color='#ffffff'>" + UiText.escape(summary) + "</font></html>");
		header.setIcon(Card.chevron(expanded, ColorScheme.LIGHT_GRAY_COLOR));
		content.setVisible(expanded);
		revalidate();
	}
}

package com.farmrunautopilot.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * One line, e.g. "Taverley" and "Falador Teleport", that opens to show its controls when clicked (Sean: one line
 * per location, the full way on hover and when opened). A yellow bar down its edge marks a row changed from the
 * default.
 */
class ExpandableRow extends JPanel
{
	private static final Color OVERRIDE = new Color(0xE8, 0xC5, 0x3A);

	private final JPanel content = new JPanel();
	private final JLabel name = new JLabel();
	/** The clickable line: a rounded card with a chevron (Sprint 7 facelift). */
	private final Card headCard = new Card(new BorderLayout(8, 0)).hoverable();
	private boolean expanded;

	/**
	 * @param name e.g. "Taverley"
	 * @param shortSummary what it's set to, short enough to share the line, e.g. "Falador Teleport"
	 * @param fullSummary the whole of it, for the tooltip
	 * @param expanded open to start with
	 * @param onToggle told the new state, so it can be kept across redraws
	 */
	ExpandableRow(String name, String shortSummary, String fullSummary, boolean overridden, int width,
		boolean expanded, Consumer<Boolean> onToggle)
	{
		setLayout(new BorderLayout());
		setAlignmentX(LEFT_ALIGNMENT);
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(new EmptyBorder(0, 0, 3, 0));

		headCard.accent(overridden ? OVERRIDE : null);
		// The name gets whatever the value on the right leaves (Sean: a long value squeezed it into a column)
		final JLabel measure = new JLabel(shortSummary);
		measure.setFont(FontManager.getRunescapeSmallFont());
		final int valueWidth = Math.min(measure.getPreferredSize().width, width / 2);
		this.name.setText(UiText.wrap(name, width - valueWidth - 40));
		this.name.setIconTextGap(6);
		this.name.setFont(FontManager.getRunescapeSmallFont());
		this.name.setForeground(Color.WHITE);
		// Only as wide as it needs (Sean: "Not yet" took half the line and cut the name to "Spellbook Swa")
		final JLabel summary = new JLabel(measure.getPreferredSize().width <= width / 2
			? shortSummary : UiText.wrap(shortSummary, width / 2));
		summary.setFont(FontManager.getRunescapeSmallFont());
		summary.setForeground(Color.WHITE);
		headCard.add(this.name, BorderLayout.CENTER);
		headCard.add(summary, BorderLayout.EAST);
		headCard.setToolTipText(UiText.tooltip(name + ": " + fullSummary
			+ (overridden ? " (changed from Auto)" : ""), 250));
		headCard.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		headCard.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				setExpanded(!ExpandableRow.this.expanded);
				onToggle.accept(ExpandableRow.this.expanded);
			}
		});

		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.setBorder(new EmptyBorder(2, 4, 2, 0));

		add(headCard, BorderLayout.NORTH);
		add(content, BorderLayout.CENTER);
		setExpanded(expanded);
	}

	void addContent(JComponent component)
	{
		component.setAlignmentX(LEFT_ALIGNMENT);
		content.add(component);
	}

	private void setExpanded(boolean expanded)
	{
		this.expanded = expanded;
		name.setIcon(Card.chevron(expanded, Color.WHITE));
		content.setVisible(expanded);
		revalidate();
	}
}

package com.farmrunautopilot.ui;

import com.farmrunautopilot.access.AccessChecker;
import com.farmrunautopilot.access.AccessSnapshot;
import com.farmrunautopilot.data.Crop;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.PatchType;
import com.farmrunautopilot.data.Requirement;
import com.farmrunautopilot.settings.AccountSettings;
import com.farmrunautopilot.settings.Compost;
import com.farmrunautopilot.settings.Outfit;
import com.farmrunautopilot.settings.Protection;
import com.farmrunautopilot.settings.RunConfig;
import com.farmrunautopilot.settings.SettingsStore;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.JComponent;
import net.runelite.api.Skill;
import net.runelite.client.ui.ColorScheme;

/**
 * The Farm tab: which patches, what to plant, protection, compost and extras to bring.
 */
class FarmPage extends SetupPanel
{
	FarmPage(SettingsStore settings, AccessChecker accessChecker, Runnable changed)
	{
		super(settings, accessChecker, changed);
		rebuild();
	}

	@Override
	void addSections(RunConfig config, AccountSettings account, AccessSnapshot access)
	{
		add(patchesSection(config, access));
		add(cropsSection(config, access));
		add(diseaseFreeSection(config, access));
		add(protectionSection(config));
		add(compostSection(config));
		add(extrasSection(config));
		add(advancedFarmSection(config));
	}

	private JComponent patchesSection(RunConfig config, AccessSnapshot access)
	{
		int usable = 0;
		int ticked = 0;
		for (Patch patch : Patch.values())
		{
			if (access.missingFor(patch).isEmpty())
			{
				usable++;
				ticked += config.getDisabledPatches().contains(patch) ? 0 : 1;
			}
		}
		final CollapsibleSection s = section("Patches", ticked + " of " + usable + " ticked");
		s.help("Untick patches you don't want in your runs; locked ones show what they need on hover. Choose trees, "
			+ "fruit trees and herbs at the top of the Run tab: each joins a run once its patches are due.");
		// One group per type that opens and closes, two tick boxes to a row (Sean)
		for (PatchType type : PatchType.values())
		{
			final List<JComponent> boxes = new ArrayList<>();
			int typeUsable = 0;
			int typeTicked = 0;
			for (Patch patch : Patch.values())
			{
				if (patch.getType() != type)
				{
					continue;
				}
				final List<Requirement> missing = access.missingFor(patch);
				final boolean locked = !missing.isEmpty();
				final boolean on = !locked && !config.getDisabledPatches().contains(patch);
				typeUsable += locked ? 0 : 1;
				typeTicked += on ? 1 : 0;
				// Locked ones are greyed, with what they need on hover
				boxes.add(halfCheckBox(patch.getLocation().getDisplayName(), on, !locked,
					locked ? "Locked: " + AccessSnapshot.describe(missing) : null,
					tick -> saveRun(() ->
					{
						if (tick)
						{
							config.getDisabledPatches().remove(patch);
						}
						else
						{
							config.getDisabledPatches().add(patch);
						}
					})));
			}
			final CollapsibleSection group = section(type.getDisplayName() + " patches",
				typeTicked + " of " + typeUsable);
			group.addContent(twoPerRow(boxes));
			s.addContent(group);
		}
		return s;
	}

	private JComponent cropsSection(RunConfig config, AccessSnapshot access)
	{
		final CollapsibleSection s = section("Crops");
		final int farming = access.isKnown() ? access.level(Skill.FARMING) : 99;
		s.addContent(checkBox("Use backup choices if I run out", config.isUseBackupCrops(), true,
			"Plant your 2nd, then 3rd choice once you run out of your 1st. Disease-free and protected patches get "
				+ "the best crops first.",
			on ->
			{
				saveRun(() -> config.setUseBackupCrops(on));
				rebuild();
			}));

		// One line per choice (Sean): "1st [drop-down]"; the 3rd only once the 2nd is set
		for (PatchType type : PatchType.values())
		{
			s.addContent(subheader(type.getDisplayName()));
			final Crop firstCrop = config.cropFor(type, farming);
			final JComponent first = combo(cropChoices(type, farming, false, Collections.emptyList()), firstCrop,
				crop ->
				{
					saveRun(() ->
					{
						config.getCrops().put(type, crop);
						// A crop can only be one of the choices: drop it from the backups
						config.getBackupCrops().getOrDefault(type, new ArrayList<>()).remove(crop);
					});
					rebuild();
				});
			if (!config.isUseBackupCrops())
			{
				s.addContent(first);
				continue;
			}
			s.addContent(labeled("1st", first));

			final List<Crop> backups = config.getBackupCrops().getOrDefault(type, new ArrayList<>());
			for (int i = 0; i < RunConfig.MAX_BACKUP_CROPS && i <= backups.size(); i++)
			{
				final int index = i;
				// Each list leaves out the choices above it (Sean)
				final List<Crop> above = new ArrayList<>(backups.subList(0, Math.min(index, backups.size())));
				above.add(firstCrop);
				s.addContent(labeled(i == 0 ? "2nd" : "3rd", combo(cropChoices(type, farming, true, above),
					index < backups.size() ? backups.get(index) : null,
					crop ->
					{
						saveRun(() -> setBackup(config, type, index, crop));
						// Setting or clearing one choice shows or hides the next
						rebuild();
					})));
			}
		}

		return s;
	}

	/** Which herbs go in the patches that never get diseased. */
	private JComponent diseaseFreeSection(RunConfig config, AccessSnapshot access)
	{
		final CollapsibleSection s = section("Disease-free herbs",
			config.isPrioritiseDiseaseFreeHerbs() ? config.getDiseaseFreeHerbs().size() + " picked" : "off");
		final int farming = access.isKnown() ? access.level(Skill.FARMING) : 99;
		s.addContent(checkBox("Prioritise herbs for disease-free patches", config.isPrioritiseDiseaseFreeHerbs(), true,
			"Pick herbs that only go in disease-free patches",
			on ->
			{
				saveRun(() -> config.setPrioritiseDiseaseFreeHerbs(on));
				rebuild();
			}));
		if (!config.isPrioritiseDiseaseFreeHerbs())
		{
			return s;
		}
		s.help("Troll Stronghold, Weiss and Harmony Island, plus Hosidius and Civitas once their "
			+ "unlock is done. They get these herbs first, most valuable first (by GE price); other patches never do.");
		for (Crop crop : Crop.values())
		{
			if (crop.getType() != PatchType.HERB)
			{
				continue;
			}
			final boolean canPlant = crop.getFarmingLevel() <= farming;
			s.addContent(checkBox(crop.getDisplayName() + " (" + crop.getFarmingLevel() + ")",
				config.getDiseaseFreeHerbs().contains(crop), canPlant,
				canPlant ? null : "Needs " + crop.getFarmingLevel() + " Farming",
				on -> saveRun(() ->
				{
					if (on)
					{
						config.getDiseaseFreeHerbs().add(crop);
					}
					else
					{
						config.getDiseaseFreeHerbs().remove(crop);
					}
				})));
		}
		return s;
	}

	/** @param taken crops already chosen above, left out of this list */
	private static List<Choice<Crop>> cropChoices(PatchType type, int farming, boolean allowNone,
		List<Crop> taken)
	{
		final List<Choice<Crop>> choices = new ArrayList<>();
		if (allowNone)
		{
			choices.add(Choice.of(null, "None"));
		}
		for (Crop crop : Crop.values())
		{
			if (crop.getType() == type && !taken.contains(crop))
			{
				final boolean canPlant = crop.getFarmingLevel() <= farming;
				choices.add(new Choice<>(crop, crop.getDisplayName() + " (" + crop.getFarmingLevel() + ")", canPlant,
					canPlant ? null : "Needs " + crop.getFarmingLevel() + " Farming"));
			}
		}
		return choices;
	}

	/** Sets the 2nd (index 0) or 3rd (index 1) choice; "None" clears it and anything after it. */
	private static void setBackup(RunConfig config, PatchType type, int index, Crop crop)
	{
		final List<Crop> backups = new ArrayList<>(config.getBackupCrops().getOrDefault(type, new ArrayList<>()));
		while (backups.size() > index)
		{
			backups.remove(backups.size() - 1);
		}
		if (crop != null)
		{
			backups.add(crop);
		}
		config.getBackupCrops().put(type, backups);
	}

	/** Paying the gardener to protect trees and fruit trees. */
	private JComponent protectionSection(RunConfig config)
	{
		final CollapsibleSection s = section("Protection", overrides(config.getProtectionOverrides().size()));
		s.addContent(checkBox("Bring gardener payments noted", config.isPayWithNotes(), true,
			"Gardeners accept noted payment; one inventory slot per item type",
			on -> saveRun(() -> config.setPayWithNotes(on))));

		for (PatchType type : PatchType.values())
		{
			if (!type.isProtectable())
			{
				continue;
			}
			s.addContent(subheader(type.getDisplayName() + " patches"));
			s.addContent(combo(enumChoices(Protection.values()), config.getProtection().get(type),
				p -> saveRun(() -> config.getProtection().put(type, p))));
			s.addContent(checkBox("Pay 200 coins to clear grown " + type.getDisplayName().toLowerCase() + "s",
				config.getPayToClear().contains(type), true,
				"The gardener removes the old tree, so no axe is needed",
				on -> saveRun(() ->
				{
					if (on)
					{
						config.getPayToClear().add(type);
					}
					else
					{
						config.getPayToClear().remove(type);
					}
				})));
		}
		return s;
	}

	/** Compost for each patch type, and what to do about disease. */
	private JComponent compostSection(RunConfig config)
	{
		final CollapsibleSection s = section("Compost and cures");
		for (PatchType type : PatchType.values())
		{
			s.addContent(label(type.getDisplayName() + " patches"));
			s.addContent(combo(enumChoices(Compost.values()), config.getCompost().get(type),
				c -> saveRun(() -> config.getCompost().put(type, c))));
		}
		s.addContent(subheader("Disease"));
		s.addContent(checkBox("Use Cure Plant (Lunar)", config.isUseCurePlant(), true, null,
			on -> saveRun(() -> config.setUseCurePlant(on))));
		s.addContent(spinnerRow("Plant cures to bring (backup)", spinner(config.getPlantCureDoses(), 0, 40, 1,
			v -> saveRunQuietly(() -> config.setPlantCureDoses(v)))));
		return s;
	}

	/** Settings most players never need to change. */
	private JComponent advancedFarmSection(RunConfig config)
	{
		final boolean perPatch = config.isUsingProtectionOverrides();
		final CollapsibleSection s = section("Advanced",
			perPatch ? overrides(config.getProtectionOverrides().size()) : null);
		s.addContent(spinnerRow("Include a run type when this % of its patches are due",
			spinner(config.getDueThresholdPercent(), 1, 100, 5,
				v -> saveRunQuietly(() -> config.setDueThresholdPercent(v)))));

		// Rarely used, so behind a tick box (Sean); ticking it off keeps the choices but ignores them
		s.addContent(checkBox("Different protection for single patches", perPatch, true,
			"Choose another protection for a patch than its type has in Protection. Ticking this off keeps your "
				+ "choices but ignores them.",
			on ->
			{
				saveRun(() -> config.setUseProtectionOverrides(on));
				rebuild();
			}));
		if (!perPatch)
		{
			return s;
		}
		// Only the patches that differ, then a way to add another
		final List<Choice<Protection>> choices = new ArrayList<>();
		choices.add(Choice.of(null, "Same as its type"));
		choices.addAll(enumChoices(Protection.values()));
		final List<Choice<Patch>> addable = new ArrayList<>();
		addable.add(Choice.of(null, "Add a patch..."));
		for (Patch patch : Patch.values())
		{
			if (!patch.getType().isProtectable())
			{
				continue;
			}
			final Protection override = config.getProtectionOverrides().get(patch);
			if (override == null)
			{
				addable.add(Choice.of(patch, patch.getDisplayName()));
				continue;
			}
			s.addContent(label(patch.getDisplayName()));
			s.addContent(combo(choices, override, p ->
			{
				saveRun(() ->
				{
					if (p == null)
					{
						config.getProtectionOverrides().remove(patch);
					}
					else
					{
						config.getProtectionOverrides().put(patch, p);
					}
				});
				rebuild();
			}));
		}
		if (addable.size() > 1)
		{
			s.addContent(combo(addable, null, patch ->
			{
				if (patch == null)
				{
					return;
				}
				// Starts as the other choice from its type's, so adding it changes something
				final Protection type = config.getProtection().get(patch.getType());
				saveRun(() -> config.getProtectionOverrides().put(patch,
					type == Protection.PAY_GARDENER ? Protection.COMPOST_ONLY : Protection.PAY_GARDENER));
				rebuild();
			}));
		}
		return s;
	}

	/** Optional things to bring that help but aren't needed. */
	private JComponent extrasSection(RunConfig config)
	{
		final CollapsibleSection s = section("Extras to bring");
		s.addContent(label("Outfit"));
		s.addContent(combo(enumChoices(Outfit.values()), config.getOutfit(), o -> saveRun(() -> config.setOutfit(o))));
		s.addContent(checkBox("Suggest yield boosts", config.isRecommendEquipmentBoosts(), true,
			"Magic secateurs (+10% herb yield) as an optional item; worn when nothing else needs the weapon slot",
			on -> saveRun(() -> config.setRecommendEquipmentBoosts(on))));
		return s;
	}

}

package com.farmrunautopilot.ui;

import com.farmrunautopilot.FarmRunAutopilotConfig;
import com.farmrunautopilot.access.AccessChecker;
import com.farmrunautopilot.settings.SettingsStore;
import com.farmrunautopilot.route.RunOverrides;
import com.farmrunautopilot.route.RunPlan;
import com.farmrunautopilot.route.RunService;
import com.farmrunautopilot.run.RunSession;
import com.farmrunautopilot.run.RunTimings;
import com.farmrunautopilot.run.RunView;
import com.farmrunautopilot.supply.HoldingsTracker;
import com.farmrunautopilot.testing.TestRunner;
import com.farmrunautopilot.testing.TestView;
import com.farmrunautopilot.tracking.PatchTracker;
import java.awt.BorderLayout;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.colorpicker.ColorPickerManager;

/**
 * Sidebar root: Run, Farm, Travel and Account tabs (SPEC section 13, docs/BRANDING.md).
 */
public class FarmRunAutopilotPanel extends PluginPanel
{
	/** Countdowns are shown to the minute, so a 10 second refresh is plenty. */
	private static final int REFRESH_MILLIS = 10_000;

	private final RunPanel runPanel;
	private final PresetsPage presetsPanel;
	private final FarmPage farmPanel;
	private final TravelPage travelPanel;
	private final AccountPage accountPanel;
	private final SettingsPage settingsPanel;
	/** Built after the Run tab, which can switch to the Account tab. */
	private TabBar tabs;
	private final RunSession runSession;
	private final Timer refreshTimer;
	private final SettingsStore settings;
	private final TestRunner testRunner;
	/** The "I NEED YOUR HELP!" button at the bottom of each tab, whose count changes as tests are run. */
	private final List<JButton> helpButtons = new ArrayList<>();

	@Inject
	public FarmRunAutopilotPanel(SettingsStore settings, AccessChecker accessChecker, PatchTracker patchTracker,
		RunOverrides runOverrides, RunService runService, RunSession runSession, ClientThread clientThread,
		FarmRunAutopilotConfig config, ConfigManager configManager,
		ColorPickerManager colorPickers, HoldingsTracker holdingsTracker, RunTimings timings,
		TestRunner testRunner)
	{
		this.runSession = runSession;
		this.settings = settings;
		this.testRunner = testRunner;
		setLayout(new BorderLayout());
		setBorder(new EmptyBorder(6, 6, 6, 6));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		final JPanel display = new JPanel(new BorderLayout());
		display.setBackground(ColorScheme.DARK_GRAY_COLOR);

		runPanel = new RunPanel(settings, runOverrides, runService::markDirty, this::rebuildSetup,
			patchTracker, accessChecker,
			new RunPanel.RunControls()
			{
				@Override
				public RunView view()
				{
					return runSession.getView();
				}

				@Override
				public void build()
				{
					clientThread.invoke(runSession::build);
				}

				@Override
				public void cancel()
				{
					clientThread.invoke(runSession::cancel);
				}

				@Override
				public void startNow()
				{
					clientThread.invoke(runSession::startNow);
				}

				@Override
				public void stop()
				{
					clientThread.invoke(() -> runSession.stop(false));
				}

				@Override
				public void setStepTicked(int step, boolean ticked)
				{
					clientThread.invoke(() -> runSession.setStepTicked(step, ticked));
				}

				@Override
				public void setRowTicked(int row, boolean ticked)
				{
					clientThread.invoke(() -> runSession.setRowTicked(row, ticked));
				}

				@Override
				public void openUnlocks()
				{
					accountPanel.revealUnlocks();
					tabs.select("Account");
				}

				@Override
				public void openPresets()
				{
					settingsPanel.revealPresets();
					tabs.select("Settings");
				}

				@Override
				public boolean seedVaultSeen()
				{
					return holdingsTracker.hasSeenSeedVault();
				}

				@Override
				public TestView testView()
				{
					return testRunner.getView();
				}

				@Override
				public void answerTest(boolean yes)
				{
					testRunner.answer(yes);
				}

				@Override
				public void skipTestStep()
				{
					testRunner.skip();
				}

				@Override
				public void cancelTest()
				{
					testRunner.cancel();
				}

				@Override
				public void openTestReport()
				{
					testRunner.openReport();
				}

				@Override
				public void closeTestReport()
				{
					testRunner.closeReport();
					runPanel.refresh();
				}
			});
		// Presets cover Farm and Travel, so they're managed under the Run tab's preset picker
		presetsPanel = new PresetsPage(settings, accessChecker, this::rebuildSetup);
		final JPanel runStack = new JPanel();
		runStack.setLayout(new BoxLayout(runStack, BoxLayout.Y_AXIS));
		runStack.setBackground(ColorScheme.DARK_GRAY_COLOR);
		runPanel.setAlignmentX(LEFT_ALIGNMENT);
		runStack.add(runPanel);
		runStack.add(helpButton());
		final JPanel run = new JPanel(new BorderLayout());
		run.setBackground(ColorScheme.DARK_GRAY_COLOR);
		run.add(runStack, BorderLayout.NORTH);

		farmPanel = new FarmPage(settings, accessChecker, this::rebuildSetup);
		travelPanel = new TravelPage(settings, accessChecker, this::rebuildSetup);
		final GuidanceSettings guidance = new GuidanceSettings(config, configManager, colorPickers);
		accountPanel = new AccountPage(settings, accessChecker, this::rebuildSetup);
		settingsPanel = new SettingsPage(settings, accessChecker, patchTracker, this::rebuildSetup, guidance,
			presetsPanel);
		final Runnable resetRunSettings = () ->
		{
			settings.resetRunConfig();
			guidance.resetDefaults();
		};
		settingsPanel.setResetActions(resetRunSettings, () ->
		{
			resetRunSettings.run();
			settings.resetAccountAndPresets();
			timings.clear();
		});
		settingsPanel.showHelpList(testRunner, () -> tabs.select("Run"));
		settingsPanel.showRunTimes(timings::learned);
		settingsPanel.showHoldings(holdingsTracker::getHoldings);
		travelPanel.showHoldings(holdingsTracker::getHoldings);
		travelPanel.showAutoPicks(runService);

		tabs = new TabBar(display);
		tabs.setBorder(new EmptyBorder(0, 0, 6, 0));
		tabs.addTab("Run", TabIcon.RUN, run);
		tabs.addTab("Farm", TabIcon.FARM, top(farmPanel, helpButton()));
		tabs.addTab("Travel", TabIcon.TRAVEL, top(travelPanel, helpButton()));
		tabs.addTab("Account", TabIcon.ACCOUNT, top(accountPanel, helpButton()));
		// No help link here: the list itself is the last section
		tabs.addTab("Settings", TabIcon.SETTINGS, top(settingsPanel, null));

		add(tabs, BorderLayout.NORTH);
		add(display, BorderLayout.CENTER);

		refreshTimer = new Timer(REFRESH_MILLIS, e -> refreshPatches());
		refreshTimer.start();
	}

	/** Re-reads patch predictions. Call on the Swing thread. */
	public void refreshPatches()
	{
		settingsPanel.refreshPatches();
		runPanel.refreshPatches();
	}

	/** What the plugin has detected changed (charges, the leprechaun, the bucket). Call on the Swing thread. */
	public void refreshDetected()
	{
		settingsPanel.refreshDetected();
	}

	/** Shows a new supply plan in the Run tab. Call on the Swing thread. */
	public void updateRun(RunPlan plan, boolean loggedIn)
	{
		runPanel.update(plan, loggedIn);
		// The supply plan is redone when holdings change, so the Detected lines may have too
		settingsPanel.refreshDetected();
		travelPanel.refreshAutoPicks();
	}

	/** Rebuilds the settings tabs from saved settings and account access. Call on the Swing thread. */
	public void rebuildSetup()
	{
		farmPanel.rebuild();
		travelPanel.rebuild();
		accountPanel.rebuild();
		settingsPanel.rebuild();
		presetsPanel.rebuild();
		// The Run tab shows the run types and preset from the same settings
		runPanel.refresh();
		for (JButton button : helpButtons)
		{
			HelpWanted.refresh(button, settings, testRunner.asDeveloper());
		}
	}

	private JButton helpButton()
	{
		final JButton button = HelpWanted.button(settings, testRunner.asDeveloper(), this::openHelp);
		helpButtons.add(button);
		return button;
	}

	/** Settings > Help improve this plugin, scrolled to the help list. */
	private void openHelp()
	{
		settingsPanel.revealHelpList();
		tabs.select("Settings");
	}

	/** Pins a page, with its help section under it, to the top of its tab instead of stretching it. */
	private static JPanel top(JPanel page, JComponent help)
	{
		final JPanel stack = new JPanel();
		stack.setLayout(new BoxLayout(stack, BoxLayout.Y_AXIS));
		stack.setBackground(ColorScheme.DARK_GRAY_COLOR);
		page.setAlignmentX(LEFT_ALIGNMENT);
		stack.add(page);
		if (help != null)
		{
			help.setAlignmentX(LEFT_ALIGNMENT);
			stack.add(help);
		}
		final JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrapper.add(stack, BorderLayout.NORTH);
		return wrapper;
	}

	public void shutDown()
	{
		refreshTimer.stop();
		runPanel.shutDown();
	}
}

package com.farmrunautopilot.ui;

import com.farmrunautopilot.FarmRunAutopilotConfig;
import java.awt.Color;
import java.awt.Component;
import java.util.function.Consumer;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.components.colorpicker.ColorPickerManager;
import net.runelite.client.ui.components.colorpicker.RuneliteColorPicker;

/**
 * Reads and writes the run guidance settings (highlights and colours) for the Account tab. They're RuneLite
 * config items, global for the client, so changes reach the overlays straight away.
 */
final class GuidanceSettings
{
	private final FarmRunAutopilotConfig config;
	private final ConfigManager configManager;
	private final ColorPickerManager colorPickers;

	GuidanceSettings(FarmRunAutopilotConfig config, ConfigManager configManager, ColorPickerManager colorPickers)
	{
		this.config = config;
		this.configManager = configManager;
		this.colorPickers = colorPickers;
	}

	FarmRunAutopilotConfig get()
	{
		return config;
	}

	void set(String key, Object value)
	{
		configManager.setConfiguration(FarmRunAutopilotConfig.GROUP, key, value);
	}

	/** Highlights and colours back to their defaults. */
	void resetDefaults()
	{
		for (String key : new String[]{"highlightPatch", "hintArrow", "highlightGardener", "highlightItems",
			"highlightSpell", "shortestPathLines", "patchColour", "npcColour", "itemColour"})
		{
			configManager.unsetConfiguration(FarmRunAutopilotConfig.GROUP, key);
		}
	}

	/** Opens RuneLite's colour picker; each change is saved as it's made. */
	void pickColour(Component parent, String title, Color current, String key, Consumer<Color> onChange)
	{
		final RuneliteColorPicker picker = colorPickers.create(parent, current, title, false);
		picker.setLocationRelativeTo(parent);
		picker.setOnColorChange(colour ->
		{
			set(key, colour);
			onChange.accept(colour);
		});
		picker.setVisible(true);
	}
}

package com.farmrunautopilot.ui;

import com.farmrunautopilot.settings.SettingsStore;
import com.farmrunautopilot.testing.TestItem;
import com.farmrunautopilot.testing.TestRunner;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.LinkBrowser;

/**
 * "I NEED YOUR HELP!": features that couldn't be tried in development (no account with the item or unlock, or
 * a game value not checked yet), what to try, and a guided test for each. A button at the bottom of every tab
 * opens the list in Settings > Help improve this plugin. Remove an item once it's confirmed (see CLAUDE.md).
 */
final class HelpWanted
{
	static final String ISSUES_URL = "https://github.com/elzerma/farm-run-autopilot/issues";
	private static final int TEXT_WIDTH = 184;
	/** Tests opened to show their steps, kept while the page redraws. */
	private static final java.util.Set<TestItem> OPEN_ROWS = java.util.EnumSet.noneOf(TestItem.class);

	private HelpWanted()
	{
	}

	/** This client has already run the item's test (for its current revision), pass or not. */
	static boolean isDone(SettingsStore settings, TestItem item)
	{
		return settings.getClientValue(item.key()) != null;
	}

	/** How many tests this client hasn't run yet. */
	static int toTry(SettingsStore settings)
	{
		int count = 0;
		for (TestItem item : TestItem.values())
		{
			count += isDone(settings, item) ? 0 : 1;
		}
		return count;
	}

	/**
	 * The small line at the bottom of every tab, which opens the list in Settings > Help improve this plugin (Sean: a quiet
	 * link rather than a big button).
	 */
	static JButton button(SettingsStore settings, boolean developer, Runnable open)
	{
		final JButton button = new JButton();
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setForeground(Color.WHITE);
		button.setFocusPainted(false);
		button.setBorderPainted(false);
		button.setContentAreaFilled(false);
		button.setBorder(new javax.swing.border.EmptyBorder(4, 0, 4, 0));
		button.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
		button.setAlignmentX(Component.LEFT_ALIGNMENT);
		button.addActionListener(e -> open.run());
		refresh(button, settings, developer);
		return button;
	}

	/** Update the count; players who have run every test don't see the button at all. */
	static void refresh(JButton button, SettingsStore settings, boolean developer)
	{
		final int count = toTry(settings);
		// Says it's easy (Sean: no coding or heavy lifting, just run a couple of scenarios)
		button.setText("<html><body style='width:146px'>Help improve this plugin: try a few quick things in game, "
			+ "no coding needed. <u>Show me</u></body></html>");
		button.setToolTipText(count == 0 ? "Every test is done" : count + (count == 1 ? " feature" : " features")
			+ " I couldn't test, with steps to try them");
		button.setVisible(count > 0 || developer);
	}

	/**
	 * The guided tests for Settings > Help improve this plugin, in the sidebar's style (Sprint 7): a group per tab
	 * that opens and closes, one line per test ("Start", or what it still needs), its steps and Start button when
	 * opened, the tests already run in a closed Done group, and a small link to the issues page. The explanation
	 * above it is the Settings page's. In the dev client a finished test's result goes to the clipboard; for
	 * players it opens a GitHub issue.
	 */
	static JPanel list(SettingsStore settings, boolean developer, TestRunner runner, Runnable showRun,
		Runnable redraw)
	{
		final JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		if (toTry(settings) == 0)
		{
			add(panel, text("You've run every test. Thank you!", ColorScheme.PROGRESS_COMPLETE_COLOR, 4));
		}
		for (TestItem.Tab tab : TestItem.Tab.values())
		{
			final List<TestItem> items = new ArrayList<>();
			for (TestItem item : TestItem.values())
			{
				if (item.getTab() == tab && !isDone(settings, item))
				{
					items.add(item);
				}
			}
			if (items.isEmpty())
			{
				continue;
			}
			final String key = "Guided tests: " + tab.name();
			final boolean open = settings.isSectionOpen(key);
			add(panel, Card.groupHeader(tab.getLabel() + " tab", items.size() + " to try", open, () ->
			{
				settings.setSectionOpen(key, !open);
				redraw.run();
			}));
			if (open)
			{
				for (TestItem item : items)
				{
					add(panel, testRow(item, runner, showRun, "Start test"));
				}
			}
		}
		addDone(panel, settings, developer, runner, showRun, redraw);
		final JLabel issues = text("See every report on GitHub", Color.WHITE, 0);
		issues.setText("<html><u>See every report on GitHub</u></html>");
		issues.setBorder(new EmptyBorder(4, 0, 2, 0));
		issues.setToolTipText(ISSUES_URL);
		issues.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		issues.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				LinkBrowser.browse(ISSUES_URL);
			}
		});
		add(panel, issues);
		return panel;
	}

	private static void add(JPanel panel, JComponent component)
	{
		component.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.add(component);
	}

	/**
	 * One test on one line: its name, and "Start" or the first thing it still needs (said only here); the steps
	 * on hover, and with the Start button when opened.
	 */
	private static JComponent testRow(TestItem item, TestRunner runner, Runnable showRun, String startLabel)
	{
		final List<String> missing = runner.missing(item);
		final ExpandableRow row = new ExpandableRow(item.getTitle(),
			// Short on the line (Sean: the whole need wrapped into a tall column); what's needed is inside
			missing.isEmpty() ? "Ready" : "Not yet",
			item.getHowToTry() + (missing.isEmpty() ? "" : " Needs: " + String.join("; ", missing) + "."),
			false, TEXT_WIDTH + 40, OPEN_ROWS.contains(item), open ->
			{
				if (open)
				{
					OPEN_ROWS.add(item);
				}
				else
				{
					OPEN_ROWS.remove(item);
				}
			});
		row.addContent(text(item.getHowToTry(), Color.WHITE, 4));
		if (!missing.isEmpty())
		{
			// Instead of a greyed-out button, say what's missing
			row.addContent(text("You need to: " + lowerFirst(String.join("; ", missing)) + ".",
				Color.WHITE, 4));
			return row;
		}
		final JButton start = Style.primary(new JButton(startLabel));
		start.setToolTipText("Walks you through it on the Run tab");
		start.addActionListener(e ->
		{
			runner.start(item);
			showRun.run();
		});
		row.addContent(start);
		return row;
	}

	private static String lowerFirst(String text)
	{
		return text.isEmpty() ? text : Character.toLowerCase(text.charAt(0)) + text.substring(1);
	}

	/**
	 * Tests this client already ran, in a closed group so nobody is asked twice. The developer can run one again
	 * (e.g. after a fix); a bigger change bumps the item's revision so everyone is asked again.
	 */
	private static void addDone(JPanel panel, SettingsStore settings, boolean developer, TestRunner runner,
		Runnable showRun, Runnable redraw)
	{
		final List<TestItem> done = new ArrayList<>();
		for (TestItem item : TestItem.values())
		{
			if (isDone(settings, item))
			{
				done.add(item);
			}
		}
		if (done.isEmpty())
		{
			return;
		}
		final String key = "Guided tests: done";
		final boolean open = settings.isSectionOpen(key);
		add(panel, Card.groupHeader("Done", String.valueOf(done.size()), open, () ->
		{
			settings.setSectionOpen(key, !open);
			redraw.run();
		}));
		if (!open)
		{
			return;
		}
		for (TestItem item : done)
		{
			if (developer)
			{
				add(panel, testRow(item, runner, showRun, "Run again"));
			}
			else
			{
				final JLabel line = text(item.getTitle() + ": " + settings.getClientValue(item.key()),
					ColorScheme.MEDIUM_GRAY_COLOR, 2);
				line.setBorder(new EmptyBorder(1, 8, 2, 0));
				add(panel, line);
			}
		}
	}

	private static JLabel text(String text, Color colour, int gapBelow)
	{
		// UiText.wrap scales to screen pixels; an unscaled width ran off the edge inside an opened test (Sean)
		final JLabel label = new JLabel(text.isEmpty() ? " " : UiText.wrap(text, TEXT_WIDTH));
		label.setForeground(colour);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setBorder(new EmptyBorder(0, 0, gapBelow, 0));
		return label;
	}
}

package com.farmrunautopilot.ui;

import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.PatchType;
import com.farmrunautopilot.tracking.PatchPrediction;
import com.farmrunautopilot.tracking.PatchStatusText;
import com.farmrunautopilot.tracking.PatchTracker;
import java.awt.Color;
import java.awt.BorderLayout;
import java.awt.GridLayout;
import java.time.Instant;
import java.util.EnumMap;
import java.util.Map;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Patch details list (Settings > Debug): every patch with its predicted state.
 */
class PatchDebugPanel extends JPanel
{
	private final PatchTracker tracker;
	private final Map<Patch, JLabel> statusLabels = new EnumMap<>(Patch.class);
	private final Map<Patch, JPanel> rows = new EnumMap<>(Patch.class);

	PatchDebugPanel(PatchTracker tracker)
	{
		this.tracker = tracker;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		final JLabel title = new JLabel("Patch states (debug)");
		Style.title(title);
		title.setBorder(new EmptyBorder(0, 0, 6, 0));
		add(title);

		for (PatchType type : PatchType.values())
		{
			final JLabel header = new JLabel(type.getDisplayName() + " patches");
			header.setForeground(Color.WHITE);
			header.setBorder(new EmptyBorder(8, 0, 4, 0));
			add(header);

			for (Patch patch : Patch.values())
			{
				if (patch.getType() == type)
				{
					add(createRow(patch));
				}
			}
		}
		refresh();
	}

	private JPanel createRow(Patch patch)
	{
		final JPanel row = new JPanel(new GridLayout(2, 1));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(4, 6, 4, 6));

		final JLabel name = new JLabel(patch.getLocation().getDisplayName());
		name.setForeground(ColorScheme.TEXT_COLOR);
		name.setFont(FontManager.getRunescapeSmallFont());

		final JLabel status = new JLabel();
		status.setFont(FontManager.getRunescapeSmallFont());

		row.add(name);
		row.add(status);
		statusLabels.put(patch, status);
		rows.put(patch, row);

		final JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrapper.setBorder(new EmptyBorder(0, 0, 3, 0));
		wrapper.add(row, BorderLayout.CENTER);
		return wrapper;
	}

	/** Re-reads every prediction. Call on the Swing thread. */
	void refresh()
	{
		final long now = Instant.now().getEpochSecond();
		for (Patch patch : Patch.values())
		{
			final PatchPrediction prediction = tracker.predict(patch);
			final JLabel status = statusLabels.get(patch);
			status.setText(PatchStatusText.describe(prediction, now));
			status.setForeground(prediction == null ? ColorScheme.MEDIUM_GRAY_COLOR : Color.WHITE);
			rows.get(patch).setToolTipText(tooltip(patch, prediction, now));
		}
	}

	private static String tooltip(Patch patch, PatchPrediction p, long now)
	{
		if (p == null)
		{
			return patch.getDisplayName() + ": no data yet. Visit the patch to record it.";
		}
		final StringBuilder sb = new StringBuilder("<html>")
			.append(patch.getDisplayName())
			.append("<br>").append(PatchStatusText.age(p.getObservedAt(), now));
		if (p.getPlantedAt() > 0)
		{
			sb.append("<br>planted ").append(PatchStatusText.duration(now - p.getPlantedAt())).append(" ago");
		}
		if (p.getSource() == PatchPrediction.Source.TIME_TRACKING)
		{
			sb.append("<br>from RuneLite Time Tracking");
		}
		return sb.append("</html>").toString();
	}
}

package com.farmrunautopilot.ui;

import com.farmrunautopilot.access.AccessChecker;
