	/** What the run-times report says about the account: only what changes how long travel takes. */
	private List<String> travelUnlocks()
	{
		final AccessSnapshot access = accessChecker.getSnapshot();
		final List<String> lines = new ArrayList<>();
		lines.add("Agility: " + (access.isKnown() ? access.level(Skill.AGILITY) : "unknown"));
		for (Unlock unlock : new Unlock[]{Unlock.FAIRY_RINGS, Unlock.SPIRIT_TREES, Unlock.QUETZAL_KASTORI})
		{
			lines.add(unlock.getDescription() + ": " + (access.getUnlocks().contains(unlock) ? "yes" : "no"));
		}
		return lines;
	}

	/** Where the learned leg times come from, for "Share your run times". */
	void showRunTimes(Supplier<LearnedTimes> learnedTimes)
	{
		this.learnedTimes = learnedTimes;
		rebuild();
	}

	/** Set what the Reset button does. */
	void setResetActions(Runnable runSettings, Runnable everything)
	{
		this.resetRunSettings = runSettings;
		this.resetEverything = everything;
		rebuild();
	}

	private void askReset()
	{
		final String runOnly = "Run settings";
		final String all = "Everything";
		final Object[] options = {runOnly, all, "Cancel"};
		final int choice = JOptionPane.showOptionDialog(this,
			"<html>Run settings: the Farm and Travel tabs and the highlights.<br>"
				+ "Everything: also your house, unlocks, presets, tracked charges and learned run times.<br><br>"
				+ "This can't be undone.</html>",
			"Reset Farm Run Autopilot", JOptionPane.DEFAULT_OPTION, JOptionPane.WARNING_MESSAGE, null, options,
			options[2]);
		if (choice == 0)
		{
			resetRunSettings.run();
		}
		else if (choice == 1)
		{
			resetEverything.run();
		}
	}

	/** Highlights, hint arrow and colours shown during a run (SPEC 13.4). Global, not per account. */
	private void addGuidance(CollapsibleSection s)
	{
		final FarmRunAutopilotConfig c = guidance.get();
		s.addContent(checkBox("Highlight the patch", c.highlightPatch(), true,
			"Outline the patch the current step is about", on -> guidance.set("highlightPatch", on)));
		s.addContent(checkBox("Hint arrow to the patch", c.hintArrow(), true,
			"The game's hint arrow over the patch, also shown on the minimap", on -> guidance.set("hintArrow", on)));
		s.addContent(checkBox("Highlight NPCs", c.highlightGardener(), true,
			"Outline the gardener when paying them, and the quetzal after the Civitas teleport",
			on -> guidance.set("highlightGardener", on)));
		s.addContent(checkBox("Highlight items to use", c.highlightItems(), true,
			"Outline the seed, compost, tool or teleport to use next in your inventory and equipment",
			on -> guidance.set("highlightItems", on)));
		s.addContent(checkBox("Highlight the spell to cast", c.highlightSpell(), true,
			"Outline the teleport (or Cure Plant) to cast next in your spellbook", on -> guidance.set("highlightSpell", on)));
		s.addContent(checkBox("Walking lines (Shortest Path)", c.shortestPathLines(), true,
			"If the Shortest Path plugin is installed, it draws the walk for each \"walk to\" step: walking only, no "
				+ "teleports. Your own Shortest Path settings come back when the step changes.",
			on -> guidance.set("shortestPathLines", on)));
		s.addContent(colourRow("Patch colour", c.patchColour(), "patchColour"));
		s.addContent(colourRow("NPC colour", c.npcColour(), "npcColour"));
		s.addContent(colourRow("Item colour", c.itemColour(), "itemColour"));
	}

	/** A label with a colour swatch that opens RuneLite's colour picker. */
	private JComponent colourRow(String text, Color colour, String key)
	{
		final JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setBorder(new EmptyBorder(1, 0, 1, 0));
		final JLabel label = new JLabel(text);
		label.setForeground(Color.WHITE);
		label.setFont(FontManager.getRunescapeSmallFont());
		final JButton swatch = new JButton();
		swatch.setFocusPainted(false);
		swatch.setBackground(colour);
		swatch.setPreferredSize(new Dimension(40, 20));
		swatch.setToolTipText("Change the " + text.toLowerCase());
		swatch.addActionListener(e -> guidance.pickColour(this, text, swatch.getBackground(), key,
			swatch::setBackground));
		row.add(label, BorderLayout.CENTER);
		row.add(swatch, BorderLayout.EAST);
		row.setMaximumSize(new Dimension(CONTROL_WIDTH, row.getPreferredSize().height));
		row.setAlignmentX(LEFT_ALIGNMENT);
		return row;
	}

}

package com.farmrunautopilot.ui;

import com.farmrunautopilot.access.AccessChecker;
import com.farmrunautopilot.access.AccessSnapshot;
import com.farmrunautopilot.settings.AccountSettings;
import com.farmrunautopilot.settings.RunConfig;
import com.farmrunautopilot.settings.SettingsStore;
import com.farmrunautopilot.supply.Holdings;
import java.awt.Color;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Insets;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.function.Consumer;
import java.util.function.IntConsumer;
import java.util.function.Supplier;
import javax.swing.BoxLayout;
import javax.swing.DefaultListCellRenderer;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.SwingUtilities;
import javax.swing.SpinnerNumberModel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * What the Farm, Travel and Account tabs, and preset management on the Run tab, have in common (SPEC 13.2;
 * look in docs/BRANDING.md): sections that remember being open, the controls, and saving. Each page
 * is its own class ({@link FarmPage}, {@link TravelPage}, {@link AccountPage}, {@link PresetsPage}). Rebuilt from
 * the saved settings whenever they reload or the account's access changes; every edit is saved straight away.
 */
abstract class SetupPanel extends JPanel
{
	/** Room left for controls after the sidebar's and sections' borders. */
	static final int CONTROL_WIDTH = PluginPanel.PANEL_WIDTH - 24;
	/** Room for a short label in front of its control on one line. */
	static final int LABEL_WIDTH = 30;

	final SettingsStore settings;
	final AccessChecker accessChecker;
	/** Redraws every tab after a change, so summaries and Override tags stay current. */
	final Runnable changed;
	/** What the player holds (Travel and Account pages). */
	Supplier<Holdings> holdings = () -> Holdings.EMPTY;

	SetupPanel(SettingsStore settings, AccessChecker accessChecker, Runnable changed)
	{
		this.changed = changed;
		this.settings = settings;
		this.accessChecker = accessChecker;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
	}

	/** What the player holds, for the pages that show it. */
	void showHoldings(Supplier<Holdings> holdings)
	{
		this.holdings = holdings;
	}

	/** Rebuilds every control from the current settings and access. Call on the Swing thread. */
	void rebuild()
	{
		removeAll();
		final AccessSnapshot access = accessChecker.getSnapshot();
		if (!settings.hasProfile())
		{
			add(note("Log in to load and save your setup."));
		}
		else if (!access.isKnown())
		{
			add(note("Checking your quests, diaries and levels... nothing is greyed out until that's done."));
		}
		addSections(settings.editRunConfig(), settings.editAccount(), access);
		revalidate();
		repaint();
	}

	/** This page's sections, from the working settings (Swing thread). */
	abstract void addSections(RunConfig config, AccountSettings account, AccessSnapshot access);

	// Saving

	void saveRun(Runnable change)
	{
		change.run();
		settings.saveRunConfig();
		SwingUtilities.invokeLater(changed);
	}

	/** Saves without redrawing the tabs: number boxes would lose focus on every click, and they change no summary. */
	void saveRunQuietly(Runnable change)
	{
		change.run();
		settings.saveRunConfig();
	}

	/**
	 * @param affectsAccess the change can lock or unlock patches or methods, so re-check access
	 */
	void saveAccount(Runnable change, boolean affectsAccess)
	{
		change.run();
		settings.saveAccount(false);
		SwingUtilities.invokeLater(changed);
		if (affectsAccess)
		{
			accessChecker.requestRefresh();
		}
	}

	static JButton smallButton(String text)
	{
		final JButton button = new JButton(text);
		button.setFont(FontManager.getRunescapeSmallFont());
		// Narrow padding, so three to a row still fit "Rename" and "Delete" (Sean: they showed "Ren..." "Del...")
		button.setMargin(new Insets(2, 2, 2, 2));
		button.setFocusPainted(false);
		button.setAlignmentX(LEFT_ALIGNMENT);
		return Style.button(button);
	}

	// Building blocks

	/** The same component with an explanation on hover (Sprint 7: explanations out of the way). */
	static <C extends JComponent> C tip(C component, String text)
	{
		component.setToolTipText(UiText.tooltip(text, 250));
		return component;
	}

	/** Sections remember being open or closed between sessions. */
	CollapsibleSection section(String title)
	{
		return section(title, null);
	}

	/** With a summary of what's set inside, shown even when the section is closed. */
	CollapsibleSection section(String title, String summary)
	{
		return new CollapsibleSection(title, summary, settings.isSectionOpen(title),
			open -> settings.setSectionOpen(title, open));
	}

	/** e.g. "2 overrides", or null for none. */
	static String overrides(int count)
	{
		return count == 0 ? null : count + (count == 1 ? " override" : " overrides");
	}

	/** A short label with its number box on the same line. */
	static JComponent spinnerRow(String text, JSpinner spinner)
	{
		final JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setBorder(new EmptyBorder(1, 0, 1, 0));
		final JLabel label = new JLabel(wrap(text, CONTROL_WIDTH - 85));
		label.setForeground(Color.WHITE);
		label.setFont(FontManager.getRunescapeSmallFont());
		row.add(label, BorderLayout.CENTER);
		row.add(spinner, BorderLayout.EAST);
		row.setMaximumSize(new Dimension(CONTROL_WIDTH, row.getPreferredSize().height));
		return row;
	}

	/** A tick box half the width, for two to a row. */
	static JCheckBox halfCheckBox(String text, boolean selected, boolean enabled, String tooltip,
		Consumer<Boolean> onChange)
	{
		final JCheckBox box = checkBox(text, selected, enabled, tooltip, onChange);
		box.setText(wrap(text, CONTROL_WIDTH / 2 - 26));
		// Rows of two sit closer together (Sean: a little much padding)
		box.setMargin(new Insets(1, 1, 1, 1));
		return box;
	}

	/**
	 * Controls two to a row, each row only as tall as its own contents (Sean: one long name made every row tall
	 * in a grid).
	 */
	static JComponent twoPerRow(List<JComponent> items)
	{
		final JPanel rows = new JPanel();
		rows.setLayout(new BoxLayout(rows, BoxLayout.Y_AXIS));
		rows.setBackground(ColorScheme.DARK_GRAY_COLOR);
		for (int i = 0; i < items.size(); i += 2)
		{
			final JPanel row = new JPanel(new GridLayout(1, 2, 4, 0));
			row.setBackground(ColorScheme.DARK_GRAY_COLOR);
			row.add(items.get(i));
			if (i + 1 < items.size())
			{
				row.add(items.get(i + 1));
			}
			else
			{
				final JPanel empty = new JPanel();
				empty.setOpaque(false);
				row.add(empty);
			}
			row.setMaximumSize(new Dimension(CONTROL_WIDTH, row.getPreferredSize().height));
			row.setAlignmentX(LEFT_ALIGNMENT);
			rows.add(row);
		}
		rows.setMaximumSize(new Dimension(CONTROL_WIDTH, rows.getPreferredSize().height));
		return rows;
	}

	/** A thin line between two parts of a section. */
	static JComponent divider()
	{
		final JPanel line = new JPanel();
		line.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
		line.setPreferredSize(new Dimension(CONTROL_WIDTH, 1));
		line.setMaximumSize(new Dimension(CONTROL_WIDTH, 1));
		line.setAlignmentX(LEFT_ALIGNMENT);
		final JPanel spaced = new JPanel(new BorderLayout());
		spaced.setBackground(ColorScheme.DARK_GRAY_COLOR);
		spaced.setBorder(new EmptyBorder(6, 0, 2, 0));
		spaced.add(line, BorderLayout.CENTER);
		spaced.setMaximumSize(new Dimension(CONTROL_WIDTH, 9));
		spaced.setAlignmentX(LEFT_ALIGNMENT);
		return spaced;
	}

	/** A short label and its control on one line, e.g. "1st" and a drop-down. */
	static JComponent labeled(String text, JComponent control)
	{
		final JPanel row = new JPanel(new BorderLayout(8, 0));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setBorder(new EmptyBorder(1, 0, 1, 0));
		final JLabel label = new JLabel(text);
		label.setForeground(Color.WHITE);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setPreferredSize(new Dimension(LABEL_WIDTH, label.getPreferredSize().height));
		control.setPreferredSize(new Dimension(CONTROL_WIDTH - LABEL_WIDTH - 8, control.getPreferredSize().height));
		control.setMaximumSize(control.getPreferredSize());
		row.add(label, BorderLayout.WEST);
		row.add(control, BorderLayout.CENTER);
		row.setMaximumSize(new Dimension(CONTROL_WIDTH, row.getPreferredSize().height));
		row.setAlignmentX(LEFT_ALIGNMENT);
		return row;
	}

	static JCheckBox checkBox(String text, boolean selected, boolean enabled, String tooltip,
		Consumer<Boolean> onChange)
	{
		final JCheckBox box = new JCheckBox((String) null, selected);
		box.setEnabled(enabled);
		// HTML text ignores the disabled state, so grey it by hand (before setting the text).
		box.setForeground(enabled ? ColorScheme.TEXT_COLOR : ColorScheme.MEDIUM_GRAY_COLOR);
		box.setText(wrap(text, CONTROL_WIDTH - 30));
		box.setToolTipText(tooltip);
		box.setBackground(ColorScheme.DARK_GRAY_COLOR);
		box.setFont(FontManager.getRunescapeSmallFont());
		box.addActionListener(e -> onChange.accept(box.isSelected()));
		return Style.checkBox(box);
	}

	static <T> JComboBox<Choice<T>> combo(List<Choice<T>> choices, T selected, Consumer<T> onChange)
	{
		final JComboBox<Choice<T>> combo = new JComboBox<>();
		Choice<T> current = choices.isEmpty() ? null : choices.get(0);
		for (Choice<T> choice : choices)
		{
			combo.addItem(choice);
			if (Objects.equals(choice.getValue(), selected))
			{
				current = choice;
			}
		}
		combo.setSelectedItem(current);
		combo.setRenderer(new ChoiceRenderer());
		combo.setPreferredSize(new Dimension(CONTROL_WIDTH, 24));
		combo.setMaximumSize(new Dimension(CONTROL_WIDTH, 24));
		combo.setFont(FontManager.getRunescapeSmallFont());

		final Object[] previous = {current};
		combo.addActionListener(e ->
		{
			@SuppressWarnings("unchecked")
			final Choice<T> picked = (Choice<T>) combo.getSelectedItem();
			if (picked == null || picked == previous[0])
			{
				return;
			}
			if (!picked.isEnabled())
			{
				combo.setSelectedItem(previous[0]);
				return;
			}
			previous[0] = picked;
			onChange.accept(picked.getValue());
		});
		return Style.combo(combo);
	}

	static <E extends Enum<E>> List<Choice<E>> enumChoices(E[] values)
	{
		final List<Choice<E>> choices = new ArrayList<>();
		for (E value : values)
		{
			choices.add(Choice.of(value, value.toString()));
		}
		return choices;
	}

	static JSpinner spinner(int value, int min, int max, int step, IntConsumer onChange)
	{
		final JSpinner spinner = new JSpinner(new SpinnerNumberModel(value, min, max, step));
		spinner.setPreferredSize(new Dimension(70, 24));
		spinner.setMaximumSize(new Dimension(70, 24));
		spinner.addChangeListener(e -> onChange.accept((Integer) spinner.getValue()));
		return Style.spinner(spinner);
	}

	static JLabel label(String text)
	{
		final JLabel label = new JLabel(wrap(text));
		label.setForeground(Color.WHITE);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setBorder(new EmptyBorder(2, 0, 1, 0));
		return label;
	}

	static JLabel subheader(String text)
	{
		final JLabel label = new JLabel(wrap(text));
		Style.title(label);
		label.setBorder(new EmptyBorder(5, 0, 1, 0));
		return label;
	}

	static JLabel note(String text)
	{
		final JLabel label = new JLabel(wrap(text));
		label.setForeground(Color.WHITE);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setBorder(new EmptyBorder(0, 0, 3, 0));
		label.setAlignmentX(LEFT_ALIGNMENT);
		return label;
	}

	static String wrap(String text)
	{
		return wrap(text, CONTROL_WIDTH - 20);
	}

	static String wrap(String text, int width)
	{
		return UiText.wrap(text, width);
	}

	static String title(String enumName)
	{
		final String spaced = enumName.replace('_', ' ').toLowerCase();
		return Character.toUpperCase(spaced.charAt(0)) + spaced.substring(1);
	}

	/** Greys out disabled choices and shows their tooltip. */
	static class ChoiceRenderer extends DefaultListCellRenderer
	{
		@Override
		public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean isSelected,
			boolean cellHasFocus)
		{
			final Component c = super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
			if (value instanceof Choice)
			{
				final Choice<?> choice = (Choice<?>) value;
				if (!choice.isEnabled())
				{
					// Never highlight locked entries: grey text on the grey hover colour is invisible.
					c.setBackground(list.getBackground());
					c.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
				}
				setToolTipText(choice.getTooltip());
			}
			return c;
		}
	}
}

package com.farmrunautopilot.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Insets;
import java.awt.RenderingHints;
import javax.swing.AbstractButton;
import javax.swing.Icon;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JSpinner;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The sidebar's look (Sprint 7 facelift, Sean: "an updated RuneLite look. No gradients, but slightly softer
 * radius, really mature and polished"): RuneLite's own colours and fonts, flat fills, one soft radius. Controls
 * are styled through FlatLaf's style property, which RuneLite's look and feel reads, so they keep their normal
 * behaviour (keyboard, focus, disabled state).
 */
final class Style
{
	/** Corner radius for cards, buttons, drop-downs and number boxes: square (Sean: no radius). */
	static final int ARC = 0;
	/** Done, due, carried. */
	static final Color GREEN = new Color(0x4C, 0xC1, 0x52);
	/** Side of a tick box, in pixels. */
	private static final int TICK_SIZE = 12;
	/** Stop: a muted red, not an alarm. */
	private static final Color DANGER = new Color(0x8A, 0x33, 0x33);
	/** FlatLaf's per-component style property (FlatClientProperties.STYLE). */
	private static final String STYLE = "FlatLaf.style";

	private Style()
	{
	}

	/** A plain button: flat dark grey, lighter on hover, no outline. */
	static <B extends AbstractButton> B button(B button)
	{
		button.setFocusPainted(false);
		button.putClientProperty(STYLE, "arc: " + ARC + "; borderWidth: 0; focusWidth: 0; innerFocusWidth: 0"
			+ "; background: " + hex(ColorScheme.DARKER_GRAY_COLOR)
			+ "; hoverBackground: " + hex(ColorScheme.DARK_GRAY_HOVER_COLOR)
			+ "; pressedBackground: " + hex(ColorScheme.MEDIUM_GRAY_COLOR));
		button.setForeground(ColorScheme.TEXT_COLOR);
		return button;
	}

	/** The main action on screen (Build run, Start now): orange with dark text. */
	static JButton primary(JButton button)
	{
		button.setFocusPainted(false);
		// Slimmer than a standard button (Sean: a little smaller)
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setMargin(new Insets(1, 8, 1, 8));
		button.putClientProperty(STYLE, "arc: " + ARC + "; borderWidth: 0; focusWidth: 0; innerFocusWidth: 0"
			+ "; background: " + hex(ColorScheme.BRAND_ORANGE)
			+ "; hoverBackground: " + hex(ColorScheme.BRAND_ORANGE.brighter())
			+ "; pressedBackground: " + hex(ColorScheme.BRAND_ORANGE.darker()));
		button.setForeground(ColorScheme.DARKER_GRAY_COLOR);
		return button;
	}

	/** Ending something (Stop): a muted red with white text. */
	static JButton danger(JButton button)
	{
		button.setFocusPainted(false);
		button.putClientProperty(STYLE, "arc: " + ARC + "; borderWidth: 0; focusWidth: 0; innerFocusWidth: 0"
			+ "; background: " + hex(DANGER)
			+ "; hoverBackground: " + hex(DANGER.brighter())
			+ "; pressedBackground: " + hex(DANGER.darker()));
		button.setForeground(Color.WHITE);
		return button;
	}

	/** A drop-down: flat, a soft grey outline that turns orange while it has focus, a plain arrow. */
	static <C extends JComboBox<?>> C combo(C combo)
	{
		combo.putClientProperty(STYLE, "arc: " + ARC + "; focusWidth: 0; buttonStyle: none"
			+ "; buttonBackground: " + hex(ColorScheme.DARKER_GRAY_COLOR)
			+ "; buttonArrowColor: " + hex(ColorScheme.LIGHT_GRAY_COLOR)
			+ "; borderColor: " + hex(ColorScheme.MEDIUM_GRAY_COLOR)
			+ "; focusedBorderColor: " + hex(ColorScheme.BRAND_ORANGE));
		combo.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		return combo;
	}

	/** A number box, matching the drop-downs. */
	static JSpinner spinner(JSpinner spinner)
	{
		spinner.putClientProperty(STYLE, "arc: " + ARC + "; focusWidth: 0; buttonStyle: none"
			+ "; buttonBackground: " + hex(ColorScheme.DARKER_GRAY_COLOR)
			+ "; buttonArrowColor: " + hex(ColorScheme.LIGHT_GRAY_COLOR)
			+ "; borderColor: " + hex(ColorScheme.MEDIUM_GRAY_COLOR)
			+ "; focusedBorderColor: " + hex(ColorScheme.BRAND_ORANGE));
		spinner.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		return spinner;
	}

	/**
	 * A tick box in the same family (Sean: the old ones were hard to see): flat dark fill and a grey outline that
	 * turns orange on hover; ticked, filled orange with a dark tick. Ticked but disabled means the plugin saw it
	 * done (a run step) or read it from the game (a detected unlock): filled green, and it can't be changed.
	 * Disabled and empty (not yet possible): a faint outline.
	 */
	static JCheckBox checkBox(JCheckBox box)
	{
		box.setFocusPainted(false);
		box.setIconTextGap(5);
		// A little room above and below, so it doesn't touch a drop-down (Sean)
		box.setMargin(new Insets(3, 1, 3, 1));
		// Drawn here, smaller than the look and feel's (Sean: smaller tick boxes)
		box.setIcon(tick(ColorScheme.DARKER_GRAY_COLOR, ColorScheme.LIGHT_GRAY_COLOR.darker(), null));
		box.setRolloverIcon(tick(ColorScheme.DARKER_GRAY_COLOR, ColorScheme.BRAND_ORANGE, null));
		box.setPressedIcon(tick(ColorScheme.DARKER_GRAY_COLOR, ColorScheme.BRAND_ORANGE, null));
		box.setSelectedIcon(tick(ColorScheme.BRAND_ORANGE, null, ColorScheme.DARKER_GRAY_COLOR));
		box.setRolloverSelectedIcon(tick(ColorScheme.BRAND_ORANGE.brighter(), null, ColorScheme.DARKER_GRAY_COLOR));
		box.setDisabledIcon(tick(ColorScheme.DARK_GRAY_COLOR, ColorScheme.MEDIUM_GRAY_COLOR, null));
		box.setDisabledSelectedIcon(tick(GREEN, null, ColorScheme.DARKER_GRAY_COLOR));
		return box;
	}

	/** A small square tick box: a fill, an outline (or none), and a tick (or none). */
	private static Icon tick(Color fill, Color outline, Color check)
	{
		return new Icon()
		{
			@Override
			public void paintIcon(Component c, Graphics g, int x, int y)
			{
				final Graphics2D g2 = (Graphics2D) g.create();
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g2.setColor(fill);
				g2.fillRect(x, y, TICK_SIZE, TICK_SIZE);
				if (outline != null)
				{
					g2.setColor(outline);
					g2.drawRect(x, y, TICK_SIZE - 1, TICK_SIZE - 1);
				}
				if (check != null)
				{
					g2.setColor(check);
					g2.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
					g2.drawPolyline(new int[]{x + 2, x + 5, x + 9}, new int[]{y + 6, y + 9, y + 3}, 3);
				}
				g2.dispose();
			}

			@Override
			public int getIconWidth()
			{
				return TICK_SIZE;
			}

			@Override
			public int getIconHeight()
			{
				return TICK_SIZE;
			}
		};
	}

	/** Titles and headings: RuneLite's normal font, not bold (Sean: back to how it was). */
	static Font titleFont()
	{
		return FontManager.getRunescapeFont();
	}

	/** A heading in white, as every title is. */
	static <C extends JComponent> C title(C component)
	{
		component.setFont(titleFont());
		component.setForeground(Color.WHITE);
		return component;
	}

	static String hex(Color color)
	{
		return String.format("#%02x%02x%02x", color.getRed(), color.getGreen(), color.getBlue());
	}
}

package com.farmrunautopilot.ui;

import java.awt.CardLayout;
import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.Cursor;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.Border;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;

/**
 * The sidebar's tab strip: one boxed button per tab sharing the width evenly, an icon each with its name on hover
 * (Sean: five names don't fit across the sidebar). The selected tab's icon is orange with a line under it.
 */
class TabBar extends JPanel
{
	// Boxed buttons sharing the width evenly (Sean); the selected one has an orange line along its bottom
	private static final Border SELECTED = BorderFactory.createCompoundBorder(
		BorderFactory.createMatteBorder(0, 0, 2, 0, ColorScheme.BRAND_ORANGE), new EmptyBorder(5, 0, 3, 0));
	private static final Border UNSELECTED = new EmptyBorder(5, 0, 5, 0);

	private final JPanel display;
	private final CardLayout cards = new VisibleCardLayout();
	private final List<JLabel> labels = new ArrayList<>();

	/**
	 * @param display where the selected tab's content is shown
	 */
	TabBar(JPanel display)
	{
		this.display = display;
		display.setLayout(cards);
		setLayout(new GridLayout(1, 0, 3, 0));
		setOpaque(false);
	}

	void addTab(String name, TabIcon icon, JComponent content)
	{
		final JLabel label = new JLabel();
		label.setName(name);
		label.setHorizontalAlignment(JLabel.CENTER);
		label.setOpaque(true);
		label.putClientProperty(TabIcon.class, icon);
		label.setToolTipText(name);
		label.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		label.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				select(name);
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				label.setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR.brighter());
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				label.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			}
		});
		labels.add(label);
		add(label);
		display.add(content, name);
		if (labels.size() == 1)
		{
			select(name);
		}
		else
		{
			style(label, false);
		}
	}

	void select(String name)
	{
		for (JLabel label : labels)
		{
			style(label, label.getName().equals(name));
		}
		cards.show(display, name);
		// The new tab may be shorter or longer: let the scroll pane re-measure
		display.revalidate();
	}

	private static void style(JLabel label, boolean selected)
	{
		label.setBorder(selected ? SELECTED : UNSELECTED);
		label.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		final TabIcon icon = (TabIcon) label.getClientProperty(TabIcon.class);
		label.setIcon(icon.icon(selected ? ColorScheme.BRAND_ORANGE : ColorScheme.LIGHT_GRAY_COLOR));
	}

	/**
	 * A card layout as tall as the tab being shown. The standard one is as tall as the tallest tab, which left
	 * the shorter tabs with a long scroll of empty space.
	 */
	private static final class VisibleCardLayout extends CardLayout
	{
		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			final Component shown = visible(parent);
			return withInsets(parent, shown != null ? shown.getPreferredSize() : new Dimension());
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			final Component shown = visible(parent);
			return withInsets(parent, shown != null ? shown.getMinimumSize() : new Dimension());
		}

		private static Component visible(Container parent)
		{
			for (Component component : parent.getComponents())
			{
				if (component.isVisible())
				{
					return component;
				}
			}
			return null;
		}

		private static Dimension withInsets(Container parent, Dimension size)
		{
			final Insets insets = parent.getInsets();
			return new Dimension(size.width + insets.left + insets.right, size.height + insets.top + insets.bottom);
		}
	}
}

package com.farmrunautopilot.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import javax.swing.Icon;

/**
 * The sidebar tabs' icons (Sean: icons with tooltips, as five names don't fit), drawn as simple line icons in the
 * tab's colour so they need no image files: a play arrow, a sprout, a map pin, a person and a cog.
 */
enum TabIcon
{
	RUN, FARM, TRAVEL, ACCOUNT, SETTINGS;

	private static final int SIZE = 18;

	Icon icon(Color color)
	{
		return new Icon()
		{
			@Override
			public void paintIcon(Component c, Graphics g, int x, int y)
			{
				final Graphics2D g2 = (Graphics2D) g.create();
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
				g2.translate(x, y);
				g2.setColor(color);
				g2.setStroke(new BasicStroke(1.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				paint(g2);
				g2.dispose();
			}

			@Override
			public int getIconWidth()
			{
				return SIZE;
			}

			@Override
			public int getIconHeight()
			{
				return SIZE;
			}
		};
	}

	/** A point on a circle round the icon's centre: moved to (the first) or drawn to. */
	private static void point(Path2D path, boolean first, double radius, double angle)
	{
		final double x = 9 + Math.cos(angle) * radius;
		final double y = 9 + Math.sin(angle) * radius;
		if (first)
		{
			path.moveTo(x, y);
		}
		else
		{
			path.lineTo(x, y);
		}
	}

	private void paint(Graphics2D g)
	{
		switch (this)
		{
			case RUN:
			{
				// A rounded play arrow
				final Path2D p = new Path2D.Float();
				p.moveTo(5, 3.5);
				p.lineTo(15, 9);
				p.lineTo(5, 14.5);
				p.closePath();
				g.fill(p);
				g.draw(p);
				break;
			}
			case FARM:
			{
				// A sprout: a stem and two leaves
				g.drawLine(9, 16, 9, 8);
				final Path2D left = new Path2D.Float();
				left.moveTo(9, 10);
				left.curveTo(4, 10, 3, 6, 3, 4);
				left.curveTo(6, 4, 9, 6, 9, 10);
				g.fill(left);
				final Path2D right = new Path2D.Float();
				right.moveTo(9, 8);
				right.curveTo(9, 4, 12, 2, 15, 2);
				right.curveTo(15, 5, 13, 8, 9, 8);
				g.fill(right);
				break;
			}
			case TRAVEL:
			{
				// A map pin
				final Path2D pin = new Path2D.Float();
				pin.moveTo(9, 16.5);
				pin.curveTo(5, 12, 3.5, 9.5, 3.5, 7);
				pin.curveTo(3.5, 3.5, 6, 1.5, 9, 1.5);
				pin.curveTo(12, 1.5, 14.5, 3.5, 14.5, 7);
				pin.curveTo(14.5, 9.5, 13, 12, 9, 16.5);
				pin.closePath();
				g.draw(pin);
				g.fill(new Ellipse2D.Float(7, 5, 4, 4));
				break;
			}
			case ACCOUNT:
			{
				// A person: head and shoulders
				g.draw(new Ellipse2D.Float(6, 2, 6, 6));
				final Path2D body = new Path2D.Float();
				body.moveTo(3, 16);
				body.curveTo(3, 11.5, 6, 10, 9, 10);
				body.curveTo(12, 10, 15, 11.5, 15, 16);
				g.draw(body);
				break;
			}
			default:
			{
				// A solid gear: six square teeth round a body with a hole (Sean: thin teeth read as a sun)
				final Path2D gear = new Path2D.Double(Path2D.WIND_EVEN_ODD);
				final int teeth = 6;
				final double outer = 8.2;
				final double inner = 6;
				final double half = Math.PI / teeth / 2.2;
				for (int i = 0; i < teeth; i++)
				{
					final double a = 2 * Math.PI / teeth * i;
					final double next = a + 2 * Math.PI / teeth;
					point(gear, i == 0, inner, a - half);
					point(gear, false, outer, a - half * 0.8);
					point(gear, false, outer, a + half * 0.8);
					point(gear, false, inner, a + half);
					point(gear, false, inner, next - half);
				}
				gear.closePath();
				gear.append(new Ellipse2D.Double(6.2, 6.2, 5.6, 5.6), false);
				g.fill(gear);
				break;
			}
		}
	}
}

package com.farmrunautopilot.ui;

import com.farmrunautopilot.access.AccessChecker;
import com.farmrunautopilot.access.AccessSnapshot;
