public class JourneyStepTest
{
	@Test
	public void everyStepSaysWhatToDo()
	{
		for (TravelMethod method : TravelMethod.values())
		{
			for (JourneyStep step : method.getThen())
			{
				assertNotNull(method.name(), step.getKind());
