package com.farmrunautopilot.route;

import com.farmrunautopilot.data.Location;
import com.farmrunautopilot.data.travel.BankTeleport;
import com.farmrunautopilot.data.travel.TravelMethod;
import com.farmrunautopilot.settings.RouteMode;
import java.util.Arrays;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class BankPlannerTest
{
	private static RouteStop stop(Location location)
	{
		return new RouteStop(location, TravelMethod.LUMBRIDGE_TELEPORT, Departure.DIRECT, 20, false);
	}

	/** Four stops: Farming Guild and Catherby have banks nearby, Taverley and Lumbridge don't. */
	private static final Route ROUTE = new Route(Arrays.asList(stop(Location.TAVERLEY), stop(Location.FARMING_GUILD),
		stop(Location.LUMBRIDGE), stop(Location.CATHERBY)), RouteMode.AUTOPILOT, 80, 0);

	/** Each stop needs this many slots. */
	private static BankPlanner.Slots each(int perStop)
	{
		return (a, b) -> (b - a) * perStop;
	}

	private static BankPlanner.Result place(BankPlanner.Slots slots, BankTeleport teleport)
	{
		return BankPlanner.place(ROUTE, slots, 28, teleport, (from, to) -> 0.0,
			to -> new RouteStop(to, TravelMethod.LUMBRIDGE_TELEPORT, Departure.DIRECT, 25, false));
	}

	@Test
	public void noVisitWhenItAllFits()
	{
		assertTrue(place(each(7), null).getVisits().isEmpty());
	}

	@Test
	public void banksAtTheStopWithABankNearby()
	{
		// 4 x 10 slots: two parts of two stops; only the Farming Guild (stop 2) has a bank to split at
		final BankPlanner.Result result = place(each(10), null);
		assertEquals(1, result.getVisits().size());
		assertEquals(Location.FARMING_GUILD, result.getVisits().get(0).getLocation());
		assertNull(result.getVisits().get(0).getTeleport());
	}

	@Test
	public void asManyVisitsAsNeeded()
	{
		// 4 x 20 slots: every stop is its own inventory, so three visits; Taverley and Lumbridge have no bank
		final BankPlanner.Result result = place(each(20), BankTeleport.RING_OF_DUELING);
		assertEquals(3, result.getVisits().size());
		assertEquals(BankTeleport.RING_OF_DUELING, result.getVisits().get(0).getTeleport());
	}

	@Test
	public void nothingFitsWithoutAWay()
	{
		// A stop that can't fit even alone
		assertNull(place(each(30), BankTeleport.RING_OF_DUELING));
		// Every stretch needs a bank where none is near and there's no teleport
		assertNull(BankPlanner.place(new Route(Arrays.asList(stop(Location.TAVERLEY), stop(Location.LUMBRIDGE)),
			RouteMode.AUTOPILOT, 40, 0), each(20), 28, null, (from, to) -> 0.0, to -> stop(to)));
	}

	@Test
	public void bankingByTeleportSetsOffFromTheBank()
	{
		final List<RouteStop> stops = place(each(20), BankTeleport.RING_OF_DUELING).getRoute().getStops();
		// The leg after a teleport to the bank is the leg from anywhere (25 s), not from the stop before
		assertEquals(25, stops.get(1).getLegSeconds(), 1e-9);
	}
}

package com.farmrunautopilot.route;

import static org.junit.Assert.assertEquals;
import com.farmrunautopilot.data.Location;
import com.farmrunautopilot.data.travel.TravelMethod;
import com.farmrunautopilot.run.RunTimings;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

public class LearnedTimesTest
{
	private static LearnedTimes with(Double... seconds)
	{
		return new LearnedTimes(Collections.singletonMap(
			LearnedTimes.key(null, "CATHERBY", "CAMELOT_TELEPORT", "DIRECT"), Arrays.asList(seconds)));
	}

	private static double adjust(LearnedTimes learned, double estimate)
	{
		return learned.adjust(null, Location.CATHERBY, TravelMethod.CAMELOT_TELEPORT, Departure.DIRECT, estimate);
	}

	@Test
	public void noSamplesKeepsTheEstimate()
	{
		assertEquals(30, adjust(LearnedTimes.NONE, 30), 1e-9);
	}

	@Test
	public void blendsUntilThreeSamples()
	{
		// One sample of 60s against a 30s estimate: one third of the way
		assertEquals(40, adjust(with(60.0), 30), 1e-9);
		// Three samples averaging 45s replace the estimate
		assertEquals(45, adjust(with(40.0, 45.0, 50.0), 30), 1e-9);
	}

	@Test
	public void ignoresOutliers()
	{
		// 200s is more than three times the 30s estimate (e.g. the player went to the bank)
		assertEquals(45, adjust(with(40.0, 45.0, 50.0, 200.0), 30), 1e-9);
		// So is 4s, under a third of it (a stop skipped through without going there)
		assertEquals(45, adjust(with(40.0, 45.0, 50.0, 4.0), 30), 1e-9);
	}

	@Test
	public void savedLegsBecomeSamplesExceptTheFirstLeg()
	{
		final LearnedTimes learned = RunTimings.learned(Arrays.asList(
			new RunTimings.Leg("CATHERBY", null, "START", 300, 1, null),
			new RunTimings.Leg("CATHERBY", "CAMELOT_TELEPORT", "DIRECT", 45, 2, null),
			new RunTimings.Leg("CATHERBY", "CAMELOT_TELEPORT", "DIRECT", 45, 3, null),
			new RunTimings.Leg("CATHERBY", "CAMELOT_TELEPORT", "DIRECT", 45, 4, null)));
		assertEquals(45, adjust(learned, 30), 1e-9);
	}

	@Test
	public void otherMethodsAreUnaffected()
	{
		final List<Double> samples = Arrays.asList(60.0, 60.0, 60.0);
		final LearnedTimes learned = new LearnedTimes(Collections.singletonMap(
			LearnedTimes.key(null, "CATHERBY", "CAMELOT_TELEPORT", "POH_NEXUS"), samples));
		assertEquals(30, adjust(learned, 30), 1e-9);
	}

	@Test
	public void legsThatDependOnWhereTheyStartAreKeptPerStart()
	{
		// The Stronghold's spirit tree is 14 tiles from its patch; Tree Gnome Village's is 60
		final LearnedTimes learned = RunTimings.learned(Arrays.asList(
			new RunTimings.Leg("TREE_GNOME_VILLAGE", "SPIRIT_TREE_TREE_GNOME_VILLAGE", "DIRECT", 30, 1, "GNOME_STRONGHOLD"),
			new RunTimings.Leg("TREE_GNOME_VILLAGE", "SPIRIT_TREE_TREE_GNOME_VILLAGE", "DIRECT", 30, 2, "GNOME_STRONGHOLD"),
			new RunTimings.Leg("TREE_GNOME_VILLAGE", "SPIRIT_TREE_TREE_GNOME_VILLAGE", "DIRECT", 30, 3, "GNOME_STRONGHOLD"),
			// Saved before the start was recorded: can't tell where it started, so not a sample
			new RunTimings.Leg("TREE_GNOME_VILLAGE", "SPIRIT_TREE_TREE_GNOME_VILLAGE", "DIRECT", 90, 4, null),
			new RunTimings.Leg("TAVERLEY", null, "WALK", 20, 5, "FALADOR_PARK"),
			new RunTimings.Leg("TAVERLEY", null, "WALK", 20, 6, "FALADOR_PARK"),
			new RunTimings.Leg("TAVERLEY", null, "WALK", 20, 7, "FALADOR_PARK")));
		assertEquals(30, learned.adjust(Location.GNOME_STRONGHOLD, Location.TREE_GNOME_VILLAGE,
			TravelMethod.SPIRIT_TREE_TREE_GNOME_VILLAGE, Departure.DIRECT, 40), 1e-9);
		// From somewhere else: no samples
		assertEquals(40, learned.adjust(Location.FARMING_GUILD, Location.TREE_GNOME_VILLAGE,
			TravelMethod.SPIRIT_TREE_TREE_GNOME_VILLAGE, Departure.DIRECT, 40), 1e-9);
		// Walks are learned too
		assertEquals(20, learned.adjust(Location.FALADOR_PARK, Location.TAVERLEY, null, Departure.WALK, 33), 1e-9);
	}
}

package com.farmrunautopilot.route;

import com.farmrunautopilot.access.AccessSnapshot;
import com.farmrunautopilot.data.AchievementDiary;
import com.farmrunautopilot.data.Location;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.Unlock;
import com.farmrunautopilot.data.travel.Spellbook;
import com.farmrunautopilot.data.travel.TravelMethod;
import com.farmrunautopilot.settings.PohSetup;
import com.farmrunautopilot.settings.RunConfig;
import com.farmrunautopilot.supply.Holdings;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

/** Known-good chains a farmer would take, so the cost model can't drift away from them unnoticed. */
public class RouteChainTest
{
	private static AccessSnapshot access()
	{
		final Map<Quest, QuestState> quests = new EnumMap<>(Quest.class);
		quests.put(Quest.TREE_GNOME_VILLAGE, QuestState.FINISHED);
		quests.put(Quest.FAIRYTALE_II__CURE_A_QUEEN, QuestState.FINISHED);
		final Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		for (Skill skill : AccessSnapshot.REAL_SKILLS)
		{
			levels.put(skill, 99);
		}
		return new AccessSnapshot(true, quests, levels, Collections.emptySet(),
			EnumSet.of(Unlock.SPIRIT_TREES, Unlock.FAIRY_RINGS), null, Spellbook.STANDARD, Collections.emptySet());
	}

	private static Holdings holdings(int... itemIds)
	{
		final Map<Integer, Integer> bank = new java.util.HashMap<>();
		for (int id : itemIds)
		{
			bank.put(id, 1);
		}
		final Map<Holdings.Source, Map<Integer, Integer>> items = new EnumMap<>(Holdings.Source.class);
		items.put(Holdings.Source.BANK, bank);
		return new Holdings(items, Collections.emptyMap(), Collections.emptySet(), true, false);
	}

	@Test
	public void strongholdThenSpiritTreeToTreeGnomeVillage()
	{
		final List<Patch> patches = Arrays.asList(Patch.GNOME_STRONGHOLD_TREE, Patch.GNOME_STRONGHOLD_FRUIT_TREE,
			Patch.TREE_GNOME_VILLAGE_FRUIT_TREE, Patch.FALADOR_TREE, Patch.LUMBRIDGE_TREE, Patch.VARROCK_TREE);
		// Isolate the chain: ending near a bank would otherwise favour finishing at the Stronghold's bank
		final RunConfig config = new RunConfig().sanitise();
		config.setEndNearBank(false);
		final Route route = RoutePlanner.plan(patches, config, access(),
			holdings(ItemID.SLAYER_RING_8, ItemID.DRAMEN_STAFF), new PohSetup());

		final List<RouteStop> stops = route.getStops();
		int stronghold = -1;
		for (int i = 0; i < stops.size(); i++)
		{
			if (stops.get(i).getLocation() == Location.GNOME_STRONGHOLD)
			{
				stronghold = i;
			}
		}
		if (stronghold + 1 >= stops.size())
		{
			throw new AssertionError(describe(stops));
		}
		final RouteStop next = stops.get(stronghold + 1);
		assertEquals(stops.toString(), Location.TREE_GNOME_VILLAGE, next.getLocation());
		assertEquals(stops.toString(), TravelMethod.SPIRIT_TREE_TREE_GNOME_VILLAGE, next.getMethod());
	}

	@Test
	public void startsByWalkingToANearbyStop()
	{
		// By the Grand Tree, about 50 tiles from the Stronghold patches, with Start at: Anywhere
		final List<RouteStop> stops = RoutePlanner.plan(Arrays.asList(Patch.values()), new RunConfig().sanitise(),
			access(), holdings(ItemID.SLAYER_RING_8, ItemID.DRAMEN_STAFF), new PohSetup(), LearnedTimes.NONE, null,
			Location.GNOME_STRONGHOLD, 50).getStops();
		assertEquals(describe(stops), Location.GNOME_STRONGHOLD, stops.get(0).getLocation());
		assertEquals(describe(stops), Departure.WALK, stops.get(0).getDeparture());
		assertEquals(describe(stops), TravelMethod.SPIRIT_TREE_TREE_GNOME_VILLAGE, stops.get(1).getMethod());

		// Even when ending the run at the Stronghold's bank would otherwise win by a second or two
		final List<RouteStop> few = RoutePlanner.plan(Arrays.asList(Patch.GNOME_STRONGHOLD_TREE, Patch.FALADOR_TREE,
			Patch.LUMBRIDGE_TREE, Patch.VARROCK_TREE), new RunConfig().sanitise(), access(),
			holdings(ItemID.SLAYER_RING_8), new PohSetup(), LearnedTimes.NONE, null, Location.GNOME_STRONGHOLD, 36)
			.getStops();
		assertEquals(describe(few), Location.GNOME_STRONGHOLD, few.get(0).getLocation());

		// Near Falador Park (57 tiles), where the ring of wealth is quicker than the walk: still the first stop
		final List<RouteStop> park = RoutePlanner.plan(Arrays.asList(Patch.values()), new RunConfig().sanitise(),
			access(), holdings(ItemID.SLAYER_RING_8, ItemID.RING_OF_WEALTH_5), new PohSetup(), LearnedTimes.NONE,
			null, Location.FALADOR_PARK, 57).getStops();
		assertEquals(describe(park), Location.FALADOR_PARK, park.get(0).getLocation());
	}

	@Test
	public void treeGnomeVillageChainsFromTheStronghold()
	{
		// The CIQ fairy ring walk is long; the Stronghold's spirit tree is the way in
		assertEquals(true, RoutePlanner.chainsFrom(Location.GNOME_STRONGHOLD, Location.TREE_GNOME_VILLAGE,
			new RunConfig().sanitise(), access(), holdings(ItemID.SLAYER_RING_8, ItemID.DRAMEN_STAFF), new PohSetup(),
			LearnedTimes.NONE));
	}

	@Test
	public void bigRunsKeepTheStrongholdChain()
	{
		// Above the exact-search limit the fast search must still find the chain
		final List<Patch> patches = Arrays.asList(Patch.values());
		final RunConfig config = new RunConfig().sanitise();
		config.setEndNearBank(false);
		final List<RouteStop> stops = RoutePlanner.plan(patches, config, access(),
			holdings(ItemID.SLAYER_RING_8, ItemID.DRAMEN_STAFF), new PohSetup()).getStops();
		assertEquals(true, stops.size() > RoutePlanner.EXACT_LIMIT);
		int stronghold = -1;
		for (int i = 0; i < stops.size(); i++)
		{
			if (stops.get(i).getLocation() == Location.GNOME_STRONGHOLD)
			{
				stronghold = i;
			}
		}
		assertEquals(describe(stops), true, stronghold + 1 < stops.size()
			&& stops.get(stronghold + 1).getMethod() == TravelMethod.SPIRIT_TREE_TREE_GNOME_VILLAGE);
	}

	@Test
	public void varlamoreChainsWithRenuAndKastoriIsNotLast()
	{
		final Map<Quest, QuestState> quests = new EnumMap<>(Quest.class);
		quests.put(Quest.CHILDREN_OF_THE_SUN, QuestState.FINISHED);
		quests.put(Quest.TWILIGHTS_PROMISE, QuestState.FINISHED);
		final Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		for (Skill skill : AccessSnapshot.REAL_SKILLS)
		{
			levels.put(skill, 99);
		}
		final AccessSnapshot access = new AccessSnapshot(true, quests, levels, Collections.emptySet(),
			EnumSet.of(Unlock.QUETZAL_KASTORI), null, Spellbook.STANDARD, Collections.emptySet());
		final RunConfig config = new RunConfig().sanitise();
		config.setEndNearBank(false);
		final List<Patch> patches = Arrays.asList(Patch.KASTORI_FRUIT_TREE, Patch.NEMUS_RETREAT_TREE,
			Patch.CIVITAS_HERB);

		// With an unlimited whistle, whistling beats walking back to the pad; Kastori still isn't last
		final List<RouteStop> whistle = RoutePlanner.plan(patches, config, access,
			holdings(ItemID.HG_QUETZALWHISTLE_PERFECTED_INFINITE), new PohSetup()).getStops();
		assertEquals(describe(whistle), true, whistle.get(whistle.size() - 1).getLocation() != Location.KASTORI);

		// Without a whistle: in by teleport, then Renu between the pads
		final List<RouteStop> noWhistle = RoutePlanner.plan(patches, config, access, holdings(), new PohSetup())
			.getStops();
		int renu = 0;
		for (RouteStop stop : noWhistle)
		{
			renu += stop.getDeparture() == Departure.RENU ? 1 : 0;
		}
		assertEquals(describe(noWhistle), 2, renu);
		assertEquals(describe(noWhistle), true,
			noWhistle.get(noWhistle.size() - 1).getLocation() != Location.KASTORI);
	}

	@Test
	public void faladorParkWalkToTaverleyThenCabbageToFaladorFarm()
	{
		final RunConfig config = new RunConfig().sanitise();
		config.setEndNearBank(false);
		final Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		for (Skill skill : AccessSnapshot.REAL_SKILLS)
		{
			levels.put(skill, 99);
		}
		// Explorer's ring needs the medium Lumbridge & Draynor diary
		final AccessSnapshot access = new AccessSnapshot(true, Collections.emptyMap(), levels,
			Collections.singleton(AccessSnapshot.diaryKey(AchievementDiary.LUMBRIDGE_DRAYNOR,
				AchievementDiary.Tier.MEDIUM)), Collections.emptySet(), null, Spellbook.STANDARD, Collections.emptySet());
		final List<RouteStop> stops = RoutePlanner.plan(Arrays.asList(Patch.FALADOR_TREE, Patch.TAVERLEY_TREE,
			Patch.FALADOR_HERB), config, access, holdings(ItemID.RING_OF_WEALTH_5, ItemID.LUMBRIDGE_RING_ELITE),
			new PohSetup()).getStops();

		// Falador Park and Taverley back to back with a walk between (either way round), and the farm by the
		// cabbage teleport rather than a walk; the same legs in any order cost the same
		boolean walkedBetween = false;
		for (int i = 1; i < stops.size(); i++)
		{
			final boolean pair = (stops.get(i - 1).getLocation() == Location.FALADOR_PARK
				&& stops.get(i).getLocation() == Location.TAVERLEY)
				|| (stops.get(i - 1).getLocation() == Location.TAVERLEY && stops.get(i).getLocation() == Location.FALADOR_PARK);
			walkedBetween |= pair && stops.get(i).getDeparture() == Departure.WALK;
		}
		assertEquals(describe(stops), true, walkedBetween);
		for (RouteStop stop : stops)
		{
			if (stop.getLocation() == Location.FALADOR_FARM)
			{
				assertEquals(describe(stops), TravelMethod.EXPLORERS_RING_CABBAGE_PATCH, stop.getMethod());
			}
		}
	}

	private static String describe(List<RouteStop> stops)
	{
		final StringBuilder b = new StringBuilder();
		for (RouteStop stop : stops)
		{
			b.append(stop.getLocation()).append(" via ").append(stop.describeTravel()).append(" (")
				.append(Math.round(stop.getLegSeconds())).append(" s); ");
		}
		return b.toString();
	}
}

package com.farmrunautopilot.route;

import static org.junit.Assert.assertArrayEquals;
