import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class RunSessionTest
{
	private static SupplyLine line(SupplyLine.Group group, int need, int carried, int leprechaun)
	{
		final Map<Holdings.Source, Integer> where = new EnumMap<>(Holdings.Source.class);
		if (carried > 0)
		{
			where.put(Holdings.Source.INVENTORY, carried);
		}
		if (leprechaun > 0)
		{
			where.put(Holdings.Source.LEPRECHAUN, leprechaun);
		}
		return new SupplyLine(group, "x", need, carried + leprechaun, carried, where, null, 1, false, null,
			new int[]{1});
	}

	private static RunPlan plan(List<SupplyLine> lines)
	{
		final Route route = new Route(Collections.singletonList(
			new RouteStop(Location.CATHERBY, null, Departure.WALK, 10, false)), RouteMode.AUTOPILOT, 10, 20);
		final SupplyPlan supplies = new SupplyPlan(lines, Collections.emptyMap(), Collections.emptyList(),
			Collections.emptyList(), Collections.emptyList(), 0, "", 0, Collections.emptyMap());
		return new RunPlan(RunSelection.EMPTY, route, supplies, Collections.emptyMap());
	}

	@Test
	public void readyWhenCarriedOrAtTheLeprechaun()
	{
		assertTrue(RunSession.isReady(plan(java.util.Arrays.asList(
			line(SupplyLine.Group.SEEDS, 8, 8, 0),
			line(SupplyLine.Group.TOOLS, 8, 0, 128)))));
	}

	@Test
	public void notReadyWhenSomethingIsStillInTheBank()
	{
		assertFalse(RunSession.isReady(plan(Collections.singletonList(line(SupplyLine.Group.SEEDS, 8, 3, 0)))));
	}

	@Test
	public void optionalItemsDontBlock()
	{
		assertTrue(RunSession.isReady(plan(java.util.Arrays.asList(
			line(SupplyLine.Group.SEEDS, 1, 1, 0),
			line(SupplyLine.Group.OPTIONAL, 4, 0, 0)))));
	}

	@Test
	public void harvestSpaceForHerbsAndFruit()
	{
		final PatchPrediction fruit = new PatchPrediction(Patch.CATHERBY_FRUIT_TREE, Crop.PAPAYA,
			PatchState.HARVESTABLE, 4, 7, 0, 0, 0, PatchPrediction.Source.THIS_PLUGIN);
		assertEquals(4, PatchGuide.expectedHarvest(Patch.CATHERBY_FRUIT_TREE, StepAdvisor.Action.PICK, fruit));
		assertEquals(6, PatchGuide.expectedHarvest(Patch.CATHERBY_FRUIT_TREE, StepAdvisor.Action.CHECK_HEALTH, null));
		assertEquals(8, PatchGuide.expectedHarvest(Patch.CATHERBY_HERB, StepAdvisor.Action.PICK, null));
		assertEquals(0, PatchGuide.expectedHarvest(Patch.CATHERBY_HERB, StepAdvisor.Action.PLANT, null));
		assertEquals(0, PatchGuide.expectedHarvest(Patch.TAVERLEY_TREE, StepAdvisor.Action.CHECK_HEALTH, null));
	}

	@Test
	public void notReadyWithNoRoute()
	{
		assertFalse(RunSession.isReady(RunPlan.EMPTY));
	}

	@Test
	public void countsOnlyRequiredLinesStillInTheBank()
	{
		assertEquals(2, RunSession.missingCount(plan(java.util.Arrays.asList(
			line(SupplyLine.Group.SEEDS, 8, 3, 0),
			line(SupplyLine.Group.TRAVEL, 1, 0, 0),
			line(SupplyLine.Group.TOOLS, 1, 0, 1),
			line(SupplyLine.Group.OPTIONAL, 4, 0, 0)))));
	}

	@Test
	public void teleportIsALongJumpInOneTick()
	{
		final WorldPoint bank = new WorldPoint(3092, 3245, 0);
		assertFalse(RunSession.isTeleport(bank, new WorldPoint(3094, 3245, 0)));
		assertFalse(RunSession.isTeleport(null, bank));
		assertTrue(RunSession.isTeleport(bank, new WorldPoint(2813, 3463, 0)));
	}
}

package com.farmrunautopilot.run;

import static org.junit.Assert.assertEquals;
import com.farmrunautopilot.data.PatchType;
import java.util.Arrays;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class RunTimingsTest
{
	@Test
	public void runsAreComparedWithLikeRuns()
	{
		final Map<PatchType, Integer> counts = new EnumMap<>(PatchType.class);
		counts.put(PatchType.TREE, 6);
		counts.put(PatchType.HERB, 6);
		final String makeup = RunTimings.makeup(counts);
		assertEquals("6 trees, 6 herbs",RunTimings.makeupName(counts));

		final List<RunTimings.Run> runs = Arrays.asList(
			new RunTimings.Run(1, 600, 12, true, makeup),
			new RunTimings.Run(2, 500, 12, true, makeup),
			new RunTimings.Run(3, 300, 6, true, "HERB:6"),
			new RunTimings.Run(4, 400, 5, false, makeup),
			new RunTimings.Run(5, 550, 12, true, makeup),
			new RunTimings.Run(6, 700, 12, true, makeup));
		assertEquals(Arrays.asList(500.0, 550.0, 600.0), RunTimings.best(runs, makeup, 3));
	}

	@Test
	public void rankText()
	{
		assertEquals(" - new best for 6 herbs!", RunSession.rank(Arrays.asList(300.0, 320.0), 300, "6 herbs"));
		assertEquals(" - 2nd best for 6 herbs", RunSession.rank(Arrays.asList(300.0, 320.0), 320, "6 herbs"));
		assertEquals(" - first time for 6 herbs", RunSession.rank(Arrays.asList(300.0), 300, "6 herbs"));
		assertEquals("", RunSession.rank(Arrays.asList(1.0, 2.0, 3.0), 400, "6 herbs"));
	}
}

package com.farmrunautopilot.run;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The walk-only overrides only work if every key and value is one Shortest Path knows: an unknown one is
 * ignored and the player's own setting wins (the "NONE" vs "None" bug sent Sean to a bank, 2026-10-11).
 */
public class ShortestPathBridgeTest
{
	/** Shortest Path's transport and bank config keys at commit 7e81a40 (ShortestPathConfig keyName). */
	private static final Set<String> KNOWN_KEYS = new HashSet<>(Arrays.asList(
		"highlightBankPickupItems", "highlightInventoryItems", "highlightSpellbookSpells", "includeBankPath",
		"showBankPickupInfo", "useAgilityShortcuts", "useBoats", "useCanoes", "useCharterShips", "useFairyRings",
		"useGnomeGliders", "useGrappleShortcuts", "useHotAirBalloons", "useMagicCarpets", "useMagicMushtrees",
		"useMinecarts", "usePoh", "usePohFairyRing", "usePohMountedItems", "usePohObelisk", "usePohSpiritTree",
		"useQuetzals", "useSailingMoves", "useSeasonalTransports", "useShips", "useSpiritTrees",
		"useTeleportationItems", "useTeleportationLevers", "useTeleportationMinigames", "useTeleportationPortals",
		"useTeleportationPortalsPoh", "useTeleportationSpells", "useTeleportationSpellsHome",
		"useWildernessObelisks"));
	/** Its TeleportationItem names, matched exactly. */
	private static final Set<String> TELEPORTATION_ITEMS = new HashSet<>(Arrays.asList("None", "Inventory",
		"Inventory (perm)", "Inventory and Bank", "Inventory and Bank (perm)", "Unlocked", "Unlocked (perm)", "All",
		"All (perm)"));

	@Test
	public void everyOverrideIsAKeyShortestPathKnows()
	{
		for (String key : ShortestPathBridge.WALK_ONLY.keySet())
		{
			assertTrue(key, KNOWN_KEYS.contains(key));
		}
	}

	@Test
	public void teleportItemsAreOffByTheirExactName()
	{
		final Object value = ShortestPathBridge.WALK_ONLY.get("useTeleportationItems");
		assertEquals("None", value);
		assertTrue(TELEPORTATION_ITEMS.contains(value));
	}

	@Test
	public void everyWayToTravelButWalkingIsOff()
	{
		// Agility shortcuts are walking, so they stay as the player has them
		for (String key : KNOWN_KEYS)
		{
			if (key.startsWith("use") && !key.equals("useAgilityShortcuts") && !key.equals("useTeleportationItems"))
			{
				final Map<String, Object> overrides = ShortestPathBridge.WALK_ONLY;
				assertEquals(key, Boolean.FALSE, overrides.get(key));
			}
		}
	}
}

