package com.farmrunautopilot.supply;

import static org.junit.Assert.assertEquals;
import com.farmrunautopilot.data.Crop;
import com.farmrunautopilot.data.Patch;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Predicate;
import org.junit.Test;

public class CropAllocatorTest
{
	private static final List<Patch> HERBS = Arrays.asList(Patch.FALADOR_HERB, Patch.CATHERBY_HERB, Patch.ARDOUGNE_HERB,
		Patch.TROLL_STRONGHOLD_HERB, Patch.WEISS_HERB, Patch.HARMONY_ISLAND_HERB);
	private static final Set<Patch> DISEASE_FREE = EnumSet.of(Patch.TROLL_STRONGHOLD_HERB, Patch.WEISS_HERB,
		Patch.HARMONY_ISLAND_HERB);
	private static final Predicate<Patch> SAFE = DISEASE_FREE::contains;
	private static final List<Crop> TOADFLAX_THEN_GUAM = Arrays.asList(Crop.TOADFLAX, Crop.GUAM);
	private static final List<Crop> NONE_RESERVED = Collections.emptyList();

	private static Map<Crop, Integer> stock(Object... cropThenCount)
	{
		final Map<Crop, Integer> stock = new HashMap<>();
		for (int i = 0; i < cropThenCount.length; i += 2)
		{
			stock.put((Crop) cropThenCount[i], (Integer) cropThenCount[i + 1]);
		}
		return stock;
	}

	private static Map<Patch, Crop> allocate(List<Crop> choices, Map<Crop, Integer> stock, List<Crop> reserved)
	{
		return CropAllocator.allocate(HERBS, choices, c -> stock.getOrDefault(c, 0), SAFE, reserved);
	}

	private static int count(Map<Patch, Crop> plan, Crop crop)
	{
		return Collections.frequency(plan.values(), crop);
	}

	@Test
	public void singleChoiceFillsEveryPatch()
	{
		final Map<Patch, Crop> plan = allocate(Collections.singletonList(Crop.RANARR), stock(Crop.RANARR, 1), NONE_RESERVED);
		assertEquals(6, count(plan, Crop.RANARR));
	}

	@Test
	public void shortStockFallsBackInOrderAndSafePatchesGetTheBest()
	{
		final List<Crop> choices = Arrays.asList(Crop.RANARR, Crop.TOADFLAX, Crop.GUAM);
		final Map<Patch, Crop> plan = allocate(choices, stock(Crop.RANARR, 3, Crop.TOADFLAX, 2, Crop.GUAM, 10),
			NONE_RESERVED);
		// Three ranarr go to the three disease-free patches.
		for (Patch patch : DISEASE_FREE)
		{
			assertEquals(Crop.RANARR, plan.get(patch));
		}
		assertEquals(2, count(plan, Crop.TOADFLAX));
		assertEquals(1, count(plan, Crop.GUAM));
	}

	@Test
	public void whenEverythingRunsOutTheFirstChoiceIsShort()
	{
		final List<Crop> choices = Arrays.asList(Crop.RANARR, Crop.TOADFLAX, Crop.GUAM);
		final Map<Patch, Crop> plan = allocate(choices, stock(Crop.RANARR, 1, Crop.TOADFLAX, 1, Crop.GUAM, 1),
			NONE_RESERVED);
		assertEquals(1, count(plan, Crop.TOADFLAX));
		assertEquals(1, count(plan, Crop.GUAM));
		assertEquals(4, count(plan, Crop.RANARR));
	}

	@Test
	public void reservedHerbsGoOnlyToDiseaseFreePatchesBestFirst()
	{
		// Snapdragon ranked above ranarr. Plenty of both, but other patches never get them.
		final Map<Patch, Crop> plan = allocate(TOADFLAX_THEN_GUAM,
			stock(Crop.SNAPDRAGON, 2, Crop.RANARR, 10, Crop.TOADFLAX, 10),
			Arrays.asList(Crop.SNAPDRAGON, Crop.RANARR));
		assertEquals(2, count(plan, Crop.SNAPDRAGON));
		assertEquals(1, count(plan, Crop.RANARR));
		assertEquals(3, count(plan, Crop.TOADFLAX));
		assertEquals(Crop.TOADFLAX, plan.get(Patch.CATHERBY_HERB));
	}

	@Test
	public void diseaseFreePatchesFallBackToNormalChoicesWhenReservedRunOut()
	{
		final Map<Patch, Crop> plan = allocate(TOADFLAX_THEN_GUAM, stock(Crop.RANARR, 1, Crop.TOADFLAX, 10),
			Collections.singletonList(Crop.RANARR));
		assertEquals(1, count(plan, Crop.RANARR));
		assertEquals(5, count(plan, Crop.TOADFLAX));
	}

	@Test
	public void reservedFirstChoiceIsKeptOutOfRiskyPatches()
	{
		// Ranarr is both the 1st choice and reserved: risky patches get the 2nd choice.
		final Map<Patch, Crop> plan = allocate(Arrays.asList(Crop.RANARR, Crop.TOADFLAX),
			stock(Crop.RANARR, 10, Crop.TOADFLAX, 10), Collections.singletonList(Crop.RANARR));
		assertEquals(3, count(plan, Crop.RANARR));
		assertEquals(Crop.TOADFLAX, plan.get(Patch.FALADOR_HERB));
	}

	@Test
	public void resultKeepsThePatchOrder()
	{
		final Map<Patch, Crop> plan = allocate(TOADFLAX_THEN_GUAM, stock(Crop.TOADFLAX, 5), NONE_RESERVED);
		assertEquals(HERBS, Arrays.asList(plan.keySet().toArray(new Patch[0])));
	}
}

package com.farmrunautopilot.supply;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.regex.Matcher;
import org.junit.Test;

/** Message wording from the wiki's item pages and transcripts. */
public class ItemChargeTrackerTest
{
	private static int read(java.util.regex.Pattern pattern, String message)
	{
		final Matcher m = pattern.matcher(message);
		assertTrue(message, m.matches());
		return ItemChargeTracker.count(m.group(1));
	}

	@Test
	public void readsCheckAndChargeMessages()
	{
		assertEquals(4, read(ItemChargeTracker.WHISTLE_CHECK, "Your quetzal whistle has 4 charges remaining."));
		assertEquals(0, read(ItemChargeTracker.TALISMAN_CHECK, "The talisman has no charges."));
		assertEquals(1, read(ItemChargeTracker.TALISMAN_CHECK, "The talisman has one charge."));
		assertEquals(1000, read(ItemChargeTracker.TALISMAN_CHECK, "The talisman has 1,000 charges."));
		assertEquals(250, read(ItemChargeTracker.TALISMAN_CHARGED, "Your talisman now has 250 charges."));
		assertEquals(1, read(ItemChargeTracker.PENDANT_CHECK, "The pendant has 1 charge."));
		assertEquals(37, read(ItemChargeTracker.PENDANT_CHARGED,
			"Your add 12 frozen tears to your pendant. It now has 37 charges."));
		assertFalse(ItemChargeTracker.PENDANT_CHECK.matcher("The talisman has 3 charges.").matches());
	}

	@Test
	public void rechargeLineHasNoCount()
	{
		// Soar Leader Pitri's line, as the client logs it: the count has to come from the next Check or flight
		assertTrue("Soar Leader Pitri|There you go. Some whistle charges for you!"
			.endsWith("Some whistle charges for you!"));
		assertFalse(ItemChargeTracker.WHISTLE_CHECK.matcher("There you go. Some whistle charges for you!").matches());
	}
}

package com.farmrunautopilot.supply;

import com.farmrunautopilot.data.travel.TravelItem;
import com.farmrunautopilot.settings.Outfit;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.gameval.ItemID;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** Sprint 3: what one part of a run uses up, worn teleports, and counting a frozen list again. */
public class RunPartsTest
{
	private static Holdings holdings(Map<Holdings.Source, Map<Integer, Integer>> items)
	{
		return new Holdings(items, Collections.emptyMap(), Collections.emptySet(), true, false);
	}

	private static Map<Integer, Integer> of(int id, int n)
	{
		final Map<Integer, Integer> m = new HashMap<>();
		m.put(id, n);
		return m;
	}

	private static SupplyLine line(String name, int need, boolean consumed, int... ids)
	{
		return new SupplyLine(SupplyLine.Group.SEEDS, name, need, 0, 0, Collections.emptyMap(), null, 1, false, null,
			ids, consumed);
	}

	@Test
	public void useTakesFromCarriedFirstThenTheBank()
	{
		final Map<Holdings.Source, Map<Integer, Integer>> items = new EnumMap<>(Holdings.Source.class);
		items.put(Holdings.Source.INVENTORY, of(ItemID.RANARR_SEED, 3));
		items.put(Holdings.Source.BANK, of(ItemID.RANARR_SEED, 10));
		final Holdings left = holdings(items).use(new int[]{ItemID.RANARR_SEED}, 5);
		assertEquals(0, (int) left.in(Holdings.Source.INVENTORY).get(ItemID.RANARR_SEED));
		assertEquals(8, (int) left.in(Holdings.Source.BANK).get(ItemID.RANARR_SEED));
	}

	@Test
	public void aPartUsesUpSeedsButNotTools()
	{
		final Map<Holdings.Source, Map<Integer, Integer>> items = new EnumMap<>(Holdings.Source.class);
		final Map<Integer, Integer> bank = of(ItemID.RANARR_SEED, 10);
		bank.put(ItemID.SPADE, 1);
		items.put(Holdings.Source.BANK, bank);
		final SupplyPlan part = new SupplyPlan(Arrays.asList(line("Ranarr seed", 4, true, ItemID.RANARR_SEED),
			line("Spade", 1, false, ItemID.SPADE)), Collections.emptyMap(), Collections.emptyList(),
			Collections.emptyList(), Collections.emptyList(), 0, "", 2, Collections.emptyMap());
		final Holdings left = part.leftAfter(holdings(items));
		// The second part of the run can only count on the 6 seeds the first part didn't plant
		assertEquals(6, left.count(ItemID.RANARR_SEED));
		assertEquals(1, left.count(ItemID.SPADE));
	}

	@Test
	public void aFrozenListIsCountedAgainstWhatsHeldNow()
	{
		final SupplyLine planned = line("Ranarr seed", 4, true, ItemID.RANARR_SEED);
		final Map<Holdings.Source, Map<Integer, Integer>> items = new EnumMap<>(Holdings.Source.class);
		items.put(Holdings.Source.INVENTORY, of(ItemID.RANARR_SEED, 4));
		final SupplyLine now = planned.counted(holdings(items));
		assertEquals(4, now.getCarried());
		assertEquals(4, now.getNeed());
		assertTrue(now.isConsumed());
	}

	@Test
	public void oneTeleportPerEquipmentSlotIsWorn()
	{
		final Set<TravelItem> used = EnumSet.of(TravelItem.RING_OF_WEALTH, TravelItem.SLAYER_RING,
			TravelItem.ARDOUGNE_CLOAK, TravelItem.ECTOPHIAL);
		final Map<Holdings.Source, Map<Integer, Integer>> items = new EnumMap<>(Holdings.Source.class);
		// Already wearing the slayer ring: that's the ring to keep on
		items.put(Holdings.Source.WORN, of(ItemID.SLAYER_RING_8, 1));
		final Set<TravelItem> worn = SupplyCalculator.toWear(used, Outfit.NONE, holdings(items));
		assertEquals(EnumSet.of(TravelItem.SLAYER_RING, TravelItem.ARDOUGNE_CLOAK), worn);
		// Graceful takes the cape slot, so the cloak goes in the inventory
		assertFalse(SupplyCalculator.toWear(used, Outfit.GRACEFUL, holdings(items)).contains(TravelItem.ARDOUGNE_CLOAK));
	}
}

package com.farmrunautopilot.supply;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.farmrunautopilot.access.AccessSnapshot;
import com.farmrunautopilot.data.AchievementDiary;
import com.farmrunautopilot.data.Crop;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.PatchState;
import com.farmrunautopilot.data.PatchType;
import com.farmrunautopilot.data.travel.Rune;
import com.farmrunautopilot.route.Route;
import com.farmrunautopilot.route.RoutePlanner;
import com.farmrunautopilot.route.RunSelection;
import com.farmrunautopilot.route.RunSelector;
import com.farmrunautopilot.settings.Compost;
import com.farmrunautopilot.settings.PohSetup;
import com.farmrunautopilot.settings.RunConfig;
import com.farmrunautopilot.tracking.PatchPrediction;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class SupplyCalculatorTest
{
	private static final long NOW = 1_700_000_000L;
	private static final Function<Patch, PatchPrediction> NEVER_SEEN = p -> null;

	private static Holdings holdings(Map<Integer, Integer> bank, Set<Rune> infinite)
	{
		final Map<Holdings.Source, Map<Integer, Integer>> items = new EnumMap<>(Holdings.Source.class);
		items.put(Holdings.Source.BANK, bank);
		return new Holdings(items, Collections.emptyMap(), infinite, true, false);
	}

	private static RunConfig onlyType(PatchType type)
	{
		final RunConfig config = new RunConfig();
		config.setEnabledTypes(EnumSet.of(type));
		return config.sanitise();
	}

	private static SupplyPlan plan(RunConfig config, AccessSnapshot access, Holdings holdings,
		Function<Patch, PatchPrediction> predictions, boolean fullRun)
	{
		final RunSelection selection = RunSelector.select(config, access, predictions, NOW, fullRun,
			Collections.emptyMap());
		final Route route = RoutePlanner.plan(selection.getPatches(), config, access, holdings, new PohSetup());
		return SupplyCalculator.calculate(config, access, holdings, selection, route, predictions, id -> "item " + id,
			id -> 0);
	}

	private static SupplyLine find(SupplyPlan plan, String name)
	{
		for (SupplyLine line : plan.getLines())
		{
			if (line.getName().equals(name))
			{
				return line;
			}
		}
		return null;
	}

	private static PatchPrediction prediction(Patch patch, PatchState state)
	{
		return new PatchPrediction(patch, null, state, 0, 1, 0, NOW, 0, PatchPrediction.Source.THIS_PLUGIN);
	}

	@Test
	public void noPlantCureWhenEveryPatchIsDiseaseFree()
	{
		final RunConfig config = onlyType(PatchType.HERB);
		config.setPlantCureDoses(1);
		for (Patch patch : Patch.values())
		{
			if (patch != Patch.TROLL_STRONGHOLD_HERB)
			{
				config.getDisabledPatches().add(patch);
			}
		}
		final SupplyPlan safe = plan(config, AccessSnapshot.UNKNOWN, holdings(new HashMap<>(), Collections.emptySet()),
			NEVER_SEEN, true);
		assertEquals(1, safe.patchTotal());
		assertNull(find(safe, "Plant cure"));

		config.getDisabledPatches().remove(Patch.ARDOUGNE_HERB);
		final SupplyPlan atRisk = plan(config, AccessSnapshot.UNKNOWN, holdings(new HashMap<>(), Collections.emptySet()),
			NEVER_SEEN, true);
		assertNotNull(find(atRisk, "Plant cure"));
	}

	@Test
	public void herbRun()
	{
		final Map<Integer, Integer> bank = new HashMap<>();
		bank.put(ItemID.TORSTOL_SEED, 4);
		bank.put(ItemID.BUCKET_ULTRACOMPOST, 12);
		bank.put(ItemID.SPADE, 1);
		final SupplyPlan plan = plan(onlyType(PatchType.HERB), AccessSnapshot.UNKNOWN,
			holdings(bank, Collections.emptySet()), NEVER_SEEN, false);

		assertEquals(10, plan.patchTotal());
		// Unknown Farming level: highest herb.
		final SupplyLine seeds = find(plan, "item " + ItemID.TORSTOL_SEED);
		assertNotNull(seeds);
		assertEquals(10, seeds.getNeed());
		assertEquals(4, seeds.getHave());
		assertFalse(seeds.isMet());
		assertEquals(1, seeds.getSlots());

		final SupplyLine compost = find(plan, Compost.ULTRACOMPOST.getDisplayName());
		assertEquals(10, compost.getNeed());
		assertTrue(compost.isMet());

		assertTrue(find(plan, "Spade").isMet());
		assertNotNull(find(plan, "Seed dibber"));
