import org.junit.Test;

public class PatchStatusTextTest
{
	private static final long NOW = 1_700_000_000L;

	private static PatchPrediction prediction(Patch patch, Crop crop, PatchState state, int stage, int stages,
		long doneAt)
	{
		return new PatchPrediction(patch, crop, state, stage, stages, doneAt, NOW, 0,
			PatchPrediction.Source.THIS_PLUGIN);
	}

	@Test
	public void durations()
	{
		assertEquals("<1m", PatchStatusText.duration(0));
		assertEquals("<1m", PatchStatusText.duration(59));
		assertEquals("1m", PatchStatusText.duration(60));
		assertEquals("1h 00m", PatchStatusText.duration(3600));
		assertEquals("2h 05m", PatchStatusText.duration(7500));
	}

	@Test
	public void descriptions()
	{
		assertEquals("Not seen yet", PatchStatusText.describe(null, NOW));
		assertEquals("Ranarr - ready in 34m", PatchStatusText.describe(
			prediction(Patch.CATHERBY_HERB, Crop.RANARR, PatchState.GROWING, 2, 5, NOW + 34 * 60), NOW));
		assertEquals("Ranarr - ready to pick", PatchStatusText.describe(
			prediction(Patch.CATHERBY_HERB, Crop.RANARR, PatchState.HARVESTABLE, 2, 5, 0), NOW));
		assertEquals("Magic - check health", PatchStatusText.describe(
			prediction(Patch.TAVERLEY_TREE, Crop.MAGIC, PatchState.CHECK_HEALTH, 12, 13, 0), NOW));
		assertEquals("Magic - grown, ready to clear", PatchStatusText.describe(
			prediction(Patch.TAVERLEY_TREE, Crop.MAGIC, PatchState.HARVESTABLE, 0, 1, 0), NOW));
		assertEquals("Palm - 3 fruit (full in 2h 15m)", PatchStatusText.describe(
			prediction(Patch.BRIMHAVEN_FRUIT_TREE, Crop.PALM, PatchState.HARVESTABLE, 3, 7, NOW + 135 * 60), NOW));
		assertEquals("Palm - 6 fruit", PatchStatusText.describe(
			prediction(Patch.BRIMHAVEN_FRUIT_TREE, Crop.PALM, PatchState.HARVESTABLE, 6, 7, NOW - 60), NOW));
		assertEquals("Dead herb", PatchStatusText.describe(
			prediction(Patch.CATHERBY_HERB, null, PatchState.DEAD, 1, 1, 0), NOW));
		assertEquals("Empty", PatchStatusText.describe(
			prediction(Patch.CATHERBY_HERB, null, PatchState.EMPTY, 0, 4, 0), NOW));
	}
}

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.GZIPOutputStream;

/**
 * One-off (Sprint 8): for each stop, walking tiles from its patches out to MAX tiles on Shortest Path's collision
 * map, kept per BLOCKxBLOCK block (the smallest in the block), plane 0. Written as a gzip file the plugin reads:
 * int count; then per stop: UTF location name, int blockX0, int blockY0, int width, int height, width*height
 * unsigned bytes (tiles / 1, 255 = not within MAX).
 * Usage: java Grid collision-map.zip patches.tsv out.bin
 */
public class Grid
{
	static final int MAX = 150, BLOCK = 4;

	/** Doors and gates anyone can use: ground floor, a step or two, no skills, items, quests or varbits. */
	static Map<Long, List<Long>> doors(Path transports) throws IOException
	{
		final Map<Long, List<Long>> doors = new HashMap<>();
		for (String line : Files.readAllLines(transports))
		{
			if (line.startsWith("#") || line.isBlank()) continue;
			final String[] r = line.split("	", -1);
			if (r.length < 8 || !r[3].isEmpty() || !r[4].isEmpty() || !r[5].isEmpty() || !r[6].isEmpty() || !r[7].isEmpty()) continue;
			final String[] a = r[0].trim().split(" "), b = r[1].trim().split(" ");
			if (a.length < 3 || b.length < 3 || !a[2].equals("0") || !b[2].equals("0")) continue;
			final int ax = Integer.parseInt(a[0]), ay = Integer.parseInt(a[1]), bx = Integer.parseInt(b[0]), by = Integer.parseInt(b[1]);
			if (Math.abs(ax - bx) + Math.abs(ay - by) > 3) continue;
			doors.computeIfAbsent(Walk.key(ax, ay), k -> new ArrayList<>()).add(Walk.key(bx, by));
		}
		return doors;
	}

	public static void main(String[] args) throws Exception
	{
		Walk.main(new String[]{args[0]});
		final Map<Long, List<Long>> doors = doors(Paths.get(args[0]).getParent().resolve("transports").resolve("transports.tsv"));
		System.out.println(doors.size() + " door and gate tiles");
		final Map<String, List<int[]>> patches = new LinkedHashMap<>();
		final List<String> lines = Files.readAllLines(Paths.get(args[1]));
		for (String line : lines.subList(1, lines.size()))
		{
			final String[] r = line.split("\t", -1);
			if (Integer.parseInt(r[4]) != 0) continue;
			patches.computeIfAbsent(r[1], k -> new ArrayList<>()).add(new int[]{Integer.parseInt(r[2]), Integer.parseInt(r[3])});
		}
		try (DataOutputStream out = new DataOutputStream(new GZIPOutputStream(new FileOutputStream(args[2]))))
		{
			out.writeInt(patches.size());
			for (Map.Entry<String, List<int[]>> e : patches.entrySet())
			{
				final Map<Long, Integer> dist = new HashMap<>();
				final ArrayDeque<Long> q = new ArrayDeque<>();
				for (int[] p : e.getValue())
					for (long k : Measure.aroundPatch(p[0], p[1], 0)) { dist.put(k, 0); q.add(k); }
				while (!q.isEmpty())
				{
					final long k = q.poll();
					final int d = dist.get(k);
					if (d >= MAX) continue;
					final int x = (int) (k >> 32), y = (int) k, z = 0;
					Measure.step(q, dist, x, y + 1, d, Walk.n(x, y, z));
					Measure.step(q, dist, x, y - 1, d, Walk.s(x, y, z));
					Measure.step(q, dist, x + 1, y, d, Walk.e(x, y, z));
					Measure.step(q, dist, x - 1, y, d, Walk.w(x, y, z));
					Measure.step(q, dist, x + 1, y + 1, d, Walk.n(x, y, z) && Walk.e(x, y + 1, z) && Walk.e(x, y, z) && Walk.n(x + 1, y, z));
					Measure.step(q, dist, x - 1, y + 1, d, Walk.n(x, y, z) && Walk.w(x, y + 1, z) && Walk.w(x, y, z) && Walk.n(x - 1, y, z));
					Measure.step(q, dist, x + 1, y - 1, d, Walk.s(x, y, z) && Walk.e(x, y - 1, z) && Walk.e(x, y, z) && Walk.s(x + 1, y, z));
					Measure.step(q, dist, x - 1, y - 1, d, Walk.s(x, y, z) && Walk.w(x, y - 1, z) && Walk.w(x, y, z) && Walk.s(x - 1, y, z));
					for (long to : doors.getOrDefault(k, Collections.emptyList()))
					{
						if (!dist.containsKey(to)) { dist.put(to, d + 1); q.add(to); }
					}
				}
				int minX = Integer.MAX_VALUE, minY = Integer.MAX_VALUE, maxX = Integer.MIN_VALUE, maxY = Integer.MIN_VALUE;
				for (long k : dist.keySet())
				{
					final int bx = Math.floorDiv((int) (k >> 32), BLOCK), by = Math.floorDiv((int) k, BLOCK);
					minX = Math.min(minX, bx); minY = Math.min(minY, by); maxX = Math.max(maxX, bx); maxY = Math.max(maxY, by);
				}
				final int w = maxX - minX + 1, h = maxY - minY + 1;
				final byte[] grid = new byte[w * h];
				Arrays.fill(grid, (byte) 255);
				for (Map.Entry<Long, Integer> d : dist.entrySet())
				{
					final int bx = Math.floorDiv((int) (d.getKey() >> 32), BLOCK) - minX, by = Math.floorDiv((int) (long) d.getKey(), BLOCK) - minY;
					final int i = by * w + bx;
					if ((grid[i] & 0xff) > d.getValue()) grid[i] = (byte) (int) d.getValue();
				}
				out.writeUTF(e.getKey());
				out.writeInt(minX); out.writeInt(minY); out.writeInt(w); out.writeInt(h);
				out.write(grid);
				System.out.println(e.getKey() + ": " + dist.size() + " tiles, " + w + "x" + h + " blocks");
			}
		}
	}
}

import java.io.*;
import java.nio.file.*;
import java.util.*;

/**
 * One-off (Sprint 8): walking tiles on Shortest Path's collision map from each landing to the nearest patch of
 * its stop, each patch to its bank, spirit tree, quetzal pad and fairy ring, and a few named walks.
 * Usage: java Measure collision-map.zip sp8-dir
 */
public class Measure
{
	static final int MAX = 3000;

	/** Patches: object tile; a player stands next to it, so any walkable tile in [x-1, x+3] x [y-1, y+3]. */
	static Set<Long> aroundPatch(int x, int y, int z)
	{
		final Set<Long> t = new HashSet<>();
		for (int dx = -1; dx <= 3; dx++) for (int dy = -1; dy <= 3; dy++)
			if (!Walk.blocked(x + dx, y + dy, z)) t.add(Walk.key(x + dx, y + dy));
		return t;
	}

	/** Objects you use (booth, tree, ring, pad): walkable tiles within 2. */
	static Set<Long> around(int x, int y, int z, int r)
	{
		final Set<Long> t = new HashSet<>();
		for (int dx = -r; dx <= r; dx++) for (int dy = -r; dy <= r; dy++)
			if (!Walk.blocked(x + dx, y + dy, z)) t.add(Walk.key(x + dx, y + dy));
		return t;
	}

	static int bfs(Set<Long> from, Set<Long> to, int z)
	{
		if (from.isEmpty() || to.isEmpty()) return -2;
		final Map<Long, Integer> dist = new HashMap<>();
		final ArrayDeque<Long> q = new ArrayDeque<>();
		for (long k : from) { dist.put(k, 0); q.add(k); }
		while (!q.isEmpty())
		{
			final long k = q.poll();
			final int d = dist.get(k);
			if (to.contains(k)) return d;
			if (d > MAX) return -1;
			final int x = (int) (k >> 32), y = (int) k;
			step(q, dist, x, y + 1, d, Walk.n(x, y, z));
			step(q, dist, x, y - 1, d, Walk.s(x, y, z));
			step(q, dist, x + 1, y, d, Walk.e(x, y, z));
			step(q, dist, x - 1, y, d, Walk.w(x, y, z));
			step(q, dist, x + 1, y + 1, d, Walk.n(x, y, z) && Walk.e(x, y + 1, z) && Walk.e(x, y, z) && Walk.n(x + 1, y, z));
			step(q, dist, x - 1, y + 1, d, Walk.n(x, y, z) && Walk.w(x, y + 1, z) && Walk.w(x, y, z) && Walk.n(x - 1, y, z));
			step(q, dist, x + 1, y - 1, d, Walk.s(x, y, z) && Walk.e(x, y - 1, z) && Walk.e(x, y, z) && Walk.s(x + 1, y, z));
			step(q, dist, x - 1, y - 1, d, Walk.s(x, y, z) && Walk.w(x, y - 1, z) && Walk.w(x, y, z) && Walk.s(x - 1, y, z));
		}
		return -1;
	}

	static void step(ArrayDeque<Long> q, Map<Long, Integer> dist, int x, int y, int d, boolean ok)
	{
		final long k = Walk.key(x, y);
		if (ok && !dist.containsKey(k)) { dist.put(k, d + 1); q.add(k); }
	}

	static List<String[]> tsv(Path p) throws IOException
	{
		final List<String[]> rows = new ArrayList<>();
		for (String line : Files.readAllLines(p))
		{
			if (line.startsWith("#") || line.isBlank()) continue;
			rows.add(line.split("\t", -1));
		}
		return rows.subList(1, rows.size());
	}

	public static void main(String[] args) throws Exception
	{
		Walk.main(new String[]{args[0]});
		final Path dir = Paths.get(args[1]);
		// location -> patch tiles
		final Map<String, List<int[]>> patches = new LinkedHashMap<>();
		final Map<String, int[]> patchByName = new LinkedHashMap<>();
		for (String[] r : tsv(dir.resolve("patches.tsv")))
		{
			final int[] t = {Integer.parseInt(r[2]), Integer.parseInt(r[3]), Integer.parseInt(r[4])};
			patches.computeIfAbsent(r[1], k -> new ArrayList<>()).add(t);
			patchByName.put(r[0], t);
		}
		System.out.println("== landing -> nearest patch of its stop");
		for (String[] r : tsv(dir.resolve("methods.tsv")))
		{
			final int x = Integer.parseInt(r[2]), y = Integer.parseInt(r[3]), z = Integer.parseInt(r[4]);
			Set<Long> to = new HashSet<>();
			for (int[] p : patches.getOrDefault(r[1], Collections.emptyList())) if (p[2] == z) to.addAll(aroundPatch(p[0], p[1], z));
			System.out.println("M\t" + r[0] + "\t" + bfs(around(x, y, z, 1), to, z));
		}
		System.out.println("== patch -> bank");
		for (String[] r : tsv(dir.resolve("banks.tsv")))
		{
			final int bx = Integer.parseInt(r[1]), by = Integer.parseInt(r[2]), bz = Integer.parseInt(r[3]);
			for (Map.Entry<String, int[]> e : patchByName.entrySet())
			{
				final int[] p = e.getValue();
				if (!patchLocation(dir, e.getKey()).equals(r[0])) continue;
				System.out.println("B\t" + r[0] + "\t" + e.getKey() + "\t" + (p[2] != bz ? "plane" : bfs(aroundPatch(p[0], p[1], p[2]), around(bx, by, bz, 1), bz)));
			}
		}
		System.out.println("== patch -> extras (tree, ring, pad, balloon)");
		for (String[] r : tsv(dir.resolve("extras.tsv")))
		{
			final int ex = Integer.parseInt(r[3]), ey = Integer.parseInt(r[4]), ez = Integer.parseInt(r[5]);
			for (Map.Entry<String, int[]> e : patchByName.entrySet())
			{
				if (!patchLocation(dir, e.getKey()).equals(r[1])) continue;
				final int[] p = e.getValue();
				System.out.println("X\t" + r[0] + "\t" + r[2] + "\t" + e.getKey() + "\t" + (p[2] != ez ? "plane" : bfs(aroundPatch(p[0], p[1], p[2]), around(ex, ey, ez, 2), ez)));
			}
		}
		System.out.println("== named walks");
		for (int i = 2; i + 6 < args.length; i += 7)
		{
			final int z = 0;
			System.out.println("W\t" + args[i] + "\t" + bfs(around(Integer.parseInt(args[i + 1]), Integer.parseInt(args[i + 2]), z, Integer.parseInt(args[i + 5])),
				around(Integer.parseInt(args[i + 3]), Integer.parseInt(args[i + 4]), z, Integer.parseInt(args[i + 6])), z));
		}
	}

	static Map<String, String> locs;
	static String patchLocation(Path dir, String patch) throws IOException
	{
		if (locs == null)
		{
			locs = new HashMap<>();
			for (String[] r : tsv(dir.resolve("patches.tsv"))) locs.put(r[0], r[1]);
		}
		return locs.getOrDefault(patch, "");
	}
}

import java.io.*;
import java.util.*;
import java.util.zip.*;

/** One-off: walking tiles between points on Shortest Path's collision map (BFS, 8 directions, game diagonal rules). */
public class Walk
{
	static final int R = 64, FLAGS = 4, PER_PLANE = R * R * FLAGS;
	static final Map<Long, BitSet> regions = new HashMap<>();

	static boolean get(int x, int y, int z, int flag)
	{
		final BitSet b = regions.get(((long) (x / R) << 32) | (y / R));
		if (b == null) return false;
		return b.get(z * PER_PLANE + ((y % R) * R + (x % R)) * FLAGS + flag);
	}
	static boolean n(int x, int y, int z) { return get(x, y, z, 0); }
	static boolean e(int x, int y, int z) { return get(x, y, z, 1); }
	static boolean s(int x, int y, int z) { return n(x, y - 1, z); }
	static boolean w(int x, int y, int z) { return e(x - 1, y, z); }
	static boolean blocked(int x, int y, int z) { return !n(x, y, z) && !s(x, y, z) && !e(x, y, z) && !w(x, y, z); }

	/** Steps from any walkable tile within `near` of (sx,sy) to any within `near` of (tx,ty). */
	static int walk(int sx, int sy, int tx, int ty, int z, int near)
	{
		final Map<Long, Integer> dist = new HashMap<>();
		final ArrayDeque<int[]> q = new ArrayDeque<>();
		for (int dx = -near; dx <= near; dx++) for (int dy = -near; dy <= near; dy++)
			if (!blocked(sx + dx, sy + dy, z)) { dist.put(key(sx + dx, sy + dy), 0); q.add(new int[]{sx + dx, sy + dy}); }
		while (!q.isEmpty())
		{
			final int[] p = q.poll();
			final int x = p[0], y = p[1], d = dist.get(key(x, y));
			if (Math.abs(x - tx) <= near && Math.abs(y - ty) <= near && !blocked(x, y, z)) return d;
			if (d > 2000) break;
			step(q, dist, x, y + 1, d, n(x, y, z));
			step(q, dist, x, y - 1, d, s(x, y, z));
			step(q, dist, x + 1, y, d, e(x, y, z));
			step(q, dist, x - 1, y, d, w(x, y, z));
			step(q, dist, x + 1, y + 1, d, n(x, y, z) && e(x, y + 1, z) && e(x, y, z) && n(x + 1, y, z));
			step(q, dist, x - 1, y + 1, d, n(x, y, z) && w(x, y + 1, z) && w(x, y, z) && n(x - 1, y, z));
			step(q, dist, x + 1, y - 1, d, s(x, y, z) && e(x, y - 1, z) && e(x, y, z) && s(x + 1, y, z));
			step(q, dist, x - 1, y - 1, d, s(x, y, z) && w(x, y - 1, z) && w(x, y, z) && s(x - 1, y, z));
		}
		return -1;
	}
	static void step(ArrayDeque<int[]> q, Map<Long, Integer> dist, int x, int y, int d, boolean ok)
	{
		if (ok && !dist.containsKey(key(x, y))) { dist.put(key(x, y), d + 1); q.add(new int[]{x, y}); }
	}
	static long key(int x, int y) { return ((long) x << 32) | (y & 0xffffffffL); }

	public static void main(String[] args) throws Exception
	{
		try (ZipInputStream in = new ZipInputStream(new FileInputStream(args[0])))
		{
			ZipEntry entry;
			while ((entry = in.getNextEntry()) != null)
			{
				final String[] n = entry.getName().split("_");
				final ByteArrayOutputStream out = new ByteArrayOutputStream();
				in.transferTo(out);
				regions.put(((long) Integer.parseInt(n[0]) << 32) | Integer.parseInt(n[1]), BitSet.valueOf(out.toByteArray()));
			}
		}
		for (int i = 1; i + 5 < args.length; i += 6)
		{
			final String name = args[i];
			final int d = walk(Integer.parseInt(args[i + 1]), Integer.parseInt(args[i + 2]), Integer.parseInt(args[i + 3]),
				Integer.parseInt(args[i + 4]), 0, Integer.parseInt(args[i + 5]));
			System.out.println(name + ": " + (d < 0 ? "no path" : d + " tiles (" + Math.round(d * 0.3) + " s running)"));
		}
	}
}
